cd /workspace && python3 << 'EOF'
import json
d = json.load(open('contracts/openapi.contract.json'))
paths = d['paths']
out = []
for p, ops in paths.items():
    for m, op in ops.items():
        out.append('='*70)
        out.append(f'{m.upper()} {p}  [{op.get("operationId")}]')
        out.append('summary: ' + str(op.get('summary','')))
        if op.get('parameters'):
            out.append('params: ' + json.dumps(op['parameters']))
        rb = op.get('requestBody')
        if rb:
            for ct, content in rb.get('content', {}).items():
                out.append(f'request({ct}): ' + json.dumps(content.get('schema')))
        for code, resp in op.get('responses', {}).items():
            desc = resp.get('description','')
            for ct, content in resp.get('content', {}).items():
                out.append(f'  {code} ({ct}) {desc}: ' + json.dumps(content.get('schema')))
            if not resp.get('content'):
                out.append(f'  {code} {desc}')
open('/tmp/paths_compact.txt','w').write('\n'.join(out))
print('lines:', len(out))
EOF
wc -l /tmp/paths_compact.txt

