package main

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"net/http"
	"strings"
	"time"

	"github.com/jackc/pgx/v5"
	"golang.org/x/crypto/bcrypt"
)

type session struct {
	Token      string
	User       *User
	ActiveRole string
}

func (s *server) requireAuth(w http.ResponseWriter, r *http.Request) (*session, *apiError) {
	auth := r.Header.Get("Authorization")
	if !strings.HasPrefix(auth, "Bearer ") {
		return nil, errOf(401, "unauthorized", "missing bearer [REDACTED]")
	}
	token := strings.TrimSpace(strings.TrimPrefix(auth, "Bearer "))
	if token == "" {
		return nil, errOf(401, "unauthorized", "missing bearer [REDACTED]")
	}
	sess, err := s.loadSession(r.Context(), token)
	if err != nil {
		return nil, errOf(401, "unauthorized", "session is not valid")
	}
	return sess, nil
}

func (s *server) loadSession(ctx context.Context, token string) (*session, error) {
	var userID, activeRole string
	var expires time.Time
	err := s.db.QueryRow(ctx, `SELECT user_id, active_role, expires_at FROM sessions WHERE token=$1`, token).
		Scan(&userID, &activeRole, &expires)
	if err != nil {
		return nil, err
	}
	if time.Now().After(expires) {
		return nil, errors.New("session expired")
	}
	u, err := loadUser(ctx, s.db, userID)
	if err != nil {
		return nil, err
	}
	if !u.Active {
		return nil, errors.New("user inactive")
	}
	return &session{Token: token, User: u, ActiveRole: activeRole}, nil
}

// requireRole enforces that the session has selected one of the allowed roles.
func requireRole(sess *session, roles ...string) *apiError {
	if sess.ActiveRole == "" {
		return errOf(409, "role_not_selected", "select an active role before performing this action")
	}
	for _, r := range roles {
		if sess.ActiveRole == r {
			return nil
		}
	}
	return errOf(403, "forbidden", "the selected role may not perform this action")
}

// ---------- audit & events ----------

func (s *server) audit(ctx context.Context, sess *session, action, entityType, entityID string, success bool, details map[string]any) {
	if details == nil {
		details = map[string]any{}
	}
	actorID, role := "", ""
	if sess != nil {
		actorID = sess.User.UserID
		role = sess.ActiveRole
	}
	d, _ := json.Marshal(details)
	_, _ = s.db.Exec(ctx, `INSERT INTO audit_entries (audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		newUUID(), actorID, role, action, entityType, entityID, success, nowUTC(), d)
}

func (s *server) emit(ctx context.Context, evType, entityType, entityID string, payload map[string]any, audienceRole, audienceUserID string) {
	if payload == nil {
		payload = map[string]any{}
	}
	p, _ := json.Marshal(payload)
	var id int64
	var createdAt time.Time
	err := s.db.QueryRow(ctx, `INSERT INTO events (type, entity_type, entity_id, payload, audience_role, audience_user_id, created_at)
		VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING id, created_at`,
		evType, entityType, entityID, p, audienceRole, audienceUserID, nowUTC()).Scan(&id, &createdAt)
	if err != nil {
		return
	}
	s.hub.broadcast(&RealtimeEvent{
		ID:         id,
		Type:       evType,
		EntityType: entityType,
		EntityID:   entityID,
		Payload:    payload,
		CreatedAt:  fmtTime(createdAt),
		AudienceRole:   audienceRole,
		AudienceUserID: audienceUserID,
	})
}

// setSampleStatus changes a sample's status, recording timeline + audit + event.
func (s *server) setSampleStatus(ctx context.Context, sess *session, sampleID, status string, details map[string]any) {
	_, _ = s.db.Exec(ctx, `UPDATE samples SET status=$2, updated_at=now() WHERE sample_id=$1`, sampleID, status)
	if details == nil {
		details = map[string]any{}
	}
	details["status"] = status
	s.audit(ctx, sess, "status_change", "sample", sampleID, true, details)
	s.emit(ctx, "sample_status", "sample", sampleID, map[string]any{"sampleId": sampleID, "status": status}, "", "")
}

// ---------- idempotency ----------

// idempotent runs fn unless the key was already used by this user for this action.
// fn returns (httpStatus, dataPayload, apiError). Successful and client-error
// responses are stored and replayed.
func (s *server) idempotent(w http.ResponseWriter, r *http.Request, sess *session, action, key string, body []byte, fn func() (int, any, *apiError)) {
	if key == "" {
		writeErr(w, errOf(400, "idempotency_required", "idempotencyKey is required"))
		return
	}
	hash := sha256.Sum256(body)
	hashHex := hex.EncodeToString(hash[:])
	var storedHash string
	var status int
	var response []byte
	err := s.db.QueryRow(r.Context(), `SELECT request_hash, status, response FROM idempotency_keys
		WHERE key=$1 AND user_id=$2 AND action=$3`, key, sess.User.UserID, action).Scan(&storedHash, &status, &response)
	if err == nil {
		if storedHash != hashHex {
			writeErr(w, errOf(409, "idempotency_conflict", "idempotencyKey was already used with a different request"))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write(response)
		return
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	st, data, aerr := fn()
	var respBody []byte
	if aerr != nil {
		respBody, _ = json.Marshal(map[string]any{"error": aerr.Message, "code": aerr.Code})
	} else {
		respBody, _ = json.Marshal(map[string]any{"data": data})
	}
	if st < 500 {
		_, _ = s.db.Exec(r.Context(), `INSERT INTO idempotency_keys (key, user_id, action, request_hash, status, response)
			VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT (key, user_id, action) DO NOTHING`,
			key, sess.User.UserID, action, hashHex, st, respBody)
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(st)
	_, _ = w.Write(respBody)
}

// ---------- auth handlers ----------

func (s *server) handleAuthenticate(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	ctx := r.Context()
	u, err := loadUserByName(ctx, s.db, body.Username)
	if err != nil || !u.Active {
		s.audit(ctx, nil, "sign_in", "user", "", false, map[string]any{"username": body.Username, "reason": "invalid_credentials"})
		writeErr(w, errOf(401, "invalid_credentials", "username or password is incorrect"))
		return
	}
	if bcrypt.CompareHashAndPassword([]byte(u.PasswordHash), []byte(body.Password)) != nil {
		s.audit(ctx, nil, "sign_in", "user", u.UserID, false, map[string]any{"username": body.Username, "reason": "invalid_credentials"})
		writeErr(w, errOf(401, "invalid_credentials", "username or password is incorrect"))
		return
	}
	token := randomToken()
	activeRole := ""
	if len(u.Roles) == 1 {
		activeRole = u.Roles[0]
	}
	_, err = s.db.Exec(ctx, `INSERT INTO sessions (token, user_id, active_role, expires_at) VALUES ($1,$2,$3,$4)`,
		token, u.UserID, activeRole, nowUTC().Add(24*time.Hour))
	if err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	sess := &session{Token: token, User: u, ActiveRole: activeRole}
	s.audit(ctx, sess, "sign_in", "user", u.UserID, true, map[string]any{"username": u.Username})
	writeData(w, 200, map[string]any{
		"sessionToken": token,
		"userId":       u.UserID,
		"roles":        u.Roles,
		"activeRole":   activeRole,
	})
}

func (s *server) handleSelectRole(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		Role string `json:"role"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	role := normalizeRole(body.Role)
	if !containsString(validRoles, role) {
		writeErr(w, errOf(400, "invalid_role", "role is not a known role"))
		return
	}
	if !containsString(sess.User.Roles, role) {
		writeErr(w, errOf(403, "role_not_held", "the account does not hold this role"))
		return
	}
	if _, err := s.db.Exec(r.Context(), `UPDATE sessions SET active_role=$2 WHERE token=$1`, sess.Token, role); err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	sess.ActiveRole = role
	s.audit(r.Context(), sess, "select_role", "user", sess.User.UserID, true, map[string]any{"role": role})
	writeData(w, 200, map[string]any{"activeRole": role, "roles": sess.User.Roles})
}

// ---------- user administration ----------

func publicUser(u *User) map[string]any {
	certs := []map[string]any{}
	for _, c := range u.Certifications {
		entry := map[string]any{
			"code":   c["code"],
			"active": c["active"],
		}
		if exp, ok := c["expiresAt"]; ok {
			entry["expiresAt"] = exp
		} else if exp, ok := c["expires_at"]; ok {
			entry["expiresAt"] = exp
		}
		certs = append(certs, entry)
	}
	return map[string]any{
		"userId":         u.UserID,
		"username":       u.Username,
		"email":          u.Email,
		"fullName":       u.FullName,
		"phone":          u.Phone,
		"roles":          u.Roles,
		"qualifications": u.Qualifications,
		"certifications": certs,
		"active":         u.Active,
	}
}

func validateCerts(certs []map[string]any) bool {
	for _, c := range certs {
		code, _ := c["code"].(string)
		if code == "" {
			return false
		}
		if _, ok := c["active"].(bool); !ok {
			return false
		}
		if exp, ok := c["expiresAt"]; ok {
			s, _ := exp.(string)
			if s != "" {
				if _, ok := parseTime(s); !ok {
					return false
				}
			}
		}
	}
	return true
}

func (s *server) handleCreateUser(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		Username           string           `json:"username"`
		InitialPassword    string           `json:"initialPassword"`
		Email              string           `json:"email"`
		FullName           string           `json:"fullName"`
		Phone              string           `json:"phone"`
		Roles              []string         `json:"roles"`
		Qualifications     []string         `json:"qualifications"`
		Certifications     []map[string]any `json:"certifications"`
		Active             *bool            `json:"active"`
		AssignedLocationID string           `json:"assignedLocationId"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	if body.Username == "" || body.InitialPassword == "" || len(body.Roles) == 0 || body.Active == nil {
		writeErr(webadRequest(w, r, sess, "create_user", errOf(400, "invalid_user", "username, initialPassword, roles and active are required")))
		return
	}
	roles := []string{}
	for _, role := range body.Roles {
		role = normalizeRole(role)
		if !containsString(validRoles, role) {
			writeErr(webadRequest(w, r, sess, "create_user", errOf(400, "invalid_user", "unknown role: "+role)))
			return
		}
		roles = append(roles, role)
	}
	if body.Certifications == nil {
		body.Certifications = []map[string]any{}
	}
	if !validateCerts(body.Certifications) {
		writeErr(webadRequest(w, r, sess, "create_user", errOf(400, "invalid_certification", "certifications must include code and active")))
		return
	}
	var assigned *string
	if body.AssignedLocationID != "" {
		if !isUUID(body.AssignedLocationID) {
			writeErr(webadRequest(w, r, sess, "create_user", errOf(400, "invalid_user", "assignedLocationId must be a uuid")))
			return
		}
		if _, err := loadLocation(r.Context(), s.db, body.AssignedLocationID); err != nil {
			writeErr(webadRequest(w, r, sess, "create_user", errOf(400, "invalid_user", "assignedLocationId does not reference a location")))
			return
		}
		assigned = &body.AssignedLocationID
	}
	hash, _ := bcrypt.GenerateFromPassword([]byte(body.InitialPassword), bcrypt.DefaultCost)
	userID := newUUID()
	rolesJSON, _ := json.Marshal(roles)
	qualsJSON, _ := json.Marshal(body.Qualifications)
	if body.Qualifications == nil {
		qualsJSON = []byte("[]")
	}
