func (s *server) handleUpdateUserAccess(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		UserID             string           `json:"userId"`
		Roles              []string         `json:"roles"`
		Qualifications     []string         `json:"qualifications"`
		Certifications     []map[string]any `json:"certifications"`
		Active             *bool            `json:"active"`
		AssignedLocationID *string          `json:"assignedLocationId"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	if body.UserID == "" || body.Active == nil {
		writeErr(w, errOf(400, "invalid_json", "userId, roles and active are required"))
		return
	}
	u, err := loadUser(r.Context(), s.db, body.UserID)
	if err != nil {
		writeErr(w, errOf(404, "not_found", "user not found"))
		return
	}
	roles := []string{}
	for _, role := range body.Roles {
		role = normalizeRole(role)
		if !containsString(validRoles, role) {
			writeErr(w, errOf(400, "invalid_json", "unknown role: "+role))
			return
		}
		roles = append(roles, role)
	}
	if body.Certifications != nil && !validateCerts(body.Certifications) {
		writeErr(w, errOf(400, "invalid_certification", "certifications must include code and active"))
		return
	}
	rolesJSON, _ := json.Marshal(roles)
	if body.Qualifications == nil {
		body.Qualifications = u.Qualifications
	}
	qualsJSON, _ := json.Marshal(body.Qualifications)
	var certsJSON []byte
	if body.Certifications == nil {
		certsJSON, _ = json.Marshal(u.Certifications)
	} else {
		certsJSON, _ = json.Marshal(body.Certifications)
	}
	assigned := u.AssignedLocationID
	if body.AssignedLocationID != nil {
		if *body.AssignedLocationID == "" {
			assigned = nil
		} else {
			if !isUUID(*body.AssignedLocationID) {
				writeErr(w, errOf(400, "invalid_json", "assignedLocationId must be a uuid"))
				return
			}
			if _, err := loadLocation(r.Context(), s.db, *body.AssignedLocationID); err != nil {
				writeErr(w, errOf(400, "invalid_json", "assignedLocationId does not reference a location"))
				return
			}
			assigned = body.AssignedLocationID
		}
	}
	_, err = s.db.Exec(r.Context(), `UPDATE users SET roles=$2, qualifications=$3, certifications=$4, active=$5, assigned_location_id=$6
		WHERE user_id=$1`, body.UserID, rolesJSON, qualsJSON, certsJSON, *body.Active, assigned)
	if err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	u, _ = loadUser(r.Context(), s.db, body.UserID)
	s.audit(r.Context(), sess, "update_user_access", "user", body.UserID, true, map[string]any{"roles": roles, "active": *body.Active})
	s.emit(r.Context(), "user_updated", "user", body.UserID, map[string]any{"userId": body.UserID}, "", "")
	writeData(w, 201, map[string]any{
		"userId":         u.UserID,
		"roles":          u.Roles,
		"qualifications": u.Qualifications,
		"certifications": publicUser(u)["certifications"],
		"active":         u.Active,
	})
}

func (s *server) handleReadUser(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	userID := r.PathValue("userId")
	if sess.ActiveRole != RoleAdmin && sess.User.UserID != userID {
		writeErr(w, errOf(403, "forbidden", "only an administrator or the user themself may read this account"))
		return
	}
	u, err := loadUser(r.Context(), s.db, userID)
	if err != nil {
		writeErr(w, errOf(404, "not_found", "user not found"))
		return
	}
	writeData(w, 200, publicUser(u))
}

// ensureFirstAdmin creates the initial administrator when no users exist.
func (s *server) ensureFirstAdmin(ctx context.Context, username, password string) error {
	var n int
	if err := s.db.QueryRow(ctx, `SELECT count(*) FROM users`).Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	hash, _ := bcrypt.GenerateFromPassword([]byte(password), bcrypt.DefaultCost)
	_, err := s.db.Exec(ctx, `INSERT INTO users (user_id, username, password_hash, full_name, roles, active)
		VALUES ($1,$2,$3,$4,'["administrator"]',TRUE)`, newUUID(), username, string(hash), "Administrator")
	return err
}

