	_, _ = s.db.Exec(ctx, `INSERT INTO audit_entries (audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		newUUID(), actorID, role, action, entityType, entityID, success, nowUTC(), d)
}

func (s *server) emit(ctx context.Context, evType, entityType, entityID string, payload map[string]any, audienceRole, audienceUserID string) {
	if payload == nil {
		payload = map[string]any{}
	}
	p, _ := json.Marshal(payload)
	var id int64
	var createdAt time.Time
	err := s.db.QueryRow(ctx, `INSERT INTO events (type, entity_type, entity_id, payload, audience_role, audience_user_id, created_at)
		VALUES ($1,$2,$3,$4,$5,$6,$7) RETURNING id, created_at`,
		evType, entityType, entityID, p, audienceRole, audienceUserID, nowUTC()).Scan(&id, &createdAt)
	if err != nil {
