// ---------- idempotency ----------

// idempotent runs fn unless the key was already used by this user for this action.
// fn returns (httpStatus, dataPayload, apiError). Successful and client-error
// responses are stored and replayed.
func (s *server) idempotent(w http.ResponseWriter, r *http.Request, sess *session, action, key string, body []byte, fn func() (int, any, *apiError)) {
	if key == "" {
		writeErr(w, errOf(400, "idempotency_required", "idempotencyKey is required"))
		return
	}
	hash := sha256.Sum256(body)
	hashHex := hex.EncodeToString(hash[:])
	var storedHash string
	var status int
	var response []byte
	err := s.db.QueryRow(r.Context(), `SELECT request_hash, status, response FROM idempotency_keys
		WHERE key=$1 AND user_id=$2 AND action=$3`, key, sess.User.UserID, action).Scan(&storedHash, &status, &response)
	if err == nil {
		if storedHash != hashHex {
			writeErr(w, errOf(409, "idempotency_conflict", "idempotencyKey was already used with a different request"))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(status)
		_, _ = w.Write(response)
		return
	}
	if !errors.Is(err, pgx.ErrNoRows) {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	st, data, aerr := fn()
	var respBody []byte
	if aerr != nil {
		respBody, _ = json.Marshal(map[string]any{"error": aerr.Message, "code": aerr.Code})
	} else {
		respBody, _ = json.Marshal(map[string]any{"data": data})
	}
	if st < 500 {
		_, _ = s.db.Exec(r.Context(), `INSERT INTO idempotency_keys (key, user_id, action, request_hash, status, response)
			VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT (key, user_id, action) DO NOTHING`,
			key, sess.User.UserID, action, hashHex, st, respBody)
	}
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(st)
	_, _ = w.Write(respBody)
}

