// ---------- user administration ----------

func publicUser(u *User) map[string]any {
	certs := []map[string]any{}
	for _, c := range u.Certifications {
		entry := map[string]any{
			"code":   c["code"],
			"active": c["active"],
		}
		if exp, ok := c["expiresAt"]; ok {
			entry["expiresAt"] = exp
		} else if exp, ok := c["expires_at"]; ok {
			entry["expiresAt"] = exp
		}
		certs = append(certs, entry)
	}
	return map[string]any{
		"userId":         u.UserID,
		"username":       u.Username,
		"email":          u.Email,
		"fullName":       u.FullName,
		"phone":          u.Phone,
		"roles":          u.Roles,
		"qualifications": u.Qualifications,
		"certifications": certs,
		"active":         u.Active,
	}
}

func validateCerts(certs []map[string]any) bool {
	for _, c := range certs {
		code, _ := c["code"].(string)
		if code == "" {
			return false
		}
		if _, ok := c["active"].(bool); !ok {
			return false
		}
		if exp, ok := c["expiresAt"]; ok {
			s, _ := exp.(string)
			if s != "" {
				if _, ok := parseTime(s); !ok {
					return false
				}
			}
		}
	}
	return true
}

