package main

import (
	"encoding/base64"
	"net/http"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

type RealtimeEvent struct {
	ID             int64          `json:"id"`
	Type           string         `json:"type"`
	EntityType     string         `json:"entityType"`
	EntityID       string         `json:"entityId"`
	Payload        map[string]any `json:"payload"`
	CreatedAt      string         `json:"createdAt"`
	AudienceRole   string         `json:"-"`
	AudienceUserID string         `json:"-"`
}

type wsClient struct {
	sess *session
	conn *websocket.Conn
	send chan *RealtimeEvent
}

type eventHub struct {
	mu      sync.Mutex
	clients map[*wsClient]bool
}

func newEventHub() *eventHub {
	return &eventHub{clients: map[*wsClient]bool{}}
}

func (h *eventHub) broadcast(ev *RealtimeEvent) {
	h.mu.Lock()
	defer h.mu.Unlock()
	for c := range h.clients {
		if !eventVisibleTo(ev, c.sess) {
			continue
		}
		select {
		case c.send <- ev:
		default:
		}
	}
}

func eventVisibleTo(ev *RealtimeEvent, sess *session) bool {
	if ev.AudienceUserID != "" && ev.AudienceUserID != sess.User.UserID {
		return false
	}
	if ev.AudienceRole != "" && ev.AudienceRole != sess.ActiveRole {
		return false
	}
	return true
}

var wsUpgrader = websocket.Upgrader{
	CheckOrigin: func(r *http.Request) bool { return true },
}

// handleEvents serves GET /api/events. With a WebSocket upgrade it streams
// events; otherwise it returns recent events as JSON.
func (s *server) handleEvents(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		writeErr(w, errOf(405, "method_not_allowed", "only GET is supported"))
		return
	}
	since := int64(0)
	if v := r.URL.Query().Get("since"); v != "" {
		if n, err := strconv.ParseInt(v, 10, 64); err == nil && n > 0 {
			since = n
		}
	}
	isWS := strings.Contains(strings.ToLower(r.Header.Get("Connection")), "upgrade") &&
		strings.ToLower(r.Header.Get("Upgrade")) == "websocket"
	if !isWS {
		sess, aerr := s.requireAuth(w, r)
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		events, cursor := s.eventsSince(r, since, sess)
		writeData(w, 200, map[string]any{"events": events, "cursor": cursor})
		return
	}
	// WebSocket: authenticate via bearer.<token> subprotocol.
	token := ""
	for _, p := range strings.Split(r.Header.Get("Sec-WebSocket-Protocol"), ",") {
		p = strings.TrimSpace(p)
		if strings.HasPrefix(p, "bearer.") {
			dec, err := base64.RawURLEncoding.DecodeString(strings.TrimPrefix(p, "bearer."))
			if err != nil {
				dec, err = base64.URLEncoding.DecodeString(strings.TrimPrefix(p, "bearer."))
				if err != nil {
					continue
				}
			}
			token = string(dec)
		}
	}
	if token == "" {
		// fall back to Authorization header or query token
		if auth := r.Header.Get("Authorization"); strings.HasPrefix(auth, "Bearer ") {
			token = strings.TrimPrefix(auth, "Bearer ")
		} else {
			token = r.URL.Query().Get("token")
		}
	}
	sess, err := s.loadSession(r.Context(), token)
	if err != nil {
		writeErr(w, errOf(401, "unauthorized", "session is not valid"))
		return
	}
	upgrader := wsUpgrader
	upgrader.Subprotocols = []string{"lab-logistics-v1"}
	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	client := &wsClient{sess: sess, conn: conn, send: make(chan *RealtimeEvent, 64)}
	s.hub.mu.Lock()
	s.hub.clients[client] = true
	s.hub.mu.Unlock()
	defer func() {
		s.hub.mu.Lock()
		delete(s.hub.clients, client)
		s.hub.mu.Unlock()
		conn.Close()
	}()
	// Replay missed events first.
	replayed, _ := s.eventsSinceCtx(r, since, sess)
	for _, ev := range replayed {
		_ = conn.WriteJSON(ev)
	}
	go func() {
		for ev := range client.send {
			if err := conn.WriteJSON(ev); err != nil {
				return
			}
		}
	}()
	// Keep the connection alive; discard incoming messages.
	conn.SetReadLimit(1024)
	for {
		if _, _, err := conn.ReadMessage(); err != nil {
			close(client.send)
			return
		}
	}
}

func (s *server) eventsSince(r *http.Request, since int64, sess *session) ([]*RealtimeEvent, int64) {
	events, cursor := s.eventsSinceCtx(r, since, sess)
	return events, cursor
}

func (s *server) eventsSinceCtx(r *http.Request, since int64, sess *session) ([]*RealtimeEvent, int64) {
	rows, err := s.db.Query(r.Context(), `SELECT id, type, entity_type, entity_id, payload, audience_role, audience_user_id, created_at
		FROM events WHERE id > $1 ORDER BY id LIMIT 500`, since)
	if err != nil {
		return nil, since
	}
	defer rows.Close()
	out := []*RealtimeEvent{}
	cursor := since
	for rows.Next() {
		var ev RealtimeEvent
		var payload []byte
