func (s *server) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleAdmin, RoleNode, RoleLab); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       *int   `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	if body.CapacityUnits == nil || *body.CapacityUnits < 0 {
		writeErr(w, errOf(400, "invalid_capacity", "capacityUnits must be zero or greater"))
		return
	}
	cooled := 0
	if body.CooledCapacityUnits != nil {
		cooled = *body.CooledCapacityUnits
	}
	if cooled < 0 {
		writeErr(w, errOf(400, "invalid_capacity", "cooledCapacityUnits must be zero or greater"))
		return
	}
	ctx := r.Context()
	// resource may be a location or a connection
	if l, err := loadLocation(ctx, s.db, body.ResourceID); err == nil {
		if sess.ActiveRole == RoleNode || sess.ActiveRole == RoleLab {
			if sess.User.AssignedLocationID == nil || *sess.User.AssignedLocationID != l.LocationID {
				writeErr(w, errOf(403, "forbidden", "you may only configure capacity at your assigned location"))
				return
			}
		}
		if *body.CapacityUnits < l.ReservedUnits || cooled < l.CooledReserved {
			writeErr(w, errOf(409, "capacity_reserved", "capacity cannot be set below currently reserved units"))
			return
		}
		if _, err := s.db.Exec(ctx, `UPDATE locations SET capacity_units=$2, cooled_capacity_units=$3 WHERE location_id=$1`,
			body.ResourceID, *body.CapacityUnits, cooled); err != nil {
			writeErr(w, errOf(500, "internal_error", err.Error()))
			return
		}
	} else if c, err := loadConnection(ctx, s.db, body.ResourceID); err == nil {
		if sess.ActiveRole != RoleAdmin {
			writeErr(w, errOf(403, "forbidden", "only an administrator may configure connection capacity"))
			return
		}
		if *body.CapacityUnits < c.ReservedUnits || cooled < c.CooledReserved {
			writeErr(w, errOf(409, "capacity_reserved", "capacity cannot be set below currently reserved units"))
			return
		}
		if _, err := s.db.Exec(ctx, `UPDATE connections SET capacity_units=$2, cooled_capacity_units=$3 WHERE connection_id=$1`,
			body.ResourceID, *body.CapacityUnits, cooled); err != nil {
			writeErr(w, errOf(500, "internal_error", err.Error()))
			return
		}
	} else {
		writeErr(w, errOf(404, "not_found", "resource not found"))
		return
	}
	s.recomputeServiceability(ctx)
	s.audit(ctx, sess, "configure_capacity", "resource", body.ResourceID, true,
		map[string]any{"capacityUnits": *body.CapacityUnits, "cooledCapacityUnits": cooled})
	s.emit(ctx, "capacity_updated", "resource", body.ResourceID, map[string]any{"resourceId": body.ResourceID}, "", "")
	writeData(w, 200, map[string]any{
		"resourceId":          body.ResourceID,
		"capacityUnits":       *body.CapacityUnits,
		"cooledCapacityUnits": cooled,
	})
}

func (s *server) handleConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
