// ---------- capacity & laboratory acceptance ----------

func (s *server) handleConfigureCapacity(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleAdmin, RoleNode, RoleLab); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       *int   `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	if body.CapacityUnits == nil || *body.CapacityUnits < 0 {
		writeErr(w, errOf(400, "invalid_capacity", "capacityUnits must be zero or greater"))
		return
	}
	cooled := 0
	if body.CooledCapacityUnits != nil {
		cooled = *body.CooledCapacityUnits
	}
	if cooled < 0 {
		writeErr(w, errOf(400, "invalid_capacity", "cooledCapacityUnits must be zero or greater"))
		return
	}
	ctx := r.Context()
	// resource may be a location or a connection
	if l, err := loadLocation(ctx, s.db, body.ResourceID); err == nil {
		if sess.ActiveRole == RoleNode || sess.ActiveRole == RoleLab {
			if sess.User.AssignedLocationID == nil || *sess.User.AssignedLocationID != l.LocationID {
				writeErr(w, errOf(403, "forbidden", "you may only configure capacity at your assigned location"))
				return
			}
		}
		if *body.CapacityUnits < l.ReservedUnits || cooled < l.CooledReserved {
			writeErr(w, errOf(409, "capacity_reserved", "capacity cannot be set below currently reserved units"))
			return
		}
		if _, err := s.db.Exec(ctx, `UPDATE locations SET capacity_units=$2, cooled_capacity_units=$3 WHERE location_id=$1`,
			body.ResourceID, *body.CapacityUnits, cooled); err != nil {
			writeErr(w, errOf(500, "internal_error", err.Error()))
			return
		}
	} else if c, err := loadConnection(ctx, s.db, body.ResourceID); err == nil {
		if sess.ActiveRole != RoleAdmin {
			writeErr(w, errOf(403, "forbidden", "only an administrator may configure connection capacity"))
			return
		}
		if *body.CapacityUnits < c.ReservedUnits || cooled < c.CooledReserved {
			writeErr(w, errOf(409, "capacity_reserved", "capacity cannot be set below currently reserved units"))
			return
		}
		if _, err := s.db.Exec(ctx, `UPDATE connections SET capacity_units=$2, cooled_capacity_units=$3 WHERE connection_id=$1`,
			body.ResourceID, *body.CapacityUnits, cooled); err != nil {
			writeErr(w, errOf(500, "internal_error", err.Error()))
			return
		}
	} else {
		writeErr(w, errOf(404, "not_found", "resource not found"))
		return
	}
	s.recomputeServiceability(ctx)
	s.audit(ctx, sess, "configure_capacity", "resource", body.ResourceID, true,
		map[string]any{"capacityUnits": *body.CapacityUnits, "cooledCapacityUnits": cooled})
	s.emit(ctx, "capacity_updated", "resource", body.ResourceID, map[string]any{"resourceId": body.ResourceID}, "", "")
	writeData(w, 200, map[string]any{
		"resourceId":          body.ResourceID,
		"capacityUnits":       *body.CapacityUnits,
		"cooledCapacityUnits": cooled,
	})
}

func (s *server) handleConfigureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      *bool  `json:"accepts"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	if body.Accepts == nil {
		writeErr(w, errOf(400, "invalid_acceptance", "accepts is required"))
		return
	}
	ctx := r.Context()
	l, err := loadLocation(ctx, s.db, body.LaboratoryID)
	if err != nil || !l.Functions["laboratory"] {
		writeErr(w, errOf(400, "invalid_acceptance", "laboratoryId does not reference a laboratory"))
		return
	}
	if _, err := loadSampleType(ctx, s.db, body.SampleTypeID); err != nil {
		writeErr(w, errOf(400, "invalid_acceptance", "sampleTypeId does not reference a sample type"))
		return
	}
	accepted := l.AcceptedTypeIDs
	if *body.Accepts {
		if !containsString(accepted, body.SampleTypeID) {
			accepted = append(accepted, body.SampleTypeID)
		}
	} else {
		accepted = removeString(accepted, body.SampleTypeID)
	}
	acceptedJSON, _ := json.Marshal(accepted)
	if _, err := s.db.Exec(ctx, `UPDATE locations SET accepted_sample_type_ids=$2 WHERE location_id=$1`, body.LaboratoryID, acceptedJSON); err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	s.recomputeServiceability(ctx)
	s.audit(ctx, sess, "configure_laboratory_acceptance", "location", body.LaboratoryID, true,
		map[string]any{"sampleTypeId": body.SampleTypeID, "accepts": *body.Accepts})
	s.emit(ctx, "location_updated", "location", body.LaboratoryID, map[string]any{"locationId": body.LaboratoryID}, "", "")
	writeData(w, 200, map[string]any{"acceptanceId": newUUID(), "accepts": *body.Accepts})
}

func (s *server) handleSetWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleAdmin, RoleDispatcher, RoleCollector, RoleCourier, RoleNode, RoleLab); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		WorkerID      string `json:"workerId"`
		Available     *bool  `json:"available"`
		CapacityUnits *int   `json:"capacityUnits"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	if body.Available == nil || body.CapacityUnits == nil {
		writeErr(w, errOf(400, "invalid_json", "workerId, available and capacityUnits are required"))
		return
	}
	if *body.CapacityUnits < 0 {
		writeErr(w, errOf(400, "invalid_capacity", "capacityUnits must be zero or greater"))
		return
	}
	ctx := r.Context()
	u, err := loadUser(ctx, s.db, body.WorkerID)
	if err != nil {
		writeErr(w, errOf(404, "not_found", "worker not found"))
		return
	}
	isStaff := sess.ActiveRole == RoleAdmin || sess.ActiveRole == RoleDispatcher
	if !isStaff && sess.User.UserID != u.UserID {
		writeErr(w, errOf(403, "forbidden", "you may only change your own availability"))
		return
	}
	if *body.CapacityUnits < u.CapacityUnits || !*body.Available {
		var active int
		_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE accepted_by=$1 AND status IN ('accepted','in_progress')`, u.UserID).Scan(&active)
		if *body.CapacityUnits < active {
			writeErr(w, errOf(409, "capacity_reserved", "capacityUnits cannot be below the worker's active assignment count"))
			return
		}
	}
	if _, err := s.db.Exec(ctx, `UPDATE users SET available=$2, capacity_units=$3 WHERE user_id=$1`,
		body.WorkerID, *body.Available, *body.CapacityUnits); err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	s.audit(ctx, sess, "set_worker_availability", "user", body.WorkerID, true,
		map[string]any{"available": *body.Available, "capacityUnits": *body.CapacityUnits})
	s.emit(ctx, "worker_updated", "user", body.WorkerID, map[string]any{"workerId": body.WorkerID, "available": *body.Available}, "", "")
	writeData(w, 200, map[string]any{
		"workerId":      body.WorkerID,
		"available":     *body.Available,
		"capacityUnits": *body.CapacityUnits,
	})
}

// recomputeServiceability is defined in serviceability.go.
var _ = context.Background
"}

