func validCoordinate(lat, lng float64) bool {
	return lat >= -90 && lat <= 90 && lng >= -180 && lng <= 180
}

func (s *server) handleCreateLocation(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		Name           string   `json:"name"`
		Coordinate     *coordIn `json:"coordinate"`
		CoverageKm     *float64 `json:"coverageKm"`
		HandlingMinutes *int    `json:"handlingMinutes"`
		Active         *bool    `json:"active"`
		Functions      []string `json:"functions"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	if body.Name == "" || body.Coordinate == nil || body.Active == nil || len(body.Functions) == 0 {
		writeErr(w, errOf(400, "invalid_json", "name, coordinate, active and functions are required"))
		return
	}
	if !validCoordinate(body.Coordinate.Latitude, body.Coordinate.Longitude) {
		writeErr(w, errOf(400, "invalid_coordinate", "coordinate is out of range"))
		return
	}
	coverage := 5.0
	if body.CoverageKm != nil {
		coverage = *body.CoverageKm
	}
	if coverage <= 0 || coverage > 5 {
		writeErr(w, errOf(400, "invalid_node_coverage", "coverageKm must be greater than 0 and at most 5"))
		return
	}
	handling := 0
	if body.HandlingMinutes != nil {
		handling = *body.HandlingMinutes
	}
	if handling < 0 || handling > 1440 {
		writeErr(w, errOf(400, "invalid_handling_time", "handlingMinutes must be between 0 and 1440"))
		return
	}
	for _, f := range body.Functions {
		if !containsString(validFunctions, f) {
			writeErr(w, errOf(400, "invalid_location_function", "unknown location function: "+f))
			return
		}
	}
	id := newUUID()
	fns, _ := json.Marshal(functionsMap(body.Functions))
	_, err := s.db.Exec(r.Context(), `INSERT INTO locations (location_id, name, lat, lng, coverage_km, handling_minutes, active, functions)
		VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
		id, body.Name, body.Coordinate.Latitude, body.Coordinate.Longitude, coverage, handling, *body.Active, fns)
	if err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	s.recomputeServiceability(r.Context())
	l, _ := loadLocation(r.Context(), s.db, id)
	s.audit(r.Context(), sess, "create_location", "location", id, true, map[string]any{"name": body.Name, "functions": body.Functions})
	s.emit(r.Context(), "location_updated", "location", id, map[string]any{"locationId": id}, "", "")
	writeData(w, 201, locationJSON(l))
}

