	}
	coverage := l.CoverageKm
	if body.CoverageKm != nil {
		coverage = *body.CoverageKm
	}
	if coverage <= 0 || coverage > 5 {
		writeErr(w, errOf(400, "invalid_node_coverage", "coverageKm must be greater than 0 and at most 5"))
		return
	}
	handling := l.HandlingMinutes
	if body.HandlingMinutes != nil {
		handling = *body.HandlingMinutes
	}
	if handling < 0 || handling > 1440 {
		writeErr(w, errOf(400, "invalid_handling_time", "handlingMinutes must be between 0 and 1440"))
		return
	}
	fns := l.Functions
	if body.Functions != nil {
		if len(body.Functions) == 0 {
			writeErr(w, errOf(400, "invalid_location_function", "at least one function is required"))
			return
		}
		for _, f := range body.Functions {
			if !containsString(validFunctions, f) {
				writeErr(w, errOf(400, "invalid_location_function", "unknown location function: "+f))
				return
			}
		}
		fns = functionsMap(body.Functions)
	}
	fnsJSON, _ := json.Marshal(fns)
	_, err = s.db.Exec(r.Context(), `UPDATE locations SET name=$2, lat=$3, lng=$4, coverage_km=$5, handling_minutes=$6, functions=$7
		WHERE location_id=$1`, body.LocationID, body.Name, body.Coordinate.Latitude, body.Coordinate.Longitude, coverage, handling, fnsJSON)
	if err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	s.recomputeServiceability(r.Context())
	l, _ = loadLocation(r.Context(), s.db, body.LocationID)
	s.audit(r.Context(), sess, "update_location", "location", body.LocationID, true, map[string]any{"name": body.Name})
	s.emit(r.Context(), "location_updated", "location", body.LocationID, map[string]any{"locationId": body.LocationID}, "", "")
	writeData(w, 201, locationJSON(l))
}

