func (s *server) handleCreateConnection(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		FromLocationID string   `json:"fromLocationId"`
		ToLocationID   string   `json:"toLocationId"`
		TravelMinutes  *int     `json:"travelMinutes"`
		CostUnits      *float64 `json:"costUnits"`
		Cooled         *bool    `json:"cooled"`
		Active         *bool    `json:"active"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	if body.TravelMinutes == nil || body.CostUnits == nil || body.Active == nil {
		writeErr(w, errOf(400, "invalid_connection", "fromLocationId, toLocationId, travelMinutes, costUnits and active are required"))
		return
	}
	if !isUUID(body.FromLocationID) || !isUUID(body.ToLocationID) || body.FromLocationID == body.ToLocationID {
		writeErr(w, errOf(400, "invalid_connection", "fromLocationId and toLocationId must be distinct locations"))
		return
	}
	if *body.TravelMinutes < 1 || *body.CostUnits < 0 {
		writeErr(w, errOf(400, "invalid_connection", "travelMinutes must be at least 1 and costUnits at least 0"))
		return
	}
	if _, err := loadLocation(r.Context(), s.db, body.FromLocationID); err != nil {
		writeErr(w, errOf(400, "invalid_connection", "fromLocationId does not reference a location"))
		return
	}
	if _, err := loadLocation(r.Context(), s.db, body.ToLocationID); err != nil {
		writeErr(w, errOf(400, "invalid_connection", "toLocationId does not reference a location"))
		return
	}
	cooled := false
	if body.Cooled != nil {
		cooled = *body.Cooled
	}
	id := newUUID()
	_, err := s.db.Exec(r.Context(), `INSERT INTO connections (connection_id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active)
		VALUES ($1,$2,$3,$4,$5,$6,$7)`,
		id, body.FromLocationID, body.ToLocationID, *body.TravelMinutes, *body.CostUnits, cooled, *body.Active)
	if err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	s.recomputeServiceability(r.Context())
	s.audit(r.Context(), sess, "create_connection", "connection", id, true,
		map[string]any{"from": body.FromLocationID, "to": body.ToLocationID})
	s.emit(r.Context(), "connection_updated", "connection", id, map[string]any{"connectionId": id}, "", "")
	writeData(w, 201, map[string]any{
		"connectionId":   id,
		"fromLocationId": body.FromLocationID,
		"toLocationId":   body.ToLocationID,
		"travelMinutes":  *body.TravelMinutes,
		"costUnits":      *body.CostUnits,
		"cooled":         cooled,
		"active":         *body.Active,
	})
}

