			return
		}
	}
	if _, err := s.db.Exec(ctx, `UPDATE users SET available=$2, capacity_units=$3 WHERE user_id=$1`,
		body.WorkerID, *body.Available, *body.CapacityUnits); err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	s.audit(ctx, sess, "set_worker_availability", "user", body.WorkerID, true,
		map[string]any{"available": *body.Available, "capacityUnits": *body.CapacityUnits})
	s.emit(ctx, "worker_updated", "user", body.WorkerID, map[string]any{"workerId": body.WorkerID, "available": *body.Available}, "", "")
	writeData(w, 200, map[string]any{
		"workerId":      body.WorkerID,
		"available":     *body.Available,
		"capacityUnits": *body.CapacityUnits,
	})
}

// recomputeServiceability is defined in serviceability.go.
var _ = context.Background
"}

