var errCapacity = errors.New("insufficient capacity")

// reserveUnit atomically reserves one unit in the required pool.
func (s *server) reserveUnit(ctx context.Context, resourceType, resourceID, journeyID, sampleID string, cooled bool) error {
	var tag string
	var err error
	if resourceType == "location" {
		if cooled {
			tag, err = s.execTag(ctx, `UPDATE locations SET cooled_reserved_units = cooled_reserved_units + 1
