				WHERE connection_id=$1 AND capacity_units - reserved_units >= 1`, resourceID)
		}
	}
	if err != nil {
		return err
	}
	if tag == 0 {
		return errCapacity
	}
	_, err = s.db.Exec(ctx, `INSERT INTO reservations (reservation_id, resource_type, resource_id, journey_id, sample_id, cooled, units)
		VALUES ($1,$2,$3,$4,$5,$6,1)`, newUUID(), resourceType, resourceID, journeyID, sampleID, cooled)
	return err
}

func (s *server) execTag(ctx context.Context, sql string, args ...any) (int64, error) {
	tag, err := s.db.Exec(ctx, sql, args...)
