	if aerr := requireRole(sess, RoleRequester, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytesReader(raw))
	var body requestBodyIn
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	exec := func() (int, any, *apiError) {
		return s.createCollectionRequest(r, sess, &body)
