	"path/filepath"
	"strings"
	"syscall"
	"time"
)

type server struct {
	db     *DB
	static string
}

func main() {
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgres://agent:agent@127.0.0.1:5432/labpickup?sslmode=disable"
	}
	db, err := connectDB(dbURL)
	if err != nil {
		log.Fatalf("database unavailable: %v", err)
	}
	if err := migrate(db); err != nil {
		log.Fatalf("migration failed: %v", err)
	}
	s := &server{db: db, static: os.Getenv("STATIC_DIR")}
	if s.static == "" {
		s.static = "/workspace/web/dist"
	}
	if err := s.seed(context.Background()); err != nil {
		log.Fatalf("seed failed: %v", err)
	}
	if err := s.ensureInitialAdmin(context.Background()); err != nil {
		log.Fatalf("initial admin failed: %v", err)
	}
	go s.offerExpiryLoop()

	mux := http.NewServeMux()
	// auth & session
	mux.HandleFunc("POST /api/auth/login", s.handleLogin)
	mux.HandleFunc("POST /api/auth/logout", s.handleLogout)
	mux.HandleFunc("POST /api/auth/select-role", s.handleSelectRole)
	mux.HandleFunc("POST /api/users/availability", s.handleSetAvailability)
	// admin user management
	mux.HandleFunc("POST /api/admin/users", s.handleCreateUser)
	mux.HandleFunc("POST /api/admin/users/{userId}/roles", s.handleAssignRoles)
	mux.HandleFunc("POST /api/admin/users/{userId}/certifications", s.handleAssignCertifications)
	mux.HandleFunc("POST /api/admin/users/{userId}/assignments", s.handleAssignWorkerSite)
	// admin network management
	mux.HandleFunc("POST /api/admin/locations", s.handleCreateLocation)
	mux.HandleFunc("POST /api/admin/locations/{locationId}", s.handleUpdateLocation)
	mux.HandleFunc("POST /api/admin/locations/{locationId}/acceptance", s.handleSetLaboratoryAcceptance)
	mux.HandleFunc("POST /api/admin/connections", s.handleCreateConnection)
	mux.HandleFunc("POST /api/admin/connections/{connectionId}", s.handleUpdateConnection)
	mux.HandleFunc("POST /api/admin/sample-types", s.handleCreateSampleType)
	mux.HandleFunc("POST /api/admin/sample-types/{sampleTypeId}", s.handleUpdateSampleType)
	mux.HandleFunc("POST /api/admin/locations/{locationId}/capacity", s.handleConfigureCapacity)
	mux.HandleFunc("POST /api/admin/connections/{connectionId}/capacity", s.handleConfigureCapacity)
	// requests & serviceability
	mux.HandleFunc("POST /api/serviceability/check", s.handleServiceabilityCheck)
	mux.HandleFunc("POST /api/requests", s.handleCreateCollectionRequest)
	mux.HandleFunc("POST /api/requests/ingest-presealed", s.handleIngestPresealed)
	// assignment lifecycle
	mux.HandleFunc("POST /api/assignments/accept", s.handleAcceptAssignment)
	mux.HandleFunc("POST /api/assignments/decline", s.handleDeclineAssignment)
	mux.HandleFunc("POST /api/assignments/progress", s.handleUpdateAssignmentProgress)
	mux.HandleFunc("POST /api/assignments/collect-and-seal", s.handleCollectAndSeal)
