	// custody
	mux.HandleFunc("POST /api/handoffs/initiate", s.handleInitiateHandoff)
	mux.HandleFunc("POST /api/handoffs/confirm", s.handleConfirmHandoff)
	mux.HandleFunc("POST /api/laboratory/receipt", s.handleConfirmLaboratoryReceipt)
	mux.HandleFunc("POST /api/laboratory/exceptions", s.handleRecordLaboratoryException)
	// reads
	mux.HandleFunc("POST /api/work/list", s.handleListRoleWork)
	mux.HandleFunc("POST /api/ui/bootstrap", s.handleBootstrap)
	mux.HandleFunc("POST /api/operations/state", s.handleReadOperationsState)
	mux.HandleFunc("GET /api/journeys/{journeyId}", s.handleReadJourneyPlan)
	mux.HandleFunc("GET /api/samples/{sampleId}", s.handleReadSampleState)
	mux.HandleFunc("GET /api/samples/{sampleId}/lifecycle", s.handleReadSampleLifecycle)
	// dispatcher actions
	mux.HandleFunc("POST /api/journeys/cancel", s.handleCancelJourney)
	mux.HandleFunc("POST /api/journeys/split", s.handleSplitJourney)
	mux.HandleFunc("POST /api/journeys/merge", s.handleMergeJourneys)
	mux.HandleFunc("POST /api/journeys/edit", s.handleEditActivePlan)
	mux.HandleFunc("POST /api/journeys/reroute", s.handleRerouteJourney)
	mux.HandleFunc("POST /api/disruptions", s.handleReportDisruption)
	mux.HandleFunc("POST /api/audit/search", s.handleSearchAuditTrail)
	// events
	mux.HandleFunc("GET /api/events", s.handleEvents)

	mux.HandleFunc("GET /ready", func(w http.ResponseWriter, r *http.Request) {
		if err := s.db.Ping(r.Context()); err != nil {
			http.Error(w, `{"status":"unavailable"}`, http.StatusServiceUnavailable)
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(200)
		_, _ = w.Write([]byte(`{"status":"ready"}`))
	})
	mux.HandleFunc("/", s.serveStatic)

	addr := os.Getenv("ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}
	httpServer := &http.Server{Addr: addr, Handler: mux}
	go func() {
		sig := make(chan os.Signal, 1)
		signal.Notify(sig, syscall.SIGINT, syscall.SIGTERM)
		<-sig
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		_ = httpServer.Shutdown(ctx)
	}()
	log.Printf("listening on %s", addr)
	if err := httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("server failed: %v", err)
	}
}

func (s *server) serveStatic(w http.ResponseWriter, r *http.Request) {
	if strings.HasPrefix(r.URL.Path, "/api/") {
		http.NotFound(w, r)
		return
	}
	p := filepath.Clean(r.URL.Path)
	if p == "/" || p == "." {
		p = "/index.html"
	}
	full := filepath.Join(s.static, p)
	if !strings.HasPrefix(full, filepath.Clean(s.static)) {
		http.NotFound(w, r)
		return
	}
	if info, err := os.Stat(full); err != nil || info.IsDir() {
		// SPA fallback
		full = filepath.Join(s.static, "index.html")
		if _, err := os.Stat(full); err != nil {
			http.NotFound(w, r)
			return
		}
	}
	http.ServeFile(w, r, full)
}

// offerExpiryLoop expires unanswered offers and re-offers them.
func (s *server) offerExpiryLoop() {
	ticker := time.NewTicker(10 * time.Second)
	defer ticker.Stop()
	for range ticker.C {
		ctx, cancel := context.WithTimeout(context.Background(), 20*time.Second)
		rows, err := s.db.Query(ctx, `SELECT assignment_id FROM assignments WHERE status='offered' AND offer_expires_at < now()`)
		if err != nil {
			cancel()
			continue
		}
		ids := []string{}
		for rows.Next() {
			var id string
			_ = rows.Scan(&id)
			ids = append(ids, id)
		}
		rows.Close()
		for _, id := range ids {
			a, err := loadAssignment(ctx, s.db, id)
			if err != nil || a.Status != AsgOffered {
				continue
			}
			// treat the expired offer as a decline
			if a.OfferedTo != nil {
				declined := append(a.DeclinedBy, *a.OfferedTo)
				dj, _ := jsonMarshal(declined)
				_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$2, updated_at=now()
					WHERE assignment_id=$1`, a.AssignmentID, dj)
				_, _ = s.db.Exec(ctx, `UPDATE users SET recent_declines = recent_declines + 1, last_decline_at=now() WHERE user_id=$1`, *a.OfferedTo)
				s.emit(ctx, "assignment_expired", "assignment", a.AssignmentID, map[string]any{
					"assignmentId": a.AssignmentID, "workerId": *a.OfferedTo, "kind": a.Kind, "sampleId": a.SampleID,
				}, "", "")
			}
			a, _ = loadAssignment(ctx, s.db, id)
			offeredTo, noQualified, _ := s.offerAssignment(ctx, nil, a)
			if noQualified {
				s.flagNoQualifiedWorker(ctx, nil, a.SampleID, a.AssignmentID)
			}
			_ = offeredTo
		}
		cancel()
	}
}

// ensureInitialAdmin creates the first administrator from environment variables.
func (s *server) ensureInitialAdmin(ctx context.Context) error {
	var n int
	if err := s.db.QueryRow(ctx, `SELECT count(*) FROM users`).Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	username := os.Getenv("ADMIN_USERNAME")
	password := os.Getenv("ADMIN_PASSWORD")
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	userID := newUUID()
	_, err := s.db.Exec(ctx, `INSERT INTO users (user_id, username, password_hash, display_name, roles, available, capacity_units)
		VALUES ($1,$2,$3,$4,$5,TRUE,4)`, userID, username, hashPassword(password), "Administrator", `["admin","dispatcher"]`)
	if err != nil {
		return err
	}
	s.audit(ctx, nil, "seed_initial_admin", "user", userID, true, map[string]any{"username": username})
	return nil
}

// seed installs the default sample types and, on an empty network, a small
// Bangalore demonstration network so the application is usable immediately.
func (s *server) seed(ctx context.Context) error {
	// default sample types
	defaults := []struct {
		name        string
		container   string
		min, max    float64
		qualified   bool
		cooled      bool
		batching    bool
		incompatIDs []string
	}{}
	_ = defaults
	var amberID, indigoID string
	{
		// look up existing types first (idempotent seeding)
		rows, err := s.db.Query(ctx, `SELECT sample_type_id, name FROM sample_types`)
		if err != nil {
			return err
		}
		existing := map[string]string{}
		for rows.Next() {
			var id, name string
			_ = rows.Scan(&id, &name)
			existing[name] = id
		}
		rows.Close()
		if _, ok := existing["Amber"]; !ok {
			amberID = newUUID()
			if _, err := s.db.Exec(ctx, `INSERT INTO sample_types (sample_type_id, name, container_type, temperature_min_c, temperature_max_c,
				qualified_collector_required, requires_cooled, batching_allowed, incompatible_sample_type_ids)
				VALUES ($1,'Amber','standard',2,25,TRUE,FALSE,TRUE,'[]')`, amberID); err != nil {
				return err
			}
		} else {
			amberID = existing["Amber"]
		}
		if _, ok := existing["Indigo"]; !ok {
			indigoID = newUUID()
			incompat, _ := jsonMarshal([]string{amberID})
			if _, err := s.db.Exec(ctx, `INSERT INTO sample_types (sample_type_id, name, container_type, temperature_min_c, temperature_max_c,
				qualified_collector_required, requires_cooled, batching_allowed, incompatible_sample_type_ids)
				VALUES ($1,'Indigo','standard',2,25,TRUE,FALSE,TRUE,$2)`, indigoID, incompat); err != nil {
				return err
			}
		}
		if _, ok := existing["Frost"]; !ok {
			if _, err := s.db.Exec(ctx, `INSERT INTO sample_types (sample_type_id, name, container_type, temperature_min_c, temperature_max_c,
				qualified_collector_required, requires_cooled, batching_allowed, incompatible_sample_type_ids)
				VALUES ($1,'Frost','cooled',-20,4,TRUE,TRUE,TRUE,'[]')`, newUUID()); err != nil {
				return err
			}
		}
		if _, ok := existing["Pulse"]; !ok {
			if _, err := s.db.Exec(ctx, `INSERT INTO sample_types (sample_type_id, name, container_type, temperature_min_c, temperature_max_c,
				qualified_collector_required, requires_cooled, batching_allowed, incompatible_sample_type_ids)
				VALUES ($1,'Pulse','standard',2,25,TRUE,FALSE,FALSE,'[]')`, newUUID()); err != nil {
				return err
			}
		}
	}
	// demonstration network (only when no locations exist yet)
	var locCount int
	if err := s.db.QueryRow(ctx, `SELECT count(*) FROM locations`).Scan(&locCount); err != nil {
		return err
	}
	if locCount > 0 {
		return nil
	}
	type locDef struct {
		name         string
		lat, lng     float64
		functions    []string
		handling     int
		cap, cooled  int
		acceptsAll   bool
	}
	defs := []locDef{
		{"Indiranagar Collection Centre", 12.9719, 77.6412, []string{"collection_point", "transfer_point"}, 5, 10, 4, false},
		{"Whitefield Collection Point", 12.9698, 77.7500, []string{"collection_point"}, 5, 8, 2, false},
		{"Koramangala Hub", 12.9352, 77.6245, []string{"transfer_point", "hub"}, 8, 20, 8, false},
		{"Hebbal Hub", 13.0358, 77.5970, []string{"transfer_point", "hub"}, 8, 20, 8, false},
		{"Central Laboratory", 12.9716, 77.5946, []string{"laboratory"}, 5, 30, 12, true},
		{"Electronic City Lab & Hub", 12.8452, 77.6602, []string{"transfer_point", "hub", "laboratory"}, 8, 25, 10, true},
	}
	locIDs := []string{}
	for _, d := range defs {
		id := newUUID()
		fn, _ := jsonMarshal(d.functions)
		accepts := []string{}
		if d.acceptsAll {
			rows, err := s.db.Query(ctx, `SELECT sample_type_id FROM sample_types`)
			if err != nil {
				return err
			}
			for rows.Next() {
				var tid string
				_ = rows.Scan(&tid)
				accepts = append(accepts, tid)
			}
			rows.Close()
		}
		acceptsJSON, _ := jsonMarshal(accepts)
		if _, err := s.db.Exec(ctx, `INSERT INTO locations (location_id, name, lat, lng, functions, handling_minutes,
			capacity_units, cooled_capacity_units, accepted_sample_type_ids)
			VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`, id, d.name, d.lat, d.lng, fn, d.handling, d.cap, d.cooled, acceptsJSON); err != nil {
			return err
		}
		locIDs = append(locIDs, id)
	}
	// connections: collection points -> hubs -> laboratories
	type connDef struct {
		from, to int
		minutes  int
		cost     int
		cooled   bool
		cap      int
		ccap     int
	}
	conns := []connDef{
		{0, 2, 20, 2, false, 10, 4}, // Indiranagar -> Koramangala hub
		{0, 3, 35, 3, true, 10, 4},  // Indiranagar -> Hebbal hub (cooled)
		{1, 5, 40, 4, true, 10, 4},  // Whitefield -> Electronic City (cooled)
		{1, 3, 45, 4, false, 10, 4}, // Whitefield -> Hebbal
		{2, 4, 25, 2, true, 12, 6},  // Koramangala -> Central lab (cooled)
		{3, 4, 30, 3, false, 12, 6}, // Hebbal -> Central lab
		{5, 4, 55, 5, true, 12, 6},  // Electronic City -> Central lab (cooled)
		{2, 5, 45, 4, true, 10, 4},  // Koramangala -> Electronic City (cooled)
	}
	for _, c := range conns {
		if _, err := s.db.Exec(ctx, `INSERT INTO connections (connection_id, from_location_id, to_location_id, travel_minutes,
			cost_units, cooled, capacity_units, cooled_capacity_units)
			VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`, newUUID(), locIDs[c.from], locIDs[c.to], c.minutes, c.cost, c.cooled, c.cap, c.ccap); err != nil {
			return err
		}
	}
	s.audit(ctx, nil, "seed_network", "location", locIDs[0], true, map[string]any{"locations": len(locIDs), "connections": len(conns)})
	return nil
}
"}

