    72	// findRoute computes the fastest route from entry to any accepting laboratory.
    73	// start is the earliest departure time from the entry point.
    74	func findRoute(locs map[string]*Location, conns []*Connection, entryID string, st *SampleType, start time.Time) *routeResult {
    75		type edge struct {
    76			to   string
    77			conn *Connection
    78		}
    79		adj := map[string][]edge{}
    80		for _, c := range conns {
    81			if !c.Active {
    82				continue
    83			}
    84			if st.RequiresCooled && !c.Cooled {
    85				continue
    86			}
    87			adj[c.FromLocationID] = append(adj[c.FromLocationID], edge{to: c.ToLocationID, conn: c})
    88		}
    89		dist := map[string]int{entryID: 0}
    90		prev := map[string]*Connection{}
    91		visited := map[string]bool{}
    92		for {
    93			// pick unvisited node with smallest dist
    94			cur := ""
    95			curDist := 0
    96			for id, d := range dist {
    97				if visited[id] {
    98					continue
    99				}
   100				if cur == "" || d < curDist {
   101					cur, curDist = id, d
   102				}
   103			}
   104			if cur == "" {
   105				break
   106			}
   107			visited[cur] = true
   108			for _, e := range adj[cur] {
   109				nd := curDist + e.conn.TravelMinutes
   110				if dl, ok := dist[e.to]; !ok || nd < dl {
   111					dist[e.to] = nd
   112					prev[e.to] = e.conn
   113				}
   114			}
   115		}
   116		// choose best lab
   117		var best *routeResult
   118		for id, l := range locs {
   119			if !l.Active || !l.Functions["laboratory"] || !containsString(l.AcceptedTypeIDs, st.SampleTypeID) {
   120				continue
   121			}
   122			d, ok := dist[id]
   123			if !ok {
   124				continue
   125			}
   126			// reconstruct path
   127			connIDs := []string{}
   128			nodeIDs := []string{}
   129			cost := 0.0
   130			cur := id
   131			for cur != entryID {
   132				c := prev[cur]
   133				if c == nil {
   134					break
   135				}
   136				connIDs = append([]string{c.ConnectionID}, connIDs...)
   137				if c.FromLocationID != entryID {
   138					nodeIDs = append([]string{c.FromLocationID}, nodeIDs...)
   139				}
   140				cost += c.CostUnits
   141				cur = c.FromLocationID
   142			}
   143			handling := 0
   144			for _, nid := range nodeIDs {
   145				if nl, ok := locs[nid]; ok {
   146					handling += nl.HandlingMinutes
   147				}
   148			}
   149			cand := &routeResult{
   150				LabID:           id,
   151				ConnectionIDs:   connIDs,
   152				NodeIDs:         nodeIDs,
   153				TravelMinutes:   d,
   154				HandlingMinutes: handling,
   155				TotalCost:       cost,
   156				Arrival:         start.Add(time.Duration(d+handling) * time.Minute),
   157			}
   158			if best == nil || cand.Arrival.Before(best.Arrival) {
   159				best = cand
   160			}
   161		}
   162		return best
   163	}
