   165	// routeCapacityOK verifies that every resource on the route has a free unit in
   166	// the required pool.
   167	func routeCapacityOK(locs map[string]*Location, conns []*Connection, route *routeResult, entryID string, cooled bool) bool {
   168		checkLoc := func(id string) bool {
   169			l, ok := locs[id]
   170			if !ok {
   171				return false
   172			}
   173			if cooled {
   174				return l.CooledCapacity-l.CooledReserved >= 1
   175			}
   176			return l.CapacityUnits-l.ReservedUnits >= 1
   177		}
   178		if !checkLoc(entryID) || !checkLoc(route.LabID) {
   179			return false
   180		}
   181		for _, nid := range route.NodeIDs {
   182			if !checkLoc(nid) {
   183				return false
   184			}
   185		}
   186		connByID := map[string]*Connection{}
   187		for _, c := range conns {
   188			connByID[c.ConnectionID] = c
   189		}
   190		for _, cid := range route.ConnectionIDs {
   191			c := connByID[cid]
   192			if c == nil {
   193				return false
   194			}
   195			if cooled {
   196				if c.CooledCapacity-c.CooledReserved < 1 {
   197					return false
   198				}
   199			} else if c.CapacityUnits-c.ReservedUnits < 1 {
   200				return false
   201			}
   202		}
   203		return true
   204	}
