   206	// resolveEntryPoint finds the collection point serving an origin.
   207	func resolveEntryPoint(locs map[string]*Location, originType string, originLat, originLng float64, originNodeID *string) (string, string) {
   208		if originType == "node" && originNodeID != nil {
   209			if l, ok := locs[*originNodeID]; ok && l.Active && l.Functions["collection_point"] {
   210				return l.LocationID, ""
   211			}
   212			return "", "outside_service_coverage"
   213		}
   214		bestID := ""
   215		bestDist := 0.0
   216		for _, l := range locs {
   217			if !l.Active || !l.Functions["collection_point"] {
   218				continue
   219			}
   220			d := haversineKm(originLat, originLng, l.Lat, l.Lng)
   221			if d > l.CoverageKm || d > 5 {
   222				continue
   223			}
   224			if bestID == "" || d < bestDist {
   225				bestID, bestDist = l.LocationID, d
   226			}
   227		}
   228		if bestID == "" {
   229			return "", "outside_service_coverage"
   230		}
   231		return bestID, ""
   232	}
