   234	// evaluateServiceability runs the full structural serviceability check.
   235	func (s *server) evaluateServiceability(ctx context.Context, originType string, originLat, originLng float64,
   236		originNodeID *string, st *SampleType, requestedAt, earliest, latest, deadline time.Time) *serviceabilityResult {
   237		res := &serviceabilityResult{}
   238		locs, conns, err := s.activeNetwork(ctx)
   239		if err != nil {
   240			res.Reason = "no_route"
   241			return res
   242		}
   243		entryID, reason := resolveEntryPoint(locs, originType, originLat, originLng, originNodeID)
   244		if reason != "" {
   245			res.Reason = reason
   246			return res
   247		}
   248		res.EntryID = entryID
   249		// any accepting lab at all?
   250		anyLab := false
   251		for _, l := range locs {
   252			if l.Active && l.Functions["laboratory"] && containsString(l.AcceptedTypeIDs, st.SampleTypeID) {
   253				anyLab = true
   254				break
   255			}
   256		}
   257		if !anyLab {
   258			res.Reason = "no_accepting_laboratory"
   259			return res
   260		}
   261		start := requestedAt
   262		if earliest.After(start) {
   263			start = earliest
   264		}
   265		if now := nowUTC(); now.After(start) {
   266			start = now
   267		}
   268		route := findRoute(locs, conns, entryID, st, start)
   269		if route == nil {
   270			res.Reason = "no_route"
   271			return res
   272		}
   273		res.Route = route
   274		res.LabID = route.LabID
   275		arrival := route.Arrival
   276		res.Arrival = &arrival
   277		if !routeCapacityOK(locs, conns, route, entryID, st.RequiresCooled) {
   278			res.Reason = "insufficient_capacity"
   279			return res
   280		}
   281		if arrival.After(deadline) {
   282			res.Reason = "deadline_unreachable"
   283			return res
   284		}
   285		res.Serviceable = true
   286		res.Reason = ""
   287		return res
   288	}
