   290	// recomputeServiceability publishes a new complete snapshot version. The
   291	// previous version remains readable until the new one is fully inserted.
   292	func (s *server) recomputeServiceability(ctx context.Context) {
   293		var revision int
   294		_ = s.db.QueryRow(ctx, `UPDATE meta SET value = (value::int + 1)::text WHERE key='network_revision' RETURNING value::int`).Scan(&revision)
   295		locs, _, err := s.activeNetwork(ctx)
   296		if err != nil {
   297			return
   298		}
   299		regions := []map[string]any{}
   300		for _, l := range locs {
   301			if !l.Active || !l.Functions["collection_point"] {
   302				continue
   303			}
   304			regions = append(regions, map[string]any{
   305				"locationId": l.LocationID,
   306				"name":       l.Name,
   307				"coordinate": map[string]any{"latitude": l.Lat, "longitude": l.Lng},
   308				"coverageKm": l.CoverageKm,
   309			})
   310		}
   311		sort.Slice(regions, func(i, j int) bool { return regions[i]["locationId"].(string) < regions[j]["locationId"].(string) })
   312		regionsJSON, _ := json.Marshal(regions)
   313		var version int
   314		_ = s.db.QueryRow(ctx, `SELECT COALESCE(max(version),0)+1 FROM serviceability_snapshots`).Scan(&version)
   315		_, _ = s.db.Exec(ctx, `INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
