    80		}
    81		isWS := strings.Contains(strings.ToLower(r.Header.Get("Connection")), "upgrade") &&
    82			strings.ToLower(r.Header.Get("Upgrade")) == "websocket"
    83		if !isWS {
    84			sess, aerr := s.requireAuth(w, r)
