    90			writeData(w, 200, map[string]any{"events": events, "cursor": cursor})
    91			return
    92		}
    93		// WebSocket: authenticate via bearer.<token> subprotocol.
    94		token := ""
    95		for _, p := range strings.Split(r.Header.Get("Sec-WebSocket-Protocol"), ",") {
    96			p = strings.TrimSpace(p)
    97			if strings.HasPrefix(p, "bearer.") {
    98				dec, err := base64.RawURLEncoding.DecodeString(strings.TrimPrefix(p, "bearer."))
    99				if err != nil {
   100					dec, err = base64.URLEncoding.DecodeString(strings.TrimPrefix(p, "bearer."))
