   127		client := &wsClient{sess: sess, conn: conn, send: make(chan *RealtimeEvent, 64)}
   128		s.hub.mu.Lock()
   129		s.hub.clients[client] = true
   130		s.hub.mu.Unlock()
   131		defer func() {
