   133			delete(s.hub.clients, client)
   134			s.hub.mu.Unlock()
   135			conn.Close()
   136		}()
   137		// Replay missed events first.
   138		replayed, _ := s.eventsSinceCtx(r, since, sess)
   139		for _, ev := range replayed {
