   143			for ev := range client.send {
   144				if err := conn.WriteJSON(ev); err != nil {
   145					return
   146				}
   147			}
   148		}()
   149		// Keep the connection alive; discard incoming messages.
   150		conn.SetReadLimit(1024)
   151		for {
