   162	}
   163	
   164	func (s *server) eventsSinceCtx(r *http.Request, since int64, sess *session) ([]*RealtimeEvent, int64) {
   165		rows, err := s.db.Query(r.Context(), `SELECT id, type, entity_type, entity_id, payload, audience_role, audience_user_id, created_at
   166			FROM events WHERE id > $1 ORDER BY id LIMIT 500`, since)
   167		if err != nil {
   168			return nil, since
   169		}
   170		defer rows.Close()
   171		out := []*RealtimeEvent{}
   172		cursor := since
   173		for rows.Next() {
   174			var ev RealtimeEvent
   175			var payload []byte
   176			var createdAt time.Time
   177			if err := rows.Scan(&ev.ID, &ev.Type, &ev.EntityType, &ev.EntityID, &payload, &ev.AudienceRole, &ev.AudienceUserID, &createdAt); err != nil {
   178				continue
   179			}
   180			ev.Payload = map[string]any{}
   181			if v := jsonUnmarshal(payload); v != nil {
   182				if m, ok := v.(map[string]any); ok {
   183					ev.Payload = m
   184				}
   185			}
   186			ev.CreatedAt = fmtTime(createdAt)
   187			if !eventVisibleTo(&ev, sess) {
   188				continue
   189			}
   190			out = append(out, &ev)
   191			if ev.ID > cursor {
   192				cursor = ev.ID
   193			}
   194		}
   195		return out, cursor
   196	}
