// resolveRequester determines who owns the request. Staff may file on behalf
// of another user via requesterId; everyone else files for themselves.
func (s *server) resolveRequester(r *http.Request, sess *session, requesterID string) (string, *apiError) {
	if requesterID == "" || requesterID == sess.User.UserID {
		return sess.User.UserID, nil
	}
	if sess.ActiveRole != RoleAdmin && sess.ActiveRole != RoleDispatcher {
		return "", errOf(403, "forbidden", "only staff may file a request on behalf of another user")
	}
	if _, err := loadUser(r.Context(), s.db, requesterID); err != nil {
		return "", errOf(404, "not_found", "requesterId does not reference a user")
	}
	return requesterID, nil
}

