		VALUES ($1,$2,$3,$4,FALSE,$5,$6,$7)`,
		sampleID, requestID, requesterID, SampleRequested, body.Origin.Latitude, body.Origin.Longitude, nowUTC())
	if err != nil {
		return 500, nil, errOf(500, "internal_error", err.Error())
	}
	res := s.evaluateServiceability(ctx, body.OriginType, body.Origin.Latitude, body.Origin.Longitude,
		originNodeID, st, requestedAt, earliest, latest, deadline)
	serviceability := "unserviceable"
	reason := res.Reason
	if res.Serviceable {
		serviceability = "serviceable"
		reason = ""
	}
	_, _ = s.db.Exec(ctx, `UPDATE samples SET serviceability=$2, serviceability_reason=$3 WHERE sample_id=$1`, sampleID, serviceability, reason)

