		req, _ := loadRequest(ctx, s.db, requestID)
		start := earliest
		if nowUTC().After(start) {
			start = nowUTC()
		}
		j, aerr := s.createJourneyPlan(ctx, sess, sample, req, st, res.EntryID, res.Route, start, false, "")
		if aerr != nil {
			_, _ = s.db.Exec(ctx, `UPDATE samples SET serviceability='unserviceable', serviceability_reason=$2 WHERE sample_id=$1`, sampleID, "insufficient_capacity")
			serviceability = "unserviceable"
			reason = "insufficient_capacity"
		} else {
			journeyID = j.JourneyID
			labID = res.LabID
			_, _ = s.db.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3 WHERE sample_id=$1`, sampleID, journeyID, labID)
			s.kickOffers(ctx, sess, journeyID)
			for _, a := range journeyAssignments(ctx, s.db, journeyID) {
				if a.Status == AsgOffered || a.Status == AsgAccepted || a.Status == AsgPending {
					activeAssignmentIDs = append(activeAssignmentIDs, a.AssignmentID)
				}
			}
		}
	}
	s.audit(ctx, sess, "create_collection_request", "request", requestID, true,
		map[string]any{"sampleId": sampleID, "serviceability": serviceability, "reason": reason})
	s.audit(ctx, sess, "status_change", "sample", sampleID, true, map[string]any{"status": SampleRequested})
	s.emit(ctx, "request_created", "request", requestID, map[string]any{"requestId": requestID, "sampleId": sampleID}, "", "")
	s.emit(ctx, "sample_status", "sample", sampleID, map[string]any{"sampleId": sampleID, "status": SampleRequested}, "", "")
	out := map[string]any{
