func (s *server) createCollectionRequest(r *http.Request, sess *session, body *requestBodyIn) (int, any, *apiError) {
	ctx := r.Context()
	st, requestedAt, deadline, earliest, latest, originNodeID, aerr := s.validateRequestBody(r, body)
	if aerr != nil {
		return aerr.HTTPStatus, nil, aerr
	}
	if body.OriginType == "node" {
