func (s *server) ingestPresealed(r *http.Request, sess *session, body *requestBodyIn) (int, any, *apiError) {
	ctx := r.Context()
	if body.OriginType == "" {
		body.OriginType = "clinic"
	}
	if body.OriginType == "home" {
