		requestedAt, deadline, earliest, latest, body.SampleTypeID, body.ContainerType,
		*body.TemperatureMinC, *body.TemperatureMaxC, incompat)
	if err != nil {
		return 500, nil, errOf(500, "internal_error", err.Error())
	}
	now := nowUTC()
	_, err = s.db.Exec(ctx, `INSERT INTO samples (sample_id, request_id, requester_id, status, sealed, sealed_at,
		current_holder_id, latest_lat, latest_lng, location_recorded_at)
		VALUES ($1,$2,$3,$4,TRUE,$5,$6,$7,$8,$9)`,
		sampleID, requestID, sess.User.UserID, SampleSealed, now, sess.User.UserID,
		body.Origin.Latitude, body.Origin.Longitude, now)
	if err != nil {
		return 500, nil, errOf(500, "internal_error", err.Error())
	}
