		req, _ := loadRequest(ctx, s.db, requestID)
		j, aerr := s.createJourneyPlan(ctx, sess, sample, req, st, res.EntryID, res.Route, now, true, sess.User.UserID)
		if aerr != nil {
			_, _ = s.db.Exec(ctx, `UPDATE samples SET serviceability='unserviceable', serviceability_reason='insufficient_capacity' WHERE sample_id=$1`, sampleID)
			serviceability = "unserviceable"
			reason = "insufficient_capacity"
		} else {
