	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"time"
)

var validOriginTypes = []string{"home", "clinic", "node"}

// requestBodyIn is shared by create-collection-request and ingest-presealed-sample.
type requestBodyIn struct {
	RequesterID string `json:"requesterId"`
	Origin *struct {
		Latitude  float64 `json:"latitude"`
		Longitude float64 `json:"longitude"`
	} `json:"origin"`
	OriginType           string   `json:"originType"`
	OriginNodeID         string   `json:"originNodeId"`
	RequestedAt          string   `json:"requestedAt"`
	DeliveryDeadline     string   `json:"deliveryDeadline"`
	EarliestCollectionAt string   `json:"earliestCollectionAt"`
	LatestCollectionAt   string   `json:"latestCollectionAt"`
	SampleTypeID         string   `json:"sampleTypeId"`
	ContainerType        string   `json:"containerType"`
	TemperatureMinC      *float64 `json:"temperatureMinC"`
	TemperatureMaxC      *float64 `json:"temperatureMaxC"`
	IncompatibleSampleTypes []string `json:"incompatibleSampleTypes"`
	IdempotencyKey       string   `json:"idempotencyKey"`
}

// validateRequestBody performs common validation and returns parsed values.
func (s *server) validateRequestBody(r *http.Request, body *requestBodyIn) (
	st *SampleType, requestedAt, deadline, earliest, latest time.Time, originNodeID *string, aerr *apiError) {

	if body.Origin == nil || !validCoordinate(body.Origin.Latitude, body.Origin.Longitude) {
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "invalid_origin", "origin must be a valid coordinate")
	}
	if body.OriginType == "" {
		body.OriginType = "home"
	}
	if !containsString(validOriginTypes, body.OriginType) {
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "invalid_origin_type", "originType must be home, clinic or node")
	}
	if body.OriginType == "node" {
		if body.OriginNodeID == "" || !isUUID(body.OriginNodeID) {
			return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "invalid_origin", "originNodeId is required for node origins")
		}
		originNodeID = &body.OriginNodeID
	}
	var ok bool
	requestedAt, ok = parseTime(body.RequestedAt)
	if !ok {
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "invalid_time", "requestedAt must be an RFC3339 timestamp")
	}
	deadline, ok = parseTime(body.DeliveryDeadline)
	if !ok {
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "invalid_time", "deliveryDeadline must be an RFC3339 timestamp")
	}
	if !deadline.After(requestedAt) {
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "invalid_deadline", "deliveryDeadline must be after requestedAt")
	}
	earliest = requestedAt
	if body.EarliestCollectionAt != "" {
		earliest, ok = parseTime(body.EarliestCollectionAt)
		if !ok {
			return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "invalid_time", "earliestCollectionAt must be an RFC3339 timestamp")
			return
		}
	}
	latest = deadline
	if body.LatestCollectionAt != "" {
		latest, ok = parseTime(body.LatestCollectionAt)
		if !ok {
			return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "invalid_time", "latestCollectionAt must be an RFC3339 timestamp")
		}
	}
	if latest.Before(earliest) {
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "invalid_collection_window", "latestCollectionAt must not be before earliestCollectionAt")
	}
	if body.TemperatureMinC == nil || body.TemperatureMaxC == nil {
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "invalid_json", "temperatureMinC and temperatureMaxC are required")
	}
	if *body.TemperatureMinC > *body.TemperatureMaxC {
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "handling_mismatch", "temperatureMinC must not exceed temperatureMaxC")
	}
	st, err := loadSampleType(r.Context(), s.db, body.SampleTypeID)
	if err != nil {
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(404, "not_found", "sample type not found")
	}
	if body.ContainerType != "" && st.ContainerType != "" && body.ContainerType != st.ContainerType {
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "handling_mismatch", "containerType does not match the sample type's required container")
	}
	if *body.TemperatureMinC < st.TempMinC || *body.TemperatureMaxC > st.TempMaxC {
		return nil, time.Time{}, time.Time{}, time.Time{}, time.Time{}, nil, errOf(400, "handling_mismatch", "temperature range is outside the sample type's required range")
	}
	return st, requestedAt, deadline, earliest, latest, originNodeID, nil
}

