	s.audit(ctx, sess, "custody", "sample", sampleID, true, map[string]any{"holderId": sess.User.UserID, "note": "registered pre-sealed"})
	s.emit(ctx, "sample_status", "sample", sampleID, map[string]any{"sampleId": sampleID, "status": SampleSealed}, "", "")
	out := map[string]any{
		"requestId":            requestID,
		"sampleId":             sampleID,
		"serviceability":       serviceability,
		"serviceabilityReason": reason,
		"activeAssignmentIds":  activeAssignmentIDs,
		"earliestCollectionAt": fmtTime(earliest),
		"latestCollectionAt":   fmtTime(latest),
		"alreadySealed":        true,
		"originType":           body.OriginType,
	}
	if journeyID != "" {
		out["journeyId"] = journeyID
	}
	if labID != "" {
		out["targetLaboratoryId"] = labID
	}
	return 201, out, nil
}

