		originNodeID, st, requestedAt, earliest, latest, deadline)
	s.audit(r.Context(), sess, "check_serviceability", "sample_type", body.SampleTypeID, true,
		map[string]any{"serviceable": res.Serviceable, "reason": res.Reason, "dryRun": true})
	reason := res.Reason
