   339			}
   340		switch status {
   341			case "exception":
   342				return 409, nil, errOf(409, "no_valid_route", "no valid route is available for the remaining work")
   343			case "expired":
   344				return 409, nil, errOf(409, "deadline_exceeded", "no route can meet the delivery deadline")
   345			}
