   289		exceptions := []map[string]any{}
   290		for _, sm := range samples {
   291			sid := sm["sampleId"].(string)
   292			status := sm["status"].(string)
   293			if status == SampleException || status == SampleExpired {
   294				exc := map[string]any{"sampleId": sid, "type": status}
   295				if e, ok := sm["exception"].(map[string]any); ok {
   296					if t, ok := e["type"].(string); ok {
   297						exc["type"] = t
   298					}
   299					if r, ok := e["reason"].(string); ok {
   300						exc["reason"] = r
   301					}
   302				}
   303				exceptions = append(exceptions, exc)
   304				continue
   305			}
   306			if status == SampleReceived || status == SampleCancelled {
   307				continue
   308			}
   309			smObj, err := loadSample(ctx, s.db, sid)
   310			if err != nil {
   311				continue
   312			}
   313			req, err := loadRequest(ctx, s.db, smObj.RequestID)
   314			if err != nil {
   315				continue
   316			}
   317			now := nowUTC()
   318			if now.After(req.DeliveryDeadline) {
   319				delays = append(delays, map[string]any{
   320					"sampleId": sid, "type": "deadline_missed",
   321					"detail": "delivery deadline has passed", "observedAt": fmtTime(now),
   322				})
   323			} else if now.Add(30 * time.Minute).After(req.DeliveryDeadline) {
   324				delays = append(delays, map[string]any{
   325					"sampleId": sid, "type": "deadline_risk",
   326					"detail": "delivery deadline is within 30 minutes", "observedAt": fmtTime(now),
   327				})
   328			}
   329		}
   330		// assignment fairness metrics
   331		spread := 0
   332		ineligible := 0
   333		counts := []int{}
   334		for _, w := range workers {
   335			counts = append(counts, w["assignmentCount"].(int))
   336		}
   337		if len(counts) > 0 {
   338			min, max := counts[0], counts[0]
   339			for _, c := range counts {
   340				if c < min {
   341					min = c
   342				}
   343				if c > max {
   344					max = c
   345				}
   346			}
   347			spread = max - min
   348		}
   349		_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments a JOIN journeys j ON j.journey_id=a.journey_id
   350			WHERE a.status='pending' AND j.status IN ('planned','in_progress')`).Scan(&ineligible)
   351		return map[string]any{
   352			"samples":                   samples,
   353			"workers":                   workers,
   354			"locations":                 locations,
   355			"connections":               connections,
   356			"routes":                    routes,
   357			"handoffs":                  handoffs,
   358			"delays":                    delays,
   359			"exceptions":                exceptions,
   360			"assignmentCountSpread":     spread,
   361			"ineligibleAssignmentCount": ineligible,
   362		}
   363	}
   364	
   365	func (s *server) sampleSummaryJSON(ctx context.Context, sm *Sample) map[string]any {
   366		out := map[string]any{
   367			"sampleId":       sm.SampleID,
   368			"status":         sm.Status,
   369			"sealed":         sm.Sealed,
   370			"locationStale":  staleSince(sm.LocationRecordedAt),
   371			"serviceability": sm.Serviceability,
   372		}
   373		if sm.CurrentHolderID != nil {
   374			out["currentHolderId"] = *sm.CurrentHolderID
   375		}
   376		if sm.LatestLat != nil && sm.LatestLng != nil {
   377			out["latestLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLng}
   378		}
   379		if sm.LocationRecordedAt != nil {
   380			out["locationRecordedAt"] = fmtTime(*sm.LocationRecordedAt)
   381		}
   382		if sm.ActiveJourneyID != nil {
   383			out["activeJourneyId"] = *sm.ActiveJourneyID
   384		}
   385		if sm.TargetLaboratoryID != nil {
   386			out["targetLaboratoryId"] = *sm.TargetLaboratoryID
   387		}
   388		if sm.Exception != nil {
   389			out["exception"] = sm.Exception
   390		}
   391		return out
   392	}
   393	
   394	// ---------- journey plan read ----------
   395	
   396	func (s *server) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
   397		sess, aerr := s.requireAuth(w, r)
   398		if aerr != nil {
   399			writeErr(w, aerr)
   400			return
   401		}
   402		if sess.ActiveRole == "" {
   403			writeErr(w, errOf(409, "role_not_selected", "select an active role before performing this action"))
   404			return
   405		}
   406		ctx := r.Context()
   407		j, err := loadJourney(ctx, s.db, r.PathValue("journeyId"))
   408		if err != nil {
   409			writeErr(w, errOf(404, "not_found", "journey not found"))
   410			return
   411		}
   412		switch sess.ActiveRole {
   413		case RoleDispatcher, RoleAdmin:
   414			writeData(w, 200, s.journeyPlanJSON(ctx, j))
   415			return
   416		case RoleRequester:
   417			// requester must own a sample in the journey
   418			owns := false
   419			for _, sid := range journeySampleIDs(ctx, s.db, j.JourneyID) {
   420				sm, err := loadSample(ctx, s.db, sid)
   421				if err == nil && sm.RequesterID == sess.User.UserID {
   422					owns = true
   423					break
   424				}
   425			}
   426			if !owns {
   427				writeErr(w, errOf(403, "forbidden", "this journey does not belong to you"))
   428				return
   429			}
   430			out := map[string]any{
   431				"journeyId": j.JourneyID,
   432				"routeMode": j.RouteMode,
   433				"status":    j.Status,
   434			}
   435			if j.EstimatedDeliveryAt != nil {
   436				out["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
   437				out["etaToLaboratory"] = fmtTime(*j.EstimatedDeliveryAt)
   438			}
   439			// current location/holder from the requester's sample
   440			for _, sid := range journeySampleIDs(ctx, s.db, j.JourneyID) {
   441				sm, err := loadSample(ctx, s.db, sid)
   442				if err == nil && sm.RequesterID == sess.User.UserID {
   443					if sm.LatestLat != nil && sm.LatestLng != nil {
   444						out["currentLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLng}
   445					}
   446					if sm.CurrentHolderID != nil {
   447						out["currentHolderId"] = *sm.CurrentHolderID
   448					}
   449					break
   450				}
   451			}
   452			writeData(w, 200, out)
   453			return
   454		default:
   455			// workers see only their own legs
   456			asgs := journeyAssignments(ctx, s.db, j.JourneyID)
   457			mine := []map[string]any{}
   458			for _, a := range asgs {
   459				if (a.AcceptedBy != nil && *a.AcceptedBy == sess.User.UserID) ||
   460					(a.OfferedTo != nil && *a.OfferedTo == sess.User.UserID) {
   461					mine = append(mine, legJSON(a))
   462				}
   463			}
   464			if len(mine) == 0 {
   465				writeErr(w, errOf(403, "forbidden", "you have no work in this journey"))
   466				return
   467			}
   468			writeData(w, 200, map[string]any{
   469				"journeyId":   j.JourneyID,
   470				"planVersion": j.PlanVersion,
   471				"routeMode":   j.RouteMode,
   472				"status":      j.Status,
   473				"scope":       "assigned_legs",
   474				"legs":        mine,
   475			})
   476			return
   477		}
   478	}
   479	
   480	// ---------- plan version guard ----------
   481	
   482	func checkPlanVersion(j *Journey, expected int) *apiError {
   483		if expected < 1 {
   484			return errOf(400, "invalid_plan_version", "expectedPlanVersion must be at least 1")
   485		}
   486		if j.Status != JourneyPlanned && j.Status != JourneyInProgress {
   487			return errOf(409, "inactive_plan", "the journey is no longer active")
   488		}
   489		if j.PlanVersion != expected {
   490			return errOf(409, "stale_plan", "the journey plan has changed; reload and retry")
   491		}
   492		return nil
   493	}
   494	
   495	// ---------- cancel ----------
   496	
   497	func (s *server) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
   498		sess, aerr := s.requireAuth(w, r)
   499		if aerr != nil {
   500			writeErr(w, aerr)
   501			return
   502		}
   503		if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
   504			writeErr(w, aerr)
   505			return
   506		}
   507		raw, _ := io.ReadAll(r.Body)
   508		r.Body = io.NopCloser(bytes.NewReader(raw))
   509		var body struct {
   510			JourneyID           string `json:"journeyId"`
   511			Reason              string `json:"reason"`
   512			ExpectedPlanVersion int    `json:"expectedPlanVersion"`
   513			IdempotencyKey      string `json:"idempotencyKey"`
   514		}
   515		if aerr := decodeBody(r, &body); aerr != nil {
   516			writeErr(w, aerr)
   517			return
   518		}
   519		s.idempotent(w, r, sess, "cancel_journey", body.IdempotencyKey, raw, func() (int, any, *apiError) {
   520			ctx := r.Context()
   521			j, err := loadJourney(ctx, s.db, body.JourneyID)
   522			if err != nil {
   523				return 404, nil, errOf(404, "not_found", "journey not found")
   524			}
   525			if aerr := checkPlanVersion(j, body.ExpectedPlanVersion); aerr != nil {
   526				return aerr.HTTPStatus, nil, aerr
   527			}
   528			s.cancelJourneyInternal(ctx, sess, j, body.Reason, JourneyCancelled)
   529			sampleIDs := journeySampleIDs(ctx, s.db, j.JourneyID)
   530			for _, sid := range sampleIDs {
   531				s.setSampleStatus(ctx, sess, sid, SampleCancelled, map[string]any{"journeyId": j.JourneyID, "reason": body.Reason})
   532			}
   533			s.audit(ctx, sess, "cancel_journey", "journey", j.JourneyID, true, map[string]any{"reason": body.Reason})
   534			s.emit(ctx, "journey_cancelled", "journey", j.JourneyID, map[string]any{"journeyId": j.JourneyID}, "", "")
   535			return 201, map[string]any{"journeyId": j.JourneyID, "status": JourneyCancelled, "sampleIds": sampleIDs}, nil
   536		})
   537	}
   538	
   539	func (s *server) cancelJourneyInternal(ctx context.Context, sess *session, j *Journey, reason string, status string) {
   540		_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='cancelled', updated_at=now()
   541			WHERE journey_id=$1 AND status IN ('pending','offered','accepted','in_progress')`, j.JourneyID)
   542		_, _ = s.db.Exec(ctx, `UPDATE journeys SET status=$2, updated_at=now() WHERE journey_id=$1`, j.JourneyID, status)
   543		s.releaseJourneyReservations(ctx, j.JourneyID)
   544		// clear pending handoffs
   545		_, _ = s.db.Exec(ctx, `UPDATE handoffs SET status='cancelled' WHERE journey_id=$1 AND status='pending'`, j.JourneyID)
   546		_, _ = s.db.Exec(ctx, `UPDATE samples SET pending_handoff_id=NULL WHERE active_journey_id=$1 AND pending_handoff_id IS NOT NULL`, j.JourneyID)
   547	}
   548	
   549	// ---------- replanning ----------
   550	
   551	// replanJourney replaces the unfinished part of a journey with a fresh plan.
   552	// Returns (replacementJourneyID, replanStatus, error).
   553	func (s *server) replanJourney(ctx context.Context, sess *session, journeyID string) (string, string, *apiError) {
   554		j, err := loadJourney(ctx, s.db, journeyID)
   555		if err != nil {
   556			return "", "", errOf(404, "not_found", "journey not found")
   557		}
   558		if j.Status != JourneyPlanned && j.Status != JourneyInProgress {
   559			return "", "not_required", nil
   560		}

