   268	func sortCands(cands []cand) {
   269		for i := 0; i < len(cands); i++ {
   270			for j := i + 1; j < len(cands); j++ {
   271				a, b := cands[i], cands[j]
   272				less := false
   273				if a.penalty != b.penalty {
   274					less = !a.penalty
   275				} else if a.active != b.active {
   276					less = a.active < b.active
   277				} else {
   278					at, bt := a.u.LastAssignedAt, b.u.LastAssignedAt
   279					switch {
   280					case at == nil && bt != nil:
   281						less = true
   282					case at != nil && bt == nil:
   283						less = false
   284					case at != nil && bt != nil:
   285						less = at.Before(*bt)
   286					default:
   287						less = a.u.UserID < b.u.UserID
   288					}
   289				}
   290				if less {
   291					cands[i], cands[j] = cands[j], cands[i]
   292				}
   293			}
   294		}
   295	}
