   299	// offerAssignment offers an assignment to the best eligible worker. Returns
   300	// (offeredTo, noQualifiedWorker, error).
   301	func (s *server) offerAssignment(ctx context.Context, sess *session, a *Assignment) (*string, bool, error) {
   302		st, err := sampleTypeForSample(ctx, s, a.SampleID)
   303		if err != nil {
   304			return nil, false, err
   305		}
   306		eligible, anyEligible := s.eligibleWorkers(ctx, a, st)
   307		if len(eligible) == 0 {
   308			if !anyEligible {
   309				return nil, true, nil
   310			}
   311			// eligible workers exist but are busy/unavailable; stay pending for the sweeper
   312			_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, updated_at=now() WHERE assignment_id=$1`, a.AssignmentID)
   313			return nil, false, nil
   314		}
   315		workerID := eligible[0]
   316		now := nowUTC()
   317		expires := now.Add(offerTimeout)
   318		_, err = s.db.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offered_at=$3, offer_expires_at=$4, updated_at=now()
   319			WHERE assignment_id=$1`, a.AssignmentID, workerID, now, expires)
   320		if err != nil {
   321			return nil, false, err
   322		}
   323		_, _ = s.db.Exec(ctx, `UPDATE users SET last_assigned_at=$2 WHERE user_id=$1`, workerID, now)
   324		s.audit(ctx, sess, "offer_assignment", "assignment", a.AssignmentID, true,
   325			map[string]any{"workerId": workerID, "kind": a.Kind, "sampleId": a.SampleID})
   326		s.emit(ctx, "assignment_offered", "assignment", a.AssignmentID, map[string]any{
   327			"assignmentId": a.AssignmentID, "workerId": workerID, "kind": a.Kind, "sampleId": a.SampleID,
   328		}, kindRole(a.Kind), workerID)
   329		return &workerID, false, nil
   330	}
