   355	// kickOffers offers all currently-offerable assignments for a journey.
   356	func (s *server) kickOffers(ctx context.Context, sess *session, journeyID string) {
   357		asgs := journeyAssignments(ctx, s.db, journeyID)
   358		for _, a := range asgs {
   359			if a.Status != AsgPending {
   360				continue
   361			}
   362			offerable := false
   363			switch a.Kind {
   364			case KindCollection:
   365				offerable = true
   366			case KindNode, KindLab:
   367				offerable = true
   368			case KindTransport:
   369				if a.Sequence == 1 {
   370					// first transport leg: offer once the sample is sealed
   371					var sealed bool
   372					_ = s.db.QueryRow(ctx, `SELECT sealed FROM samples WHERE sample_id=$1`, a.SampleID).Scan(&sealed)
   373					offerable = sealed
   374				} else {
   375					// later legs: offer once the preceding node assignment is engaged
   376					var prevStatus string
   377					err := s.db.QueryRow(ctx, `SELECT status FROM assignments WHERE journey_id=$1 AND sequence=$2`,
   378						journeyID, a.Sequence-1).Scan(&prevStatus)
   379					offerable = err == nil && (prevStatus == AsgAccepted || prevStatus == AsgInProgress || prevStatus == AsgCompleted)
   380				}
   381			}
   382			if !offerable {
   383				continue
   384			}
   385			offeredTo, noQualified, err := s.offerAssignment(ctx, sess, a)
   386			if err != nil {
   387				continue
   388			}
   389			if noQualified {
   390				s.flagNoQualifiedWorker(ctx, sess, a.SampleID, a.AssignmentID)
   391			} else if offeredTo != nil {
   392				if a.Kind == KindCollection {
   393					s.setSampleStatus(ctx, sess, a.SampleID, SampleAwaitingCollection, map[string]any{"assignmentId": a.AssignmentID})
   394				}
   395			}
   396		}
   397	}
