   399	// offerSweeper periodically expires unanswered offers and retries pending ones.
   400	func (s *server) offerSweeper(ctx context.Context) {
   401		ticker := time.NewTicker(10 * time.Second)
   402		defer ticker.Stop()
   403		for {
   404			select {
   405			case <-ctx.Done():
   406				return
   407			case <-ticker.C:
   408			}
   409			// expire offers
   410			rows, err := s.db.Query(ctx, `SELECT assignment_id FROM assignments WHERE status='offered' AND offer_expires_at < now()`)
   411			if err == nil {
   412				ids := []string{}
   413				for rows.Next() {
   414					var id string
   415					_ = rows.Scan(&id)
   416					ids = append(ids, id)
   417				}
   418				rows.Close()
   419				for _, id := range ids {
   420					a, err := loadAssignment(ctx, s.db, id)
   421					if err != nil || a.OfferedTo == nil {
   422						continue
   423					}
   424					declined := append(a.DeclinedBy, *a.OfferedTo)
   425					dj, _ := json.Marshal(declined)
   426					_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$2, updated_at=now()
   427						WHERE assignment_id=$1`, id, dj)
   428					_, _ = s.db.Exec(ctx, `UPDATE users SET recent_declines = recent_declines + 1, last_decline_at=now() WHERE user_id=$1`, *a.OfferedTo)
   429					s.audit(ctx, nil, "offer_expired", "assignment", id, true, map[string]any{"workerId": *a.OfferedTo})
   430				}
   431			}
   432			// retry pending assignments on active journeys
   433			jrows, err := s.db.Query(ctx, `SELECT DISTINCT journey_id FROM assignments a JOIN journeys j ON j.journey_id=a.journey_id
   434				WHERE a.status='pending' AND j.status IN ('planned','in_progress')`)
   435			if err == nil {
   436				jids := []string{}
   437				for jrows.Next() {
   438					var id string
   439					_ = jrows.Scan(&id)
   440					jids = append(jids, id)
   441				}
   442				jrows.Close()
   443				for _, jid := range jids {
   444					s.kickOffers(ctx, nil, jid)
   445				}
   446			}
   447		}
   448	}
