    13	func (s *server) rebuildRoute(ctx context.Context, j *Journey, start time.Time) *routeResult {
    14		route := &routeResult{
    15			ConnectionIDs: j.ConnectionIDs,
    16			NodeIDs:       j.NodeIDs,
    17		}
    18		if j.LaboratoryID != nil {
    19			route.LabID = *j.LaboratoryID
    20		}
    21		t := start
    22		for i, cid := range j.ConnectionIDs {
    23			c, err := loadConnection(ctx, s.db, cid)
    24			if err != nil {
    25				continue
    26			}
    27			route.TravelMinutes += c.TravelMinutes
    28			route.TotalCost += c.CostUnits
    29			t = t.Add(time.Duration(c.TravelMinutes) * time.Minute)
    30			if i < len(j.ConnectionIDs)-1 {
    31				if nl, err := loadLocation(ctx, s.db, c.ToLocationID); err == nil {
    32					route.HandlingMinutes += nl.HandlingMinutes
    33					t = t.Add(time.Duration(nl.HandlingMinutes) * time.Minute)
    34				}
    35			}
    36		}
    37		route.Arrival = t
    38		return route
    39	}
