package main

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"net/http"
	"time"
)

// ---------- journey plan serialization ----------

func legJSON(a *Assignment) map[string]any {
	out := map[string]any{
		"assignmentId": a.AssignmentID,
		"sequence":     a.Sequence,
		"status":       a.Status,
		"sampleId":     a.SampleID,
	}
	if a.FromLocationID != nil {
		out["fromLocationId"] = *a.FromLocationID
	}
	if a.ToLocationID != nil {
		out["toLocationId"] = *a.ToLocationID
	}
	worker := a.AcceptedBy
	if worker == nil {
		worker = a.OfferedTo
	}
	if worker != nil {
		out["workerId"] = *worker
	}
	return out
}

func (s *server) journeyPlanJSON(ctx context.Context, j *Journey) map[string]any {
	asgs := journeyAssignments(ctx, s.db, j.JourneyID)
	legs := []map[string]any{}
	collectionIDs := []string{}
	nodeIDs := []string{}
	labIDs := []string{}
	transportIDs := []string{}
	for _, a := range asgs {
		switch a.Kind {
		case KindTransport:
			legs = append(legs, legJSON(a))
			transportIDs = append(transportIDs, a.AssignmentID)
		case KindCollection:
			collectionIDs = append(collectionIDs, a.AssignmentID)
		case KindNode:
			nodeIDs = append(nodeIDs, a.AssignmentID)
		case KindLab:
			labIDs = append(labIDs, a.AssignmentID)
		}
	}
	out := map[string]any{
		"journeyId":                 j.JourneyID,
		"planVersion":               j.PlanVersion,
		"routeMode":                 j.RouteMode,
		"status":                    j.Status,
		"totalCostUnits":            j.TotalCostUnits,
		"sampleIds":                 journeySampleIDs(ctx, s.db, j.JourneyID),
		"stops":                     j.Stops,
		"legs":                      legs,
		"collectionAssignmentIds":   collectionIDs,
		"nodeAssignmentIds":         nodeIDs,
		"laboratoryAssignmentIds":   labIDs,
	}
	if j.ParentJourneyID != nil {
		out["parentJourneyId"] = *j.ParentJourneyID
	}
	if j.EstimatedDeliveryAt != nil {
		out["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
	}
	if len(transportIDs) > 0 {
		out["firstTransportAssignmentId"] = transportIDs[0]
		out["finalTransportAssignmentId"] = transportIDs[len(transportIDs)-1]
		if len(transportIDs) > 2 {
			out["middleTransportAssignmentIds"] = transportIDs[1 : len(transportIDs)-1]
		}
	}
	if j.ReplanStatus != nil {
		out["replanStatus"] = *j.ReplanStatus
	}
	if j.ReplacementJourneyID != nil {
		if rj, err := loadJourney(ctx, s.db, *j.ReplacementJourneyID); err == nil {
			out["replacementJourney"] = s.journeyPlanJSON(ctx, rj)
		}
	}
	return out
}

// ---------- operations state ----------

func (s *server) handleReadOperationsState(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin, RoleNode, RoleLab); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		Filters *struct {
			SampleTypeID string `json:"sampleTypeId"`
		} `json:"filters"`
	}
	if r.Body != nil && r.ContentLength > 0 {
		if aerr := decodeBody(r, &body); aerr != nil {
			writeErr(w, aerr)
			return
		}
	}
	filter := ""
	if body.Filters != nil {
		filter = body.Filters.SampleTypeID
	}
	ctx := r.Context()
	writeData(w, 200, s.operationsState(ctx, filter))
}

func (s *server) operationsState(ctx context.Context, sampleTypeFilter string) map[string]any {
	// samples
	samples := []map[string]any{}
	srows, err := s.db.Query(ctx, `SELECT sample_id FROM samples ORDER BY created_at`)
	if err == nil {
		ids := []string{}
		for srows.Next() {
			var id string
			_ = srows.Scan(&id)
			ids = append(ids, id)
		}
		srows.Close()
		for _, id := range ids {
			sm, err := loadSample(ctx, s.db, id)
			if err != nil {
				continue
			}
			if sampleTypeFilter != "" {
				req, err := loadRequest(ctx, s.db, sm.RequestID)
				if err != nil || req.SampleTypeID != sampleTypeFilter {
					continue
				}
			}
			samples = append(samples, s.sampleSummaryJSON(ctx, sm))
		}
	}
	// workers
	workers := []map[string]any{}
	wrows, err := s.db.Query(ctx, `SELECT `+userCols+` FROM users WHERE active=TRUE ORDER BY created_at`)
	if err == nil {
		for wrows.Next() {
			u, err := scanUser(wrows)
			if err != nil {
				continue
			}
			isWorker := false
			for _, role := range u.Roles {
				if containsString(workerRoles, role) {
					isWorker = true
				}
			}
			if !isWorker {
				continue
			}
			var asgCount int
			_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE accepted_by=$1 AND status IN ('accepted','in_progress')`, u.UserID).Scan(&asgCount)
			status := "unavailable"
			if u.Available {
				status = "available"
			}
			entry := map[string]any{
				"workerId":        u.UserID,
				"fullName":        u.FullName,
				"roles":           u.Roles,
				"available":       u.Available,
				"status":          status,
				"capacityUnits":   u.CapacityUnits,
				"assignmentCount": asgCount,
				"locationStale":   staleSince(u.LocationRecordedAt),
			}
			if u.LatestLat != nil && u.LatestLng != nil {
				entry["latestLocation"] = map[string]any{"latitude": *u.LatestLat, "longitude": *u.LatestLng}
			}
			if u.LocationRecordedAt != nil {
				entry["locationRecordedAt"] = fmtTime(*u.LocationRecordedAt)
			}
			workers = append(workers, entry)
		}
		wrows.Close()
	}
	// locations
	locations := []map[string]any{}
	lrows, err := s.db.Query(ctx, `SELECT location_id FROM locations ORDER BY created_at`)
	if err == nil {
		ids := []string{}
		for lrows.Next() {
			var id string
			_ = lrows.Scan(&id)
			ids = append(ids, id)
		}
		lrows.Close()
		for _, id := range ids {
			l, err := loadLocation(ctx, s.db, id)
			if err != nil {
				continue
			}
			locations = append(locations, map[string]any{
				"id":              l.LocationID,
				"locationId":      l.LocationID,
				"name":            l.Name,
				"coordinate":      map[string]any{"latitude": l.Lat, "longitude": l.Lng},
				"functions":       l.Functions,
				"active":          l.Active,
				"coverageKm":      l.CoverageKm,
				"handlingMinutes": l.HandlingMinutes,
				"capacity":        capacityJSON(l.CapacityUnits, l.ReservedUnits, l.CooledCapacity, l.CooledReserved),
				"acceptedSampleTypeIds": l.AcceptedTypeIDs,
			})
		}
	}
	// connections
	connections := []map[string]any{}
	crows, err := s.db.Query(ctx, `SELECT connection_id FROM connections ORDER BY created_at`)
	if err == nil {
		ids := []string{}
		for crows.Next() {
			var id string
			_ = crows.Scan(&id)
			ids = append(ids, id)
		}
		crows.Close()
		for _, id := range ids {
			c, err := loadConnection(ctx, s.db, id)
			if err != nil {
				continue
			}
			connections = append(connections, map[string]any{
				"id":             c.ConnectionID,
				"connectionId":   c.ConnectionID,
				"fromLocationId": c.FromLocationID,
				"toLocationId":   c.ToLocationID,
				"travelMinutes":  c.TravelMinutes,
				"costUnits":      c.CostUnits,
				"cooled":         c.Cooled,
				"active":         c.Active,
				"capacity":       capacityJSON(c.CapacityUnits, c.ReservedUnits, c.CooledCapacity, c.CooledReserved),
			})
		}
	}
	// routes (journey summaries)
	routes := []map[string]any{}
	jrows, err := s.db.Query(ctx, `SELECT journey_id FROM journeys ORDER BY created_at`)
	if err == nil {
		ids := []string{}
		for jrows.Next() {
			var id string
			_ = jrows.Scan(&id)
			ids = append(ids, id)
		}
		jrows.Close()
		for _, id := range ids {
			j, err := loadJourney(ctx, s.db, id)
			if err != nil {
				continue
			}
			entry := map[string]any{
				"journeyId":   j.JourneyID,
				"planVersion": j.PlanVersion,
				"routeMode":   j.RouteMode,
				"status":      j.Status,
				"sampleIds":   journeySampleIDs(ctx, s.db, j.JourneyID),
			}
			if j.EstimatedDeliveryAt != nil {
				entry["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
			}
			routes = append(routes, entry)
		}
	}
	// pending handoffs
	handoffs := []map[string]any{}
	hrows, err := s.db.Query(ctx, `SELECT handoff_id, sample_id, sender_id, receiver_id, status, initiated_at FROM handoffs WHERE status='pending' ORDER BY initiated_at`)
	if err == nil {
		for hrows.Next() {
			var hid, sid, sender, receiver, status string
			var initiated time.Time
			if err := hrows.Scan(&hid, &sid, &sender, &receiver, &status, &initiated); err != nil {
				continue
			}
			handoffs = append(handoffs, map[string]any{
				"handoffId":   hid,
				"sampleId":    sid,
				"senderId":    sender,
				"receiverId":  receiver,
				"status":      status,
				"initiatedAt": fmtTime(initiated),
			})
		}
		hrows.Close()
	}
	// delays: unfinished samples whose deadline is near or passed
	delays := []map[string]any{}
	exceptions := []map[string]any{}
	for _, sm := range samples {
		sid := sm["sampleId"].(string)
		status := sm["status"].(string)
		if status == SampleReceived || status == SampleCancelled {
			continue
		}
		smObj, err := loadSample(ctx, s.db, sid)
		if err != nil {
			continue
		}
		if status == SampleException || status == SampleExpired {
			exc := map[string]any{"sampleId": sid, "type": status}
			if smObj.Exception != nil {
				if t, ok := smObj.Exception["type"].(string); ok {
					exc["type"] = t
				}
				if r, ok := smObj.Exception["reason"].(string); ok {
					exc["reason"] = r
				}
			}
			exceptions = append(exceptions, exc)
			continue
		}
		req, err := loadRequest(ctx, s.db, smObj.RequestID)
		if err != nil {
			continue
		}
		now := nowUTC()
		if now.After(req.DeliveryDeadline) {
			delays = append(delays, map[string]any{
				"sampleId": sid, "type": "deadline_missed",
				"detail": "delivery deadline has passed", "observedAt": fmtTime(now),
			})
		} else if now.Add(30 * time.Minute).After(req.DeliveryDeadline) {
			delays = append(delays, map[string]any{
				"sampleId": sid, "type": "deadline_risk",
				"detail": "delivery deadline is within 30 minutes", "observedAt": fmtTime(now),
			})
		}
	}
	// assignment fairness metrics
	spread := 0
	ineligible := 0
	counts := []int{}
	for _, w := range workers {
		counts = append(counts, w["assignmentCount"].(int))
	}
	if len(counts) > 0 {
		min, max := counts[0], counts[0]
		for _, c := range counts {
			if c < min {
				min = c
			}
			if c > max {
				max = c
			}
		}
		spread = max - min
	}
	_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments a JOIN journeys j ON j.journey_id=a.journey_id
		WHERE a.status='pending' AND j.status IN ('planned','in_progress')`).Scan(&ineligible)
	return map[string]any{
		"samples":                   samples,
		"workers":                   workers,
		"locations":                 locations,
		"connections":               connections,
		"routes":                    routes,
		"handoffs":                  handoffs,
		"delays":                    delays,
		"exceptions":                exceptions,
		"assignmentCountSpread":     spread,
		"ineligibleAssignmentCount": ineligible,
	}
}

func (s *server) sampleSummaryJSON(ctx context.Context, sm *Sample) map[string]any {
	out := map[string]any{
		"sampleId":      sm.SampleID,
		"status":        sm.Status,
		"requestId":     sm.RequestID,
		"locationStale": staleSince(sm.LocationRecordedAt),
	}
	if req, err := loadRequest(ctx, s.db, sm.RequestID); err == nil {
		out["origin"] = map[string]any{"latitude": req.OriginLat, "longitude": req.OriginLng}
		out["deliveryDeadline"] = fmtTime(req.DeliveryDeadline)
	}
	if sm.CurrentHolderID != nil {
		out["currentHolderId"] = *sm.CurrentHolderID
	}
	if sm.LatestLat != nil && sm.LatestLng != nil {
		out["latestLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLng}
	}
	if sm.LocationRecordedAt != nil {
		out["locationRecordedAt"] = fmtTime(*sm.LocationRecordedAt)
	}
	if sm.ActiveJourneyID != nil {
		out["activeJourneyId"] = *sm.ActiveJourneyID
	}
	return out
}

// ---------- journey plan read ----------

func (s *server) handleReadJourneyPlan(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if sess.ActiveRole == "" {
		writeErr(w, errOf(409, "role_not_selected", "select an active role before performing this action"))
		return
	}
	var body struct {
		JourneyID string `json:"journeyId"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	ctx := r.Context()
	j, err := loadJourney(ctx, s.db, body.JourneyID)
	if err != nil {
		writeErr(w, errOf(404, "not_found", "journey not found"))
		return
	}
	switch sess.ActiveRole {
	case RoleDispatcher, RoleAdmin:
		writeData(w, 200, s.journeyPlanJSON(ctx, j))
		return
	case RoleRequester:
		// requester must own a sample in the journey
		owns := false
		for _, sid := range journeySampleIDs(ctx, s.db, j.JourneyID) {
			sm, err := loadSample(ctx, s.db, sid)
			if err == nil && sm.RequesterID == sess.User.UserID {
				owns = true
				break
			}
		}
		if !owns {
			writeErr(w, errOf(403, "forbidden", "this journey does not belong to you"))
			return
		}
		out := map[string]any{
			"journeyId": j.JourneyID,
			"routeMode": j.RouteMode,
			"status":    j.Status,
		}
		if j.EstimatedDeliveryAt != nil {
			out["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
			out["etaToLaboratory"] = fmtTime(*j.EstimatedDeliveryAt)
		}
		// current location/holder from the requester's sample
		for _, sid := range journeySampleIDs(ctx, s.db, j.JourneyID) {
			sm, err := loadSample(ctx, s.db, sid)
			if err == nil && sm.RequesterID == sess.User.UserID {
				if sm.LatestLat != nil && sm.LatestLng != nil {
					out["currentLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLng}
				}
				if sm.CurrentHolderID != nil {
					out["currentHolderId"] = *sm.CurrentHolderID
				}
				break
			}
		}
		writeData(w, 200, out)
		return
	default:
		// workers see only their own legs
		asgs := journeyAssignments(ctx, s.db, j.JourneyID)
		mine := []map[string]any{}
		for _, a := range asgs {
			if (a.AcceptedBy != nil && *a.AcceptedBy == sess.User.UserID) ||
				(a.OfferedTo != nil && *a.OfferedTo == sess.User.UserID) {
				mine = append(mine, legJSON(a))
			}
		}
		if len(mine) == 0 {
			writeErr(w, errOf(403, "forbidden", "you have no work in this journey"))
			return
		}
		writeData(w, 200, map[string]any{
			"journeyId":   j.JourneyID,
			"planVersion": j.PlanVersion,
			"routeMode":   j.RouteMode,
			"status":      j.Status,
			"scope":       "assigned_legs",
			"legs":        mine,
		})
		return
	}
}

// ---------- plan version guard ----------

func checkPlanVersion(j *Journey, expected int) *apiError {
	if expected < 1 {
		return errOf(400, "expected_plan_version_required", "expectedPlanVersion must be at least 1")
	}
	if j.Status != JourneyPlanned && j.Status != JourneyInProgress {
		return errOf(409, "inactive_plan", "the journey is no longer active")
	}
	if j.PlanVersion != expected {
		return errOf(409, "stale_plan", "the journey plan has changed; reload and retry")
	}
	return nil
}

// ---------- cancel ----------

func (s *server) handleCancelJourney(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		JourneyID           string `json:"journeyId"`
		Reason              string `json:"reason"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "cancel_journey", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		j, err := loadJourney(ctx, s.db, body.JourneyID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "journey not found")
		}
		if aerr := checkPlanVersion(j, body.ExpectedPlanVersion); aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
		s.cancelJourneyInternal(ctx, sess, j, body.Reason, JourneyCancelled)
		sampleIDs := journeySampleIDs(ctx, s.db, j.JourneyID)
		for _, sid := range sampleIDs {
			s.setSampleStatus(ctx, sess, sid, SampleCancelled, map[string]any{"journeyId": j.JourneyID, "reason": body.Reason})
		}
		s.audit(ctx, sess, "cancel_journey", "journey", j.JourneyID, true, map[string]any{"reason": body.Reason})
		s.emit(ctx, "journey_cancelled", "journey", j.JourneyID, map[string]any{"journeyId": j.JourneyID}, "", "")
		return 201, map[string]any{"journeyId": j.JourneyID, "status": JourneyCancelled, "sampleIds": sampleIDs}, nil
	})
}

func (s *server) cancelJourneyInternal(ctx context.Context, sess *session, j *Journey, reason string, status string) {
	_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='cancelled', updated_at=now()
		WHERE journey_id=$1 AND status IN ('pending','offered','accepted','in_progress')`, j.JourneyID)
	_, _ = s.db.Exec(ctx, `UPDATE journeys SET status=$2, updated_at=now() WHERE journey_id=$1`, j.JourneyID, status)
	s.releaseJourneyReservations(ctx, j.JourneyID)
	// clear pending handoffs
	_, _ = s.db.Exec(ctx, `UPDATE handoffs SET status='cancelled' WHERE journey_id=$1 AND status='pending'`, j.JourneyID)
	_, _ = s.db.Exec(ctx, `UPDATE samples SET pending_handoff_id=NULL WHERE active_journey_id=$1 AND pending_handoff_id IS NOT NULL`, j.JourneyID)
}

// ---------- replanning ----------

// replanJourney replaces the unfinished part of a journey with a fresh plan.
// Returns (replacementJourneyID, replanStatus, error).
func (s *server) replanJourney(ctx context.Context, sess *session, journeyID string) (string, string, *apiError) {
	j, err := loadJourney(ctx, s.db, journeyID)
	if err != nil {
		return "", "", errOf(404, "not_found", "journey not found")
	}
	if j.Status != JourneyPlanned && j.Status != JourneyInProgress {
		return "", "not_required", nil
	}
	sampleIDs := journeySampleIDs(ctx, s.db, journeyID)
	if len(sampleIDs) == 0 {
		return "", "not_required", nil
	}
	sample, err := loadSample(ctx, s.db, sampleIDs[0])
	if err != nil {
		return "", "", errOf(404, "not_found", "sample not found")
	}
	if sample.Status == SampleReceived || sample.Status == SampleCancelled || sample.Status == SampleExpired {
		return "", "not_required", nil
	}
	req, err := loadRequest(ctx, s.db, sample.RequestID)
	if err != nil {
		return "", "", errOf(404, "not_found", "request not found")
	}
	st, err := loadSampleType(ctx, s.db, req.SampleTypeID)
	if err != nil {
		return "", "", errOf(404, "not_found", "sample type not found")
	}

	// Determine where the remaining plan must start.
	asgs := journeyAssignments(ctx, s.db, journeyID)
	position := ""
	anchorMode := "collection"
	var anchorWorker string
	var preserveAssignment *Assignment
	if j.EntryLocationID != nil {
		position = *j.EntryLocationID
	}
	switch sample.Status {
	case SampleRequested, SampleAwaitingCollection:
		anchorMode = "collection"
	case SampleSealed, SampleAtNode:
		anchorMode = "intake"
		if sample.CurrentHolderID != nil {
			anchorWorker = *sample.CurrentHolderID
		}
		// find the node where the holder is: the accepted/in-progress node assignment
		for _, a := range asgs {
			if a.Kind == KindNode && (a.Status == AsgInProgress || a.Status == AsgAccepted) &&
				a.AcceptedBy != nil && sample.CurrentHolderID != nil && *a.AcceptedBy == *sample.CurrentHolderID && a.NodeID != nil {
				position = *a.NodeID
			}
		}
	case SampleInTransit:
		// preserve the in-progress transport leg; replan from its destination
		for _, a := range asgs {
			if a.Kind == KindTransport && a.Status == AsgInProgress && a.ToLocationID != nil {
				position = *a.ToLocationID
				preserveAssignment = a
			}
		}
		if preserveAssignment == nil {
			// courier holds custody but has not started; replan from the origin of their leg
			for _, a := range asgs {
				if a.Kind == KindTransport && a.Status == AsgAccepted && a.AcceptedBy != nil &&
					sample.CurrentHolderID != nil && *a.AcceptedBy == *sample.CurrentHolderID && a.FromLocationID != nil {
					position = *a.FromLocationID
					anchorMode = "intake"
					anchorWorker = *sample.CurrentHolderID
				}
			}
		} else {
			anchorMode = "node"
		}
	case SampleAtLaboratory:
		return "", "not_required", nil
	default:
		anchorMode = "intake"
		if sample.CurrentHolderID != nil {
			anchorWorker = *sample.CurrentHolderID
		}
	}
	if position == "" {
		return "", "not_required", nil
	}

	locs, conns, err := s.activeNetwork(ctx)
	if err != nil {
		return "", "", errOf(500, "internal_error", err.Error())
	}
	start := nowUTC()
	routes := computeRoutes(locs, conns, position, st, start)
	if len(routes) == 0 {
		for _, sid := range sampleIDs {
			s.markSampleException(ctx, sess, sid, "no_route", "no valid route is available after replanning")
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET replan_status='exception', updated_at=now() WHERE journey_id=$1`, journeyID)
		return "", "exception", nil
	}
	var route *routeResult
	for _, cand := range routes {
		if !routeCapacityOK(locs, conns, cand, position, st.RequiresCooled) {
			continue
		}
		if !cand.Arrival.After(req.DeliveryDeadline) {
			route = cand
			break
		}
	}
	if route == nil {
		anyCapacity := false
		for _, cand := range routes {
			if routeCapacityOK(locs, conns, cand, position, st.RequiresCooled) {
				anyCapacity = true
				break
			}
		}
		if !anyCapacity {
			for _, sid := range sampleIDs {
				s.markSampleException(ctx, sess, sid, "insufficient_capacity", "no route with available capacity after replanning")
			}
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET replan_status='exception', updated_at=now() WHERE journey_id=$1`, journeyID)
			return "", "exception", nil
		}
		for _, sid := range sampleIDs {
			_, _ = s.db.Exec(ctx, `UPDATE samples SET status=$2, updated_at=now() WHERE sample_id=$1`, sid, SampleExpired)
			s.audit(ctx, sess, "status_change", "sample", sid, true, map[string]any{"status": SampleExpired, "reason": "deadline_unreachable_after_replan"})
			s.emit(ctx, "sample_status", "sample", sid, map[string]any{"sampleId": sid, "status": SampleExpired}, "", "")
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET replan_status='expired', updated_at=now() WHERE journey_id=$1`, journeyID)
		return "", "expired", nil
	}

	// Build the replacement journey for every sample of the old journey.
	var replacementID string
	for i, sid := range sampleIDs {
		sm, err := loadSample(ctx, s.db, sid)
		if err != nil {
			continue
		}
		rq, err := loadRequest(ctx, s.db, sm.RequestID)
		if err != nil {
			continue
		}
		stx, err := loadSampleType(ctx, s.db, rq.SampleTypeID)
		if err != nil {
			continue
		}
		var nj *Journey
		var aerr *apiError
		if i == 0 {
			nj, aerr = s.createJourneyPlan(ctx, sess, sm, rq, stx, position, route, start,
				anchorMode == "intake", anchorWorker)
		} else {
			nj, aerr = s.createJourneyPlan(ctx, sess, sm, rq, stx, position, route, start,
				anchorMode == "intake", anchorWorker)
		}
		if aerr != nil {
			return "", "", aerr
		}
		if anchorMode == "collection" {
			// replace the intake anchor with a fresh collection assignment
			_, _ = s.db.Exec(ctx, `DELETE FROM assignments WHERE journey_id=$1 AND kind='node' AND sequence=0`, nj.JourneyID)
			_, _ = s.db.Exec(ctx, `INSERT INTO assignments (assignment_id, journey_id, sample_id, kind, sequence, status, to_location_id)
				VALUES ($1,$2,$3,'collection',0,'pending',$4)`, newUUID(), nj.JourneyID, sid, position)
		} else if anchorMode == "node" {
			// continuation: the anchor node assignment must be offered, not auto-accepted
			_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='pending', accepted_by=NULL, accepted_at=NULL
				WHERE journey_id=$1 AND kind='node' AND sequence=0`, nj.JourneyID)
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET parent_journey_id=$2, plan_version=$3, route_mode=$4, updated_at=now() WHERE journey_id=$1`,
			nj.JourneyID, journeyID, j.PlanVersion+1, nj.RouteMode)
		_, _ = s.db.Exec(ctx, `UPDATE samples SET active_journey_id=$2, target_laboratory_id=$3, updated_at=now() WHERE sample_id=$1`,
			sid, nj.JourneyID, route.LabID)
		if len(sampleIDs) > 1 {
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET route_mode='batched' WHERE journey_id=$1`, nj.JourneyID)
		}
		if i == 0 {
			replacementID = nj.JourneyID
		} else {
			// additional samples join the first replacement journey
			_, _ = s.db.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, replacementID, sid)
			_, _ = s.db.Exec(ctx, `UPDATE samples SET active_journey_id=$2 WHERE sample_id=$1`, sid, replacementID)
			_, _ = s.db.Exec(ctx, `UPDATE assignments SET journey_id=$2 WHERE journey_id=$1`, nj.JourneyID, replacementID)
			_, _ = s.db.Exec(ctx, `UPDATE reservations SET journey_id=$2 WHERE journey_id=$1`, nj.JourneyID, replacementID)
			_, _ = s.db.Exec(ctx, `DELETE FROM journeys WHERE journey_id=$1`, nj.JourneyID)
		}
	}
	// retire the old journey, preserving completed work and custody
	if preserveAssignment != nil {
		_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='cancelled', updated_at=now()
			WHERE journey_id=$1 AND status IN ('pending','offered','accepted')`, journeyID)
	} else {
		_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='cancelled', updated_at=now()
			WHERE journey_id=$1 AND status IN ('pending','offered','accepted','in_progress')`, journeyID)
	}
	_, _ = s.db.Exec(ctx, `UPDATE journeys SET status='replaced', replacement_journey_id=$2, replan_status='replaced', updated_at=now()
		WHERE journey_id=$1`, journeyID, replacementID)
	s.releaseJourneyReservations(ctx, journeyID)
	s.audit(ctx, sess, "replan_journey", "journey", journeyID, true,
		map[string]any{"replacementJourneyId": replacementID})
	s.emit(ctx, "journey_replanned", "journey", journeyID, map[string]any{
		"journeyId": journeyID, "replacementJourneyId": replacementID,
	}, "", "")
	s.kickOffers(ctx, sess, replacementID)
	return replacementID, "replaced", nil
}

func (s *server) handleRerouteJourney(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		JourneyID           string `json:"journeyId"`
		Reason              string `json:"reason"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "reroute_journey", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		j, err := loadJourney(ctx, s.db, body.JourneyID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "journey not found")
		}
		if aerr := checkPlanVersion(j, body.ExpectedPlanVersion); aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
		replacementID, status, aerr := s.replanJourney(ctx, sess, body.JourneyID)
		if aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
	switch status {
		case "exception":
			return 409, nil, errOf(409, "no_valid_route", "no valid route is available for the remaining work")
		case "expired":
			return 409, nil, errOf(409, "deadline_exceeded", "no route can meet the delivery deadline")
		}
		out := map[string]any{
			"journeyId":    body.JourneyID,
			"replanStatus": status,
		}
		if replacementID != "" {
			out["replacementPlanId"] = replacementID
			if rj, err := loadJourney(ctx, s.db, replacementID); err == nil {
				out["replacementJourney"] = s.journeyPlanJSON(ctx, rj)
			}
		}
		return 201, out, nil
	})
}

func (s *server) handleReportDisruption(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		ResourceType   string   `json:"resourceType"`
		ResourceID     string   `json:"resourceId"`
		Reason         string   `json:"reason"`
		OccurredAt     string   `json:"occurredAt"`
		IdempotencyKey string   `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "report_disruption", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		if !containsString([]string{"worker", "node", "route", "laboratory", "vehicle", "capacity_pool"}, body.ResourceType) {
			return 400, nil, errOf(400, "invalid_json", "resourceType must be worker, node, route, laboratory, vehicle or capacity_pool")
		}
		occurredAt := nowUTC()
		if body.OccurredAt != "" {
			t, ok := parseTime(body.OccurredAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "occurredAt must be an RFC3339 timestamp")
			}
			occurredAt = t
		}
		// find affected active journeys
		affected := map[string]bool{}
		jrows, err := s.db.Query(ctx, `SELECT journey_id, connection_ids, node_ids, entry_location_id, laboratory_id FROM journeys
			WHERE status IN ('planned','in_progress')`)
		if err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		type jrow struct {
			id      string
			conns   []string
			nodes   []string
			entry   *string
			lab     *string
		}
		jlist := []jrow{}
		for jrows.Next() {
			var jr jrow
			var connsB, nodesB []byte
			if err := jrows.Scan(&jr.id, &connsB, &nodesB, &jr.entry, &jr.lab); err != nil {
				continue
			}
			jr.conns = strSlice(jsonAny(connsB))
			jr.nodes = strSlice(jsonAny(nodesB))
			jlist = append(jlist, jr)
		}
		jrows.Close()
		for _, jr := range jlist {
			switch body.ResourceType {
			case "node", "laboratory":
				if containsString(jr.nodes, body.ResourceID) ||
					(jr.lab != nil && *jr.lab == body.ResourceID) ||
					(jr.entry != nil && *jr.entry == body.ResourceID) {
					affected[jr.id] = true
				}
			case "route", "capacity_pool":
				if containsString(jr.conns, body.ResourceID) || containsString(jr.nodes, body.ResourceID) ||
					(jr.lab != nil && *jr.lab == body.ResourceID) || (jr.entry != nil && *jr.entry == body.ResourceID) {
					affected[jr.id] = true
				}
			case "worker", "vehicle":
				var n int
				_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE journey_id=$1
					AND (accepted_by=$2 OR offered_to=$2) AND status IN ('offered','accepted','in_progress')`, jr.id, body.ResourceID).Scan(&n)
				if n > 0 {
					affected[jr.id] = true
				}
			}
		}
		affectedSamples := []string{}
		replacementPlans := []string{}
		worst := "not_required"
		rank := map[string]int{"not_required": 0, "replaced": 1, "expired": 2, "exception": 3}
		for jid := range affected {
			for _, sid := range journeySampleIDs(ctx, s.db, jid) {
				if !containsString(affectedSamples, sid) {
					affectedSamples = append(affectedSamples, sid)
				}
			}
			replID, status, aerr := s.replanJourney(ctx, sess, jid)
			if aerr != nil {
				continue
			}
			if replID != "" {
				replacementPlans = append(replacementPlans, replID)
			}
			if rank[status] > rank[worst] {
				worst = status
			}
		}
		disruptionID := newUUID()
		asJSON, _ := json.Marshal(affectedSamples)
		rpJSON, _ := json.Marshal(replacementPlans)
		if _, err := s.db.Exec(ctx, `INSERT INTO disruptions (disruption_id, resource_type, resource_id, reason, occurred_at,
			affected_sample_ids, replacement_plan_ids, replan_status) VALUES ($1,$2,$3,$4,$5,$6,$7,$8)`,
			disruptionID, body.ResourceType, body.ResourceID, body.Reason, occurredAt, asJSON, rpJSON, worst); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		s.audit(ctx, sess, "report_disruption", "disruption", disruptionID, true,
			map[string]any{"resourceType": body.ResourceType, "resourceId": body.ResourceID, "replanStatus": worst})
		s.emit(ctx, "disruption_reported", "disruption", disruptionID, map[string]any{
			"disruptionId": disruptionID, "resourceType": body.ResourceType, "resourceId": body.ResourceID,
		}, "", "")
		return 201, map[string]any{
			"disruptionId":       disruptionID,
			"affectedSampleIds":  affectedSamples,
			"replacementPlanIds": replacementPlans,
			"replanStatus":       worst,
		}, nil
	})
}

