   284			if err == nil {
   285				ids := []string{}
   286				for rows.Next() {
   287					var id string
   288					_ = rows.Scan(&id)
   289					ids = append(ids, id)
   290				}
   291				rows.Close()
   292				for _, id := range ids {
   293					sm, err := loadSample(ctx, s.db, id)
   294					if err != nil {
   295						continue
   296					}
   297					if body.SampleTypeID != "" {
   298						req, err := loadRequest(ctx, s.db, sm.RequestID)
   299						if err != nil || req.SampleTypeID != body.SampleTypeID {
   300							continue
   301						}
   302					}
   303					match := false
   304					switch view {
   305					case "pending":
   306						match = !sm.Sealed && sm.Status != SampleCancelled && sm.Status != SampleExpired
   307					case "in_progress":
   308						match = sm.Sealed && sm.Status != SampleReceived && sm.Status != SampleCancelled && sm.Status != SampleExpired
   309					case "completed":
   310						match = sm.Status == SampleReceived || sm.Status == SampleCancelled || sm.Status == SampleExpired
   311					}
   312					if !match {
   313						continue
   314					}
   315					item := s.sampleStateJSON(ctx, sm)
   316					items = append(items, map[string]any{"kind": "sample", "sample": item})
   317				}
   318			}
   319		case RoleCollector, RoleCourier, RoleNode, RoleLab:
   320			kind := ""
   321			switch role {
   322			case RoleCollector:
   323				kind = KindCollection
   324			case RoleCourier:
   325				kind = KindTransport
   326			case RoleNode:
   327				kind = KindNode
   328			case RoleLab:
   329				kind = KindLab
   330			}
   331			var query string
   332			var args []any
   333			switch view {
   334			case "pending":
   335				query = `SELECT assignment_id FROM assignments WHERE kind=$1 AND status='offered' AND offered_to=$2 ORDER BY offered_at`
   336				args = []any{kind, sess.User.UserID}
   337			case "in_progress":
   338				query = `SELECT assignment_id FROM assignments WHERE kind=$1 AND accepted_by=$2 AND status IN ('accepted','in_progress') ORDER BY accepted_at`
   339				args = []any{kind, sess.User.UserID}
   340			case "completed":
   341				query = `SELECT assignment_id FROM assignments WHERE kind=$1 AND accepted_by=$2 AND status IN ('completed','cancelled') ORDER BY completed_at NULLS LAST, updated_at DESC LIMIT 200`
   342				args = []any{kind, sess.User.UserID}
   343			}
   344			rows, err := s.db.Query(ctx, query, args...)
   345			if err == nil {
   346				ids := []string{}
   347				for rows.Next() {
   348					var id string
   349					_ = rows.Scan(&id)
   350					ids = append(ids, id)
   351				}
   352				rows.Close()
   353				for _, id := range ids {
   354					a, err := loadAssignment(ctx, s.db, id)
   355					if err != nil {
   356						continue
   357					}
   358					if body.SampleTypeID != "" {
   359						st, err := sampleTypeForSample(ctx, s, a.SampleID)
   360						if err != nil || st.SampleTypeID != body.SampleTypeID {
   361							continue
   362						}
   363					}
   364					items = append(items, map[string]any{"kind": "assignment", "assignment": s.assignmentWorkItemJSON(ctx, a)})
   365				}
   366			}
   367		case RoleDispatcher, RoleAdmin:
   368			statuses := []string{}
   369			switch view {
   370			case "pending":
   371				statuses = []string{JourneyPlanned}
   372			case "in_progress":
   373				statuses = []string{JourneyInProgress}
   374			case "completed":
   375				statuses = []string{JourneyCompleted, JourneyCancelled, JourneyReplaced, JourneyMerged}
   376			}
   377			rows, err := s.db.Query(ctx, `SELECT journey_id FROM journeys WHERE status = ANY($1) ORDER BY created_at DESC LIMIT 300`, statuses)
   378			if err == nil {
   379				ids := []string{}
   380				for rows.Next() {
   381					var id string
   382					_ = rows.Scan(&id)
   383					ids = append(ids, id)
   384				}
   385				rows.Close()
   386				for _, id := range ids {
   387					j, err := loadJourney(ctx, s.db, id)
   388					if err != nil {
   389						continue
   390					}
   391					if body.SampleTypeID != "" {
   392						matchType := false
   393						for _, sid := range journeySampleIDs(ctx, s.db, j.JourneyID) {
   394							st, err := sampleTypeForSample(ctx, s, sid)
   395							if err == nil && st.SampleTypeID == body.SampleTypeID {
   396								matchType = true
   397							}
   398						}
   399						if !matchType {
   400							continue
   401						}
   402					}
   403					jw := map[string]any{
   404						"journeyId":   j.JourneyID,
   405						"status":      j.Status,
   406						"routeMode":   j.RouteMode,
   407						"planVersion": j.PlanVersion,
   408						"sampleIds":   journeySampleIDs(ctx, s.db, j.JourneyID),
   409					}
   410					if j.EstimatedDeliveryAt != nil {
   411						jw["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
   412					}
   413					if j.ReplanStatus != nil {
   414						jw["replanStatus"] = *j.ReplanStatus
   415					}
   416					items = append(items, map[string]any{"kind": "journey", "journey": jw})
   417				}
   418			}
   419		}
   420		writeData(w, 200, map[string]any{"role": role, "view": view, "items": items})
   421	}
   422	
   423	// ---------- bootstrap ----------
   424	
   425	func (s *server) handleBootstrap(w http.ResponseWriter, r *http.Request) {
   426		sess, aerr := s.requireAuth(w, r)
   427		if aerr != nil {
   428			writeErr(w, aerr)
   429			return
   430		}
   431		ctx := r.Context()
   432		out := map[string]any{
   433			"user":       publicUser(sess.User),
   434			"serverTime": fmtTime(nowUTC()),
   435		}
   436		// sample types are included so request forms can be built
   437		typeRows, err := s.db.Query(ctx, `SELECT sample_type_id FROM sample_types ORDER BY name`)
   438		if err == nil {
   439			ids := []string{}
   440			for typeRows.Next() {
   441				var id string
   442				_ = typeRows.Scan(&id)
   443				ids = append(ids, id)
   444			}
   445			typeRows.Close()
   446			types := []map[string]any{}
   447			for _, id := range ids {
   448				if st, err := loadSampleType(ctx, s.db, id); err == nil {
   449					types = append(types, sampleTypeJSON(st))
   450				}
   451			}
   452			out["sampleTypes"] = types
   453		}
   454		if sess.ActiveRole == RoleRequester {
   455			samples := []map[string]any{}
   456			rows, err := s.db.Query(ctx, `SELECT sample_id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC LIMIT 100`, sess.User.UserID)
   457			if err == nil {
   458				ids := []string{}
   459				for rows.Next() {
   460					var id string
   461					_ = rows.Scan(&id)
   462					ids = append(ids, id)
   463				}
   464				rows.Close()
   465				for _, id := range ids {
   466					if sm, err := loadSample(ctx, s.db, id); err == nil {
   467						samples = append(samples, s.sampleStateJSON(ctx, sm))
   468					}
   469				}
   470			}
   471			out["requesterSamples"] = samples
   472		}
   473		if sess.ActiveRole == RoleDispatcher || sess.ActiveRole == RoleAdmin || sess.ActiveRole == RoleNode || sess.ActiveRole == RoleLab {
   474			out["operations"] = s.operationsState(ctx, "")
   475		}
   476		writeData(w, 200, out)
   477	}
