package main

import (
	"context"
	"net/http"
	"time"
)

// sampleTimeline returns the ordered audit history for a sample.
func (s *server) sampleTimeline(ctx context.Context, sampleID string) []map[string]any {
	rows, err := s.db.Query(ctx, `SELECT id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details
		FROM audit_entries
		WHERE (entity_type='sample' AND entity_id=$1)
		   OR (entity_type IN ('assignment','handoff','request') AND details->>'sampleId'=$1)
		ORDER BY id`, sampleID)
	if err != nil {
		return []map[string]any{}
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var eventID int64
		var actorID, role, action, entityType, entityID string
		var success bool
		var occurredAt time.Time
		var details []byte
		if err := rows.Scan(&eventID, &actorID, &role, &action, &entityType, &entityID, &success, &occurredAt, &details); err != nil {
			continue
		}
		det := map[string]any{}
		if v := jsonAny(details); v != nil {
			if m, ok := v.(map[string]any); ok {
				det = m
			}
		}
		out = append(out, map[string]any{
			"eventId":    eventID,
			"action":     action,
			"actorId":    actorID,
			"role":       role,
			"entityType": entityType,
			"entityId":   entityID,
			"success":    success,
			"occurredAt": fmtTime(occurredAt),
			"details":    det,
		})
	}
	return out
}

// journeyTimeline returns the ordered audit history for a journey.
func (s *server) journeyTimeline(ctx context.Context, journeyID string) []map[string]any {
