package main

import (
	"context"
	"net/http"
	"time"
)

// sampleTimeline returns the ordered audit history for a sample.
func (s *server) sampleTimeline(ctx context.Context, sampleID string) []map[string]any {
	rows, err := s.db.Query(ctx, `SELECT id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details
		FROM audit_entries
		WHERE (entity_type='sample' AND entity_id=$1)
		   OR (entity_type IN ('assignment','handoff','request') AND details->>'sampleId'=$1)
		ORDER BY id`, sampleID)
	if err != nil {
		return []map[string]any{}
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var eventID int64
		var actorID, role, action, entityType, entityID string
		var success bool
		var occurredAt time.Time
		var details []byte
		if err := rows.Scan(&eventID, &actorID, &role, &action, &entityType, &entityID, &success, &occurredAt, &details); err != nil {
			continue
		}
		det := map[string]any{}
		if v := jsonAny(details); v != nil {
			if m, ok := v.(map[string]any); ok {
				det = m
			}
		}
		out = append(out, map[string]any{
			"eventId":    eventID,
			"action":     action,
			"actorId":    actorID,
			"role":       role,
			"entityType": entityType,
			"entityId":   entityID,
			"success":    success,
			"occurredAt": fmtTime(occurredAt),
			"details":    det,
		})
	}
	return out
}

// journeyTimeline returns the ordered audit history for a journey.
func (s *server) journeyTimeline(ctx context.Context, journeyID string) []map[string]any {
	rows, err := s.db.Query(ctx, `SELECT id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details
		FROM audit_entries
		WHERE (entity_type='journey' AND entity_id=$1)
		   OR (entity_type='assignment' AND details->>'journeyId'=$1)
		ORDER BY id`, journeyID)
	if err != nil {
		return []map[string]any{}
	}
	defer rows.Close()
	out := []map[string]any{}
	for rows.Next() {
		var eventID int64
		var actorID, role, action, entityType, entityID string
		var success bool
		var occurredAt time.Time
		var details []byte
		if err := rows.Scan(&eventID, &actorID, &role, &action, &entityType, &entityID, &success, &occurredAt, &details); err != nil {
			continue
		}
		det := map[string]any{}
		if v := jsonAny(details); v != nil {
			if m, ok := v.(map[string]any); ok {
				det = m
			}
		}
		out = append(out, map[string]any{
			"eventId":    eventID,
			"action":     action,
			"actorId":    actorID,
			"role":       role,
			"entityType": entityType,
			"entityId":   entityID,
			"success":    success,
			"occurredAt": fmtTime(occurredAt),
			"details":    det,
		})
	}
	return out
}

func (s *server) sampleStateJSON(ctx context.Context, sm *Sample) map[string]any {
	activeAssignmentIDs := []string{}
	arows, err := s.db.Query(ctx, `SELECT assignment_id FROM assignments
		WHERE sample_id=$1 AND status IN ('offered','accepted','in_progress') ORDER BY sequence`, sm.SampleID)
	if err == nil {
		for arows.Next() {
			var id string
			_ = arows.Scan(&id)
			activeAssignmentIDs = append(activeAssignmentIDs, id)
		}
		arows.Close()
	}
	out := map[string]any{
		"sampleId":             sm.SampleID,
		"requestId":            sm.RequestID,
		"requesterId":          sm.RequesterID,
		"serviceability":       sm.Serviceability,
		"activeAssignmentIds":  activeAssignmentIDs,
		"state":                map[string]any{"status": sm.Status},
		"locationStale":        staleSince(sm.LocationRecordedAt),
		"timeline":             s.sampleTimeline(ctx, sm.SampleID),
	}
	if req, err := loadRequest(ctx, s.db, sm.RequestID); err == nil {
		out["origin"] = map[string]any{"latitude": req.OriginLat, "longitude": req.OriginLng}
		out["originType"] = req.OriginType
		out["requestedAt"] = fmtTime(req.RequestedAt)
		out["deliveryDeadline"] = fmtTime(req.DeliveryDeadline)
		out["sampleTypeId"] = req.SampleTypeID
		out["containerType"] = req.ContainerType
		out["temperatureMinC"] = req.TempMinC
		out["temperatureMaxC"] = req.TempMaxC
		incompat := req.IncompatibleIDs
		if incompat == nil {
			incompat = []string{}
		}
		out["incompatibleSampleTypes"] = incompat
	}
	if sm.ActiveJourneyID != nil {
		out["activeJourneyId"] = *sm.ActiveJourneyID
	}
	if sm.TargetLaboratoryID != nil {
		out["targetLaboratoryId"] = *sm.TargetLaboratoryID
	}
	if sm.LatestLat != nil && sm.LatestLng != nil {
		out["latestLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLng}
	}
	if sm.LocationRecordedAt != nil {
		out["locationRecordedAt"] = fmtTime(*sm.LocationRecordedAt)
	}
	return out
}

// canViewSample checks role-based visibility for a sample.
func (s *server) canViewSample(ctx context.Context, sess *session, sm *Sample) bool {
	switch sess.ActiveRole {
	case RoleAdmin, RoleDispatcher:
		return true
	case RoleRequester:
		return sm.RequesterID == sess.User.UserID
	case RoleCollector, RoleCourier, RoleNode, RoleLab:
		if sm.CurrentHolderID != nil && *sm.CurrentHolderID == sess.User.UserID {
			return true
		}
		var n int
		_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE sample_id=$1 AND (accepted_by=$2 OR offered_to=$2)`,
			sm.SampleID, sess.User.UserID).Scan(&n)
		return n > 0
	}
	return false
}

func (s *server) handleReadSampleState(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if sess.ActiveRole == "" {
		writeErr(w, errOf(409, "role_not_selected", "select an active role before performing this action"))
		return
	}
	ctx := r.Context()
	sm, err := loadSample(ctx, s.db, r.PathValue("sampleId"))
	if err != nil {
		writeErr(w, errOf(404, "not_found", "sample not found"))
		return
	}
	if !s.canViewSample(ctx, sess, sm) {
		writeErr(w, errOf(403, "forbidden", "you may not view this sample"))
		return
	}
	writeData(w, 200, s.sampleStateJSON(ctx, sm))
}

func (s *server) handleReadSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if sess.ActiveRole == "" {
		writeErr(w, errOf(409, "role_not_selected", "select an active role before performing this action"))
		return
	}
	var body struct {
		SampleID string `json:"sampleId"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	ctx := r.Context()
	sm, err := loadSample(ctx, s.db, body.SampleID)
	if err != nil {
		writeErr(w, errOf(404, "not_found", "sample not found"))
		return
	}
	if !s.canViewSample(ctx, sess, sm) {
		writeErr(w, errOf(403, "forbidden", "you may not view this sample"))
		return
	}
	completedLegIDs := []string{}
	lrows, err := s.db.Query(ctx, `SELECT assignment_id FROM assignments
		WHERE sample_id=$1 AND status='completed' ORDER BY sequence`, sm.SampleID)
	if err == nil {
		for lrows.Next() {
			var id string
			_ = lrows.Scan(&id)
			completedLegIDs = append(completedLegIDs, id)
		}
		lrows.Close()
	}
	activeReplacementPlanIDs := []string{}
	prows, err := s.db.Query(ctx, `SELECT DISTINCT j.journey_id FROM journeys j
		JOIN assignments a ON a.journey_id=j.journey_id
		WHERE a.sample_id=$1 AND j.parent_journey_id IS NOT NULL AND j.status IN ('planned','in_progress')`, sm.SampleID)
	if err == nil {
		for prows.Next() {
			var id string
			_ = prows.Scan(&id)
			activeReplacementPlanIDs = append(activeReplacementPlanIDs, id)
		}
		prows.Close()
	}
	out := map[string]any{
		"sampleId":                 sm.SampleID,
		"status":                   sm.Status,
		"sealed":                   sm.Sealed,
		"completedLegIds":          completedLegIDs,
		"activeReplacementPlanIds": activeReplacementPlanIDs,
		"timeline":                 s.sampleTimeline(ctx, sm.SampleID),
		"locationStale":            staleSince(sm.LocationRecordedAt),
	}
	if sm.ActiveJourneyID != nil {
		out["activeJourneyId"] = *sm.ActiveJourneyID
	}
	if sm.CurrentHolderID != nil {
		out["currentHolderId"] = *sm.CurrentHolderID
	}
	if sm.ReceivedLaboratoryID != nil {
		out["receivedLaboratoryId"] = *sm.ReceivedLaboratoryID
	}
	if sm.Exception != nil {
		out["exception"] = sm.Exception
	}
	if sm.PendingHandoffID != nil {
		out["pendingHandoffId"] = *sm.PendingHandoffID
		var hid, sender, receiver, hstatus string
		var initiated time.Time
		var completed *time.Time
		herr := s.db.QueryRow(ctx, `SELECT handoff_id, sender_id, receiver_id, status, initiated_at, completed_at
			FROM handoffs WHERE handoff_id=$1`, *sm.PendingHandoffID).
			Scan(&hid, &sender, &receiver, &hstatus, &initiated, &completed)
		if herr == nil {
			pending := map[string]any{
				"handoffId":   hid,
				"fromUserId":  sender,
				"toUserId":    receiver,
				"status":      hstatus,
				"initiatedAt": fmtTime(initiated),
			}
			if completed != nil {
				pending["completedAt"] = fmtTime(*completed)
			}
			out["pendingHandoff"] = pending
		}
	}
	if sm.LatestLat != nil && sm.LatestLng != nil {
		out["latestLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLng}
	}
	if sm.LocationRecordedAt != nil {
		out["locationRecordedAt"] = fmtTime(*sm.LocationRecordedAt)
	}
	writeData(w, 200, out)
}

// ---------- role work lists ----------

func (s *server) assignmentWorkItemJSON(ctx context.Context, a *Assignment) map[string]any {
	out := map[string]any{
		"assignmentId": a.AssignmentID,
		"kind":         a.Kind,
		"status":       a.Status,
		"sampleId":     a.SampleID,
		"journeyId":    a.JourneyID,
	}
	if a.FromLocationID != nil {
		out["fromLocationId"] = *a.FromLocationID
	}
	if a.ToLocationID != nil {
		out["toLocationId"] = *a.ToLocationID
	}
	if a.NodeID != nil {
		out["nodeId"] = *a.NodeID
	}
	if a.LaboratoryID != nil {
		out["laboratoryId"] = *a.LaboratoryID
	}
	if a.OfferedTo != nil {
		out["offeredTo"] = *a.OfferedTo
	}
	if a.AcceptedBy != nil {
		out["acceptedBy"] = *a.AcceptedBy
	}
	if sm, err := loadSample(ctx, s.db, a.SampleID); err == nil {
		if req, err := loadRequest(ctx, s.db, sm.RequestID); err == nil {
			out["deadlineAt"] = fmtTime(req.DeliveryDeadline)
		}
		out["history"] = s.sampleTimeline(ctx, a.SampleID)
	}
	// destination capacity for node and laboratory work
	if a.Kind == KindNode && a.NodeID != nil {
		if l, err := loadLocation(ctx, s.db, *a.NodeID); err == nil {
			out["destinationCapacity"] = capacityJSON(l.CapacityUnits, l.ReservedUnits, l.CooledCapacity, l.CooledReserved)
		}
	}
	if a.Kind == KindLab && a.LaboratoryID != nil {
		if l, err := loadLocation(ctx, s.db, *a.LaboratoryID); err == nil {
			out["destinationCapacity"] = capacityJSON(l.CapacityUnits, l.ReservedUnits, l.CooledCapacity, l.CooledReserved)
		}
	}
	return out
}

func (s *server) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		Role         string `json:"role"`
		View         string `json:"view"`
		SampleTypeID string `json:"sampleTypeId"`
	}
	if r.Body != nil && r.ContentLength > 0 {
		if aerr := decodeBody(r, &body); aerr != nil {
			writeErr(w, aerr)
			return
		}
	}
	role := body.Role
	if role == "" {
		role = sess.ActiveRole
	}
	if role == "" {
		writeErr(w, errOf(409, "role_not_selected", "select an active role before performing this action"))
		return
	}
	if !containsString(validRoles, role) {
		writeErr(w, errOf(400, "invalid_role", "role is not a known role"))
		return
	}
	if role != sess.ActiveRole {
		writeErr(w, errOf(403, "forbidden", "work lists follow the currently selected role"))
		return
	}
	view := body.View
	if view == "" {
		view = "pending"
	}
	if !containsString([]string{"pending", "in_progress", "completed"}, view) {
		writeErr(w, errOf(400, "invalid_view", "view must be pending, in_progress or completed"))
		return
	}
	ctx := r.Context()
	items := []map[string]any{}
	switch role {
	case RoleRequester:
		rows, err := s.db.Query(ctx, `SELECT sample_id FROM samples WHERE requester_id=$1 ORDER BY created_at`, sess.User.UserID)
		if err == nil {
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				sm, err := loadSample(ctx, s.db, id)
				if err != nil {
					continue
				}
				if body.SampleTypeID != "" {
					req, err := loadRequest(ctx, s.db, sm.RequestID)
					if err != nil || req.SampleTypeID != body.SampleTypeID {
						continue
					}
				}
				match := false
				switch view {
				case "pending":
					match = !sm.Sealed && sm.Status != SampleCancelled && sm.Status != SampleExpired
				case "in_progress":
					match = sm.Sealed && sm.Status != SampleReceived && sm.Status != SampleCancelled && sm.Status != SampleExpired
				case "completed":
					match = sm.Status == SampleReceived || sm.Status == SampleCancelled || sm.Status == SampleExpired
				}
				if !match {
					continue
				}
				item := s.sampleStateJSON(ctx, sm)
				items = append(items, map[string]any{"kind": "sample", "sample": item})
			}
		}
	case RoleCollector, RoleCourier, RoleNode, RoleLab:
		kind := ""
		switch role {
		case RoleCollector:
			kind = KindCollection
		case RoleCourier:
			kind = KindTransport
		case RoleNode:
			kind = KindNode
		case RoleLab:
			kind = KindLab
		}
		var query string
		var args []any
		switch view {
		case "pending":
			query = `SELECT assignment_id FROM assignments WHERE kind=$1 AND status='offered' AND offered_to=$2 ORDER BY offered_at`
			args = []any{kind, sess.User.UserID}
		case "in_progress":
			query = `SELECT assignment_id FROM assignments WHERE kind=$1 AND accepted_by=$2 AND status IN ('accepted','in_progress') ORDER BY accepted_at`
			args = []any{kind, sess.User.UserID}
		case "completed":
			query = `SELECT assignment_id FROM assignments WHERE kind=$1 AND accepted_by=$2 AND status IN ('completed','cancelled') ORDER BY completed_at NULLS LAST, updated_at DESC LIMIT 200`
			args = []any{kind, sess.User.UserID}
		}
		rows, err := s.db.Query(ctx, query, args...)
		if err == nil {
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				a, err := loadAssignment(ctx, s.db, id)
				if err != nil {
					continue
				}
				if body.SampleTypeID != "" {
					st, err := sampleTypeForSample(ctx, s, a.SampleID)
					if err != nil || st.SampleTypeID != body.SampleTypeID {
						continue
					}
				}
				items = append(items, map[string]any{"kind": "assignment", "assignment": s.assignmentWorkItemJSON(ctx, a)})
			}
		}
	case RoleDispatcher, RoleAdmin:
		statuses := []string{}
		switch view {
		case "pending":
			statuses = []string{JourneyPlanned}
		case "in_progress":
			statuses = []string{JourneyInProgress}
		case "completed":
			statuses = []string{JourneyCompleted, JourneyCancelled, JourneyReplaced, JourneyMerged}
		}
		rows, err := s.db.Query(ctx, `SELECT journey_id FROM journeys WHERE status = ANY($1) ORDER BY created_at DESC LIMIT 300`, statuses)
		if err == nil {
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				j, err := loadJourney(ctx, s.db, id)
				if err != nil {
					continue
				}
				if body.SampleTypeID != "" {
					matchType := false
					for _, sid := range journeySampleIDs(ctx, s.db, j.JourneyID) {
						st, err := sampleTypeForSample(ctx, s, sid)
						if err == nil && st.SampleTypeID == body.SampleTypeID {
							matchType = true
						}
					}
					if !matchType {
						continue
					}
				}
				jw := map[string]any{
					"journeyId":   j.JourneyID,
					"status":      j.Status,
					"routeMode":   j.RouteMode,
					"planVersion": j.PlanVersion,
					"sampleIds":   journeySampleIDs(ctx, s.db, j.JourneyID),
				}
				if j.EstimatedDeliveryAt != nil {
					jw["estimatedDeliveryAt"] = fmtTime(*j.EstimatedDeliveryAt)
				}
				if j.ReplanStatus != nil {
					jw["replanStatus"] = *j.ReplanStatus
				}
				items = append(items, map[string]any{"kind": "journey", "journey": jw})
			}
		}
	}
	writeData(w, 200, map[string]any{"role": role, "view": view, "items": items})
}

// ---------- bootstrap ----------

func (s *server) handleBootstrap(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	ctx := r.Context()
	out := map[string]any{
		"user":       publicUser(sess.User),
		"serverTime": fmtTime(nowUTC()),
	}
	// sample types are included so request forms can be built
	typeRows, err := s.db.Query(ctx, `SELECT sample_type_id FROM sample_types ORDER BY name`)
	if err == nil {
		ids := []string{}
		for typeRows.Next() {
			var id string
			_ = typeRows.Scan(&id)
			ids = append(ids, id)
		}
		typeRows.Close()
		types := []map[string]any{}
		for _, id := range ids {
			if st, err := loadSampleType(ctx, s.db, id); err == nil {
				types = append(types, sampleTypeJSON(st))
			}
		}
		out["sampleTypes"] = types
	}
	if sess.ActiveRole == RoleRequester {
		samples := []map[string]any{}
		rows, err := s.db.Query(ctx, `SELECT sample_id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC LIMIT 100`, sess.User.UserID)
		if err == nil {
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				if sm, err := loadSample(ctx, s.db, id); err == nil {
					samples = append(samples, s.sampleStateJSON(ctx, sm))
				}
			}
		}
		out["requesterSamples"] = samples
	}
	if sess.ActiveRole == RoleDispatcher || sess.ActiveRole == RoleAdmin || sess.ActiveRole == RoleNode || sess.ActiveRole == RoleLab {
		out["operations"] = s.operationsState(ctx, "")
	}
	writeData(w, 200, out)
}

