// sampleWorkItemJSON renders a SampleWorkItem for role work lists.
func (s *server) sampleWorkItemJSON(ctx context.Context, sm *Sample) map[string]any {
	out := map[string]any{
		"kind":          "sample",
		"sampleId":      sm.SampleID,
		"requestId":     sm.RequestID,
		"status":        sm.Status,
		"serviceability": sm.Serviceability,
		"requesterId":   sm.RequesterID,
