}

func (s *server) handleListRoleWork(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if r.Body != nil && r.ContentLength > 0 {
		if aerr := decodeBody(r, &body); aerr != nil {
			writeErr(w, aerr)
			return
		}
	}
	role := body.Role
	if role == "" {
		role = sess.ActiveRole
	}
	if role == "" {
		writeErr(w, errOf(409, "role_not_selected", "select an active role before performing this action"))
		return
	}
	if !containsString(validRoles, role) {
		writeErr(w, errOf(400, "invalid_role", "role is not a known role"))
		return
	}
	if role != sess.ActiveRole {
		writeErr(w, errOf(403, "forbidden", "work lists follow the currently selected role"))
		return
	}
	ctx := r.Context()
	pending := []map[string]any{}
	inProgress := []map[string]any{}
	completed := []map[string]any{}
	include := func(bucket string) bool {
		if body.Status == "" {
			return true
		}
		return body.Status == bucket
	}
	switch role {
	case RoleRequester:
		rows, err := s.db.Query(ctx, `SELECT sample_id FROM samples WHERE requester_id=$1 ORDER BY created_at`, sess.User.UserID)
		if err == nil {
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				sm, err := loadSample(ctx, s.db, id)
				if err != nil {
					continue
				}
				item := s.sampleWorkItemJSON(ctx, sm)
				switch {
				case sm.Status == SampleReceived || sm.Status == SampleCancelled || sm.Status == SampleExpired:
					if include("completed") {
						completed = append(completed, item)
					}
				case sm.Sealed:
					if include("in_progress") {
						inProgress = append(inProgress, item)
					}
				default:
					if include("pending") {
						pending = append(pending, item)
					}
				}
			}
		}
	case RoleCollector, RoleCourier, RoleNode, RoleLab:
		kind := ""
		switch role {
		case RoleCollector:
			kind = KindCollection
		case RoleCourier:
			kind = KindTransport
		case RoleNode:
			kind = KindNode
		case RoleLab:
			kind = KindLab
		}
		queries := []struct {
			bucket string
			query  string
		}{
			{"pending", `SELECT assignment_id FROM assignments WHERE kind=$1 AND status='offered' AND offered_to=$2 ORDER BY offered_at`},
			{"in_progress", `SELECT assignment_id FROM assignments WHERE kind=$1 AND accepted_by=$2 AND status IN ('accepted','in_progress') ORDER BY accepted_at`},
			{"completed", `SELECT assignment_id FROM assignments WHERE kind=$1 AND accepted_by=$2 AND status IN ('completed','cancelled') ORDER BY completed_at NULLS LAST, updated_at DESC LIMIT 200`},
		}
		for _, q := range queries {
			if !include(q.bucket) {
				continue
			}
			rows, err := s.db.Query(ctx, q.query, kind, sess.User.UserID)
			if err != nil {
				continue
			}
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				a, err := loadAssignment(ctx, s.db, id)
				if err != nil {
					continue
				}
				item := s.assignmentWorkItemJSON(ctx, a)
				switch q.bucket {
				case "pending":
					pending = append(pending, item)
				case "in_progress":
					inProgress = append(inProgress, item)
				case "completed":
					completed = append(completed, item)
				}
			}
		}
	case RoleDispatcher, RoleAdmin:
		buckets := []struct {
			bucket   string
			statuses []string
		}{
			{"pending", []string{JourneyPlanned}},
			{"in_progress", []string{JourneyInProgress}},
			{"completed", []string{JourneyCompleted, JourneyCancelled, JourneyReplaced, JourneyMerged}},
		}
		for _, b := range buckets {
			if !include(b.bucket) {
				continue
			}
			rows, err := s.db.Query(ctx, `SELECT journey_id FROM journeys WHERE status = ANY($1) ORDER BY created_at DESC LIMIT 300`, b.statuses)
			if err != nil {
				continue
			}
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				j, err := loadJourney(ctx, s.db, id)
				if err != nil {
					continue
				}
				item := s.journeyWorkItemJSON(ctx, j)
				switch b.bucket {
				case "pending":
					pending = append(pending, item)
				case "in_progress":
					inProgress = append(inProgress, item)
				case "completed":
					completed = append(completed, item)
				}
			}
		}
	}
	writeData(w, 200, map[string]any{
		"pending":    pending,
		"inProgress": inProgress,
		"completed":  completed,
	})
}

// ---------- bootstrap ----------

func (s *server) handleBootstrap(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	ctx := r.Context()
	out := map[string]any{
		"user": map[string]any{
			"userId":                sess.User.UserID,
			"username":              sess.User.Username,
			"fullName":              sess.User.FullName,
			"roles":                 sess.User.Roles,
			"activeRole":            sess.ActiveRole,
			"roleSelectionRequired": sess.ActiveRole == "",
		},
		"serverTime": fmtTime(nowUTC()),
	}
	if sess.ActiveRole == RoleRequester {
		samples := []map[string]any{}
		rows, err := s.db.Query(ctx, `SELECT sample_id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC LIMIT 100`, sess.User.UserID)
		if err == nil {
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				if sm, err := loadSample(ctx, s.db, id); err == nil {
					samples = append(samples, s.sampleStateJSON(ctx, sm))
				}
			}
		}
		out["requesterSamples"] = samples
	}
	if sess.ActiveRole == RoleDispatcher || sess.ActiveRole == RoleAdmin || sess.ActiveRole == RoleNode || sess.ActiveRole == RoleLab {
		out["operations"] = s.operationsState(ctx, "")
	}
	writeData(w, 200, out)
}

