func (s *server) handleSearchAuditTrail(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      *int   `json:"limit"`
		Offset     *int   `json:"offset"`
		Order      string `json:"order"`
	}
	if r.Body != nil && r.ContentLength > 0 {
		if aerr := decodeBody(r, &body); aerr != nil {
			writeErr(w, aerr)
			return
		}
	}
	ctx := r.Context()
	where := `TRUE`
	args := []any{}
	add := func(cond string, v any) {
		args = append(args, v)
		where += ` AND ` + cond + itoa(len(args))
	}
	if body.ActorID != "" {
		add(`actor_id=$`, body.ActorID)
	}
	if body.EntityType != "" {
		add(`entity_type=$`, body.EntityType)
	}
	if body.EntityID != "" {
		add(`entity_id=$`, body.EntityID)
	}
	if body.Action != "" {
		add(`action=$`, body.Action)
	}
	if body.Role != "" {
		add(`role=$`, body.Role)
	}
	if body.Success != nil {
		add(`success=$`, *body.Success)
	}
	if body.FromTime != "" {
		t, ok := parseTime(body.FromTime)
		if !ok {
			writeErr(w, errOf(400, "invalid_time", "fromTime must be an RFC3339 timestamp"))
			return
		}
		add(`occurred_at >= $`, t)
	}
	if body.ToTime != "" {
		t, ok := parseTime(body.ToTime)
		if !ok {
			writeErr(w, errOf(400, "invalid_time", "toTime must be an RFC3339 timestamp"))
			return
		}
		add(`occurred_at <= $`, t)
	}
	limit := 100
	if body.Limit != nil && *body.Limit > 0 {
		limit = *body.Limit
	}
	if limit > 1000 {
		limit = 1000
	}
	offset := 0
	if body.Offset != nil && *body.Offset > 0 {
		offset = *body.Offset
	}
	order := "newest_first"
	if body.Order == "oldest_first" {
		order = "oldest_first"
	}
	var total int
	if err := s.db.QueryRow(ctx, `SELECT count(*) FROM audit_entries WHERE `+where, args...).Scan(&total); err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	dir := "DESC"
	if order == "oldest_first" {
		dir = "ASC"
	}
	args = append(args, limit, offset)
	rows, err := s.db.Query(ctx, `SELECT audit_id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details
		FROM audit_entries WHERE `+where+` ORDER BY id `+dir+` LIMIT $`+itoa(len(args)-1)+` OFFSET $`+itoa(len(args)), args...)
	if err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	defer rows.Close()
	entries := []map[string]any{}
	for rows.Next() {
		var auditID, actorID, role, action, entityType, entityID string
		var success bool
		var occurredAt time.Time
		var details []byte
		if err := rows.Scan(&auditID, &actorID, &role, &action, &entityType, &entityID, &success, &occurredAt, &details); err != nil {
			continue
		}
		det := map[string]any{}
		if v := jsonAny(details); v != nil {
			if m, ok := v.(map[string]any); ok {
				det = m
			}
		}
		entries = append(entries, map[string]any{
			"auditId":    auditID,
			"actorId":    actorID,
			"role":       role,
			"actorRole":  role,
			"action":     action,
			"entityType": entityType,
			"entityId":   entityID,
			"success":    success,
			"occurredAt": fmtTime(occurredAt),
			"details":    det,
		})
	}
	hasMore := offset+len(entries) < total
	out := map[string]any{
		"entries":  entries,
		"total":    total,
		"returned": len(entries),
		"offset":   offset,
		"limit":    limit,
		"order":    order,
		"hasMore":  hasMore,
	}
	if hasMore {
		out["nextOffset"] = offset + len(entries)
	}
	writeData(w, 200, out)
}

