   463				if err == nil && sm.RequesterID == sess.User.UserID {
   464					if sm.LatestLat != nil && sm.LatestLng != nil {
   465						out["currentLocation"] = map[string]any{"latitude": *sm.LatestLat, "longitude": *sm.LatestLng}
