   478			mine := []map[string]any{}
   479			for _, a := range asgs {
   480				if (a.AcceptedBy != nil && *a.AcceptedBy == sess.User.UserID) ||
   481					(a.OfferedTo != nil && *a.OfferedTo == sess.User.UserID) {
   482					mine = append(mine, legJSON(a))
   483				}
   484			}
   485			if len(mine) == 0 {
   486				writeErr(w, errOf(403, "forbidden", "you have no work in this journey"))
   487				return
   488			}
   489			writeData(w, 200, map[string]any{
   490				"journeyId":   j.JourneyID,
   491				"planVersion": j.PlanVersion,
   492				"routeMode":   j.RouteMode,
   493				"status":      j.Status,
   494				"scope":       "assigned_legs",
   495				"legs":        mine,
   496			})
   497			return
   498		}
   499	}
