		c, err := loadConnection(ctx, s.db, id)
		if err == nil {
			conns = append(conns, c)
		}
	}
	return locs, conns, nil
}

// computeRoutes runs Dijkstra from the entry point and returns candidate
// routes to every reachable accepting laboratory, ordered by earliest arrival.
// start is the earliest departure time from the entry point.
func computeRoutes(locs map[string]*Location, conns []*Connection, entryID string, st *SampleType, start time.Time) []*routeResult {
	type edge struct {
		to   string
		conn *Connection
	}
	adj := map[string][]edge{}
	for _, c := range conns {
		if !c.Active {
			continue
		}
		if st.RequiresCooled && !c.Cooled {
			continue
		}
		if st.RequiresCooled {
			if c.CooledCapacity-c.CooledReserved < 1 {
				continue
			}
		} else if c.CapacityUnits-c.ReservedUnits < 1 {
			continue
		}
		adj[c.FromLocationID] = append(adj[c.FromLocationID], edge{to: c.ToLocationID, conn: c})
	}
	dist := map[string]int{entryID: 0}
	prev := map[string]*Connection{}
	visited := map[string]bool{}
	for {
		// pick unvisited node with smallest dist
		cur := ""
		curDist := 0
		for id, d := range dist {
			if visited[id] {
				continue
			}
			if cur == "" || d < curDist {
				cur, curDist = id, d
			}
		}
		if cur == "" {
			break
		}
		visited[cur] = true
		for _, e := range adj[cur] {
			nd := curDist + e.conn.TravelMinutes
			if dl, ok := dist[e.to]; !ok || nd < dl {
				dist[e.to] = nd
				prev[e.to] = e.conn
			}
		}
	}
	return findRoutes(locs, dist, prev, entryID, st, start)
}

// findRoute computes the fastest route from entry to any accepting laboratory.
func findRoute(locs map[string]*Location, conns []*Connection, entryID string, st *SampleType, start time.Time) *routeResult {
	routes := computeRoutes(locs, conns, entryID, st, start)
	if len(routes) == 0 {
		return nil
	}
	return routes[0]
}

// findRoutes lists candidate routes to every reachable accepting laboratory,
// ordered by earliest arrival.
func findRoutes(locs map[string]*Location, dist map[string]int, prev map[string]*Connection,
	entryID string, st *SampleType, start time.Time) []*routeResult {
	out := []*routeResult{}
	for id, l := range locs {
		if !l.Active || !l.Functions["laboratory"] || !containsString(l.AcceptedTypeIDs, st.SampleTypeID) {
			continue
		}
		d, ok := dist[id]
		if !ok {
			continue
		}
		// reconstruct path
		connIDs := []string{}
		nodeIDs := []string{}
		cost := 0.0
		cur := id
		for cur != entryID {
			c := prev[cur]
			if c == nil {
				break
			}
			connIDs = append([]string{c.ConnectionID}, connIDs...)
			if c.FromLocationID != entryID {
				nodeIDs = append([]string{c.FromLocationID}, nodeIDs...)
			}
			cost += c.CostUnits
			cur = c.FromLocationID
		}
		handling := 0
		for _, nid := range nodeIDs {
			if nl, ok := locs[nid]; ok {
				handling += nl.HandlingMinutes
			}
		}
		out = append(out, &routeResult{
			LabID:           id,
			ConnectionIDs:   connIDs,
			NodeIDs:         nodeIDs,
			TravelMinutes:   d,
			HandlingMinutes: handling,
			TotalCost:       cost,
			Arrival:         start.Add(time.Duration(d+handling) * time.Minute),
		})
	}
	sort.Slice(out, func(i, j int) bool { return out[i].Arrival.Before(out[j].Arrival) })
	return out
}

// routeCapacityOK verifies that every resource on the route has a free unit in
// the required pool.
func routeCapacityOK(locs map[string]*Location, conns []*Connection, route *routeResult, entryID string, cooled bool) bool {
	checkLoc := func(id string) bool {
		l, ok := locs[id]
		if !ok {
			return false
		}
		if cooled {
			return l.CooledCapacity-l.CooledReserved >= 1
		}
		return l.CapacityUnits-l.ReservedUnits >= 1
	}
	if !checkLoc(entryID) || !checkLoc(route.LabID) {
		return false
	}
	for _, nid := range route.NodeIDs {
		if !checkLoc(nid) {
			return false
		}
	}
	connByID := map[string]*Connection{}
	for _, c := range conns {
		connByID[c.ConnectionID] = c
	}
	for _, cid := range route.ConnectionIDs {
		c := connByID[cid]
		if c == nil {
			return false
		}
		if cooled {
			if c.CooledCapacity-c.CooledReserved < 1 {
				return false
			}
		} else if c.CapacityUnits-c.ReservedUnits < 1 {
			return false
		}
	}
	return true
}

// resolveEntryPoint finds the collection point serving an origin.
func resolveEntryPoint(locs map[string]*Location, originType string, originLat, originLng float64, originNodeID *string) (string, string) {
	if originType == "node" && originNodeID != nil {
		if l, ok := locs[*originNodeID]; ok && l.Active && l.Functions["collection_point"] {
			return l.LocationID, ""
		}
		return "", "outside_service_coverage"
	}
	bestID := ""
	bestDist := 0.0
	for _, l := range locs {
		if !l.Active || !l.Functions["collection_point"] {
			continue
		}
		d := haversineKm(originLat, originLng, l.Lat, l.Lng)
		if d > l.CoverageKm || d > 5 {
			continue
		}
		if bestID == "" || d < bestDist {
			bestID, bestDist = l.LocationID, d
		}
	}
	if bestID == "" {
		return "", "outside_service_coverage"
	}
	return bestID, ""
}

// evaluateServiceability runs the full structural serviceability check.
func (s *server) evaluateServiceability(ctx context.Context, originType string, originLat, originLng float64,
	originNodeID *string, st *SampleType, requestedAt, earliest, latest, deadline time.Time) *serviceabilityResult {
	res := &serviceabilityResult{}
	locs, conns, err := s.activeNetwork(ctx)
	if err != nil {
		res.Reason = "no_route"
		return res
	}
	entryID, reason := resolveEntryPoint(locs, originType, originLat, originLng, originNodeID)
	if reason != "" {
		res.Reason = reason
		return res
	}
	res.EntryID = entryID
	// any accepting lab at all?
	anyLab := false
	for _, l := range locs {
		if l.Active && l.Functions["laboratory"] && containsString(l.AcceptedTypeIDs, st.SampleTypeID) {
			anyLab = true
			break
		}
	}
	if !anyLab {
		res.Reason = "no_accepting_laboratory"
		return res
	}
	start := requestedAt
	if earliest.After(start) {
		start = earliest
	}
	if now := nowUTC(); now.After(start) {
		start = now
	}
	routes := computeRoutes(locs, conns, entryID, st, start)
	if len(routes) == 0 {
		res.Reason = "no_route"
		return res
	}
	// Prefer the earliest route that has capacity and meets the deadline.
	var firstWithCapacity *routeResult
	for _, route := range routes {
		if !routeCapacityOK(locs, conns, route, entryID, st.RequiresCooled) {
			continue
		}
		if firstWithCapacity == nil {
			firstWithCapacity = route
		}
		if !route.Arrival.After(deadline) {
			res.Route = route
			res.LabID = route.LabID
			arrival := route.Arrival
			res.Arrival = &arrival
			res.Serviceable = true
			res.Reason = ""
			return res
		}
	}
	// No route meets the deadline; report the best known arrival.
	best := routes[0]
	res.Route = best
	res.LabID = best.LabID
	arrival := best.Arrival
	res.Arrival = &arrival
	if firstWithCapacity == nil {
		res.Reason = "insufficient_capacity"
		return res
	}
	res.Reason = "deadline_unreachable"
	return res
}

// recomputeServiceability publishes a new complete snapshot version. The
// previous version remains readable until the new one is fully inserted.
func (s *server) recomputeServiceability(ctx context.Context) {
	var revision int
	_ = s.db.QueryRow(ctx, `UPDATE meta SET value = (value::int + 1)::text WHERE key='network_revision' RETURNING value::int`).Scan(&revision)
	locs, _, err := s.activeNetwork(ctx)
	if err != nil {
		return
	}
	regions := []map[string]any{}
	for _, l := range locs {
		if !l.Active || !l.Functions["collection_point"] {
			continue
		}
		regions = append(regions, map[string]any{
			"locationId": l.LocationID,
			"name":       l.Name,
			"coordinate": map[string]any{"latitude": l.Lat, "longitude": l.Lng},
			"coverageKm": l.CoverageKm,
		})
	}
	sort.Slice(regions, func(i, j int) bool { return regions[i]["locationId"].(string) < regions[j]["locationId"].(string) })
	regionsJSON, _ := json.Marshal(regions)
	var version int
	_ = s.db.QueryRow(ctx, `SELECT COALESCE(max(version),0)+1 FROM serviceability_snapshots`).Scan(&version)
	_, _ = s.db.Exec(ctx, `INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count)
		VALUES ($1,'complete',$2,$3,$4,$5)`, version, nowUTC(), revision, regionsJSON, len(regions))
	s.emit(ctx, "serviceability_updated", "serviceability", "", map[string]any{"version": version}, "", "")
}

func (s *server) currentSnapshot(ctx context.Context) (map[string]any, error) {
	var version, revision, count int
	var status string
	var computedAt time.Time
	var regions []byte
	err := s.db.QueryRow(ctx, `SELECT version, status, computed_at, network_revision, regions, active_collection_point_count
		FROM serviceability_snapshots ORDER BY version DESC LIMIT 1`).
		Scan(&version, &status, &computedAt, &revision, &regions, &count)
	if err != nil {
		return nil, err
	}
	regionList := []any{}
	if v := jsonUnmarshal(regions); v != nil {
		if arr, ok := v.([]any); ok {
			regionList = arr
		}
	}
	return map[string]any{
		"version":                    version,
		"status":                     status,
		"computedAt":                 fmtTime(computedAt),
		"networkRevision":            revision,
		"regions":                    regionList,
		"activeCollectionPointCount": count,
	}, nil
}

func (s *server) currentSnapshotVersion(ctx context.Context) int {
	var version int
	if err := s.db.QueryRow(ctx, `SELECT COALESCE(max(version),0) FROM serviceability_snapshots`).Scan(&version); err != nil {
		return 0
	}
	return version
}

func (s *server) handleReadServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if sess.ActiveRole == "" {
		writeErr(w, errOf(409, "role_not_selected", "select an active role before performing this action"))
		return
	}
	snap, err := s.currentSnapshot(r.Context())
	if err != nil {
		writeErr(w, errOf(404, "not_found", "no serviceability snapshot is available"))
		return
	}
	writeData(w, 200, snap)
}

func (s *server) handleCheckServiceability(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleRequester, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		Origin *struct {
			Latitude  float64 `json:"latitude"`
			Longitude float64 `json:"longitude"`
		} `json:"origin"`
		OriginType           string `json:"originType"`
		OriginNodeID         string `json:"originNodeId"`
		RequestedAt          string `json:"requestedAt"`
		DeliveryDeadline     string `json:"deliveryDeadline"`
		EarliestCollectionAt string `json:"earliestCollectionAt"`
		LatestCollectionAt   string `json:"latestCollectionAt"`
		SampleTypeID         string `json:"sampleTypeId"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	if body.Origin == nil || !validCoordinate(body.Origin.Latitude, body.Origin.Longitude) {
		writeErr(w, errOf(400, "invalid_origin", "origin must be a valid coordinate"))
		return
	}
	originType := body.OriginType
	if originType == "" {
		originType = "home"
	}
	if !containsString([]string{"home", "clinic", "node"}, originType) {
		writeErr(w, errOf(400, "invalid_origin_type", "originType must be home, clinic or node"))
		return
	}
	var originNodeID *string
	if originType == "node" {
		if body.OriginNodeID == "" || !isUUID(body.OriginNodeID) {
			writeErr(w, errOf(400, "invalid_origin", "originNodeId is required for node origins"))
			return
		}
		originNodeID = &body.OriginNodeID
	}
	requestedAt, ok := parseTime(body.RequestedAt)
	if !ok {
		writeErr(w, errOf(400, "invalid_time", "requestedAt must be an RFC3339 timestamp"))
		return
	}
	deadline, ok := parseTime(body.DeliveryDeadline)
	if !ok {
		writeErr(w, errOf(400, "invalid_time", "deliveryDeadline must be an RFC3339 timestamp"))
		return
	}
	if !deadline.After(requestedAt) {
		writeErr(w, errOf(400, "invalid_deadline", "deliveryDeadline must be after requestedAt"))
		return
	}
	earliest := requestedAt
	if body.EarliestCollectionAt != "" {
		earliest, ok = parseTime(body.EarliestCollectionAt)
		if !ok {
			writeErr(w, errOf(400, "invalid_time", "earliestCollectionAt must be an RFC3339 timestamp"))
			return
		}
	}
	latest := deadline
	if body.LatestCollectionAt != "" {
		latest, ok = parseTime(body.LatestCollectionAt)
		if !ok {
			writeErr(w, errOf(400, "invalid_time", "latestCollectionAt must be an RFC3339 timestamp"))
			return
		}
	}
	if latest.Before(earliest) {
		writeErr(w, errOf(400, "invalid_collection_window", "latestCollectionAt must not be before earliestCollectionAt"))
		return
	}
	st, err := loadSampleType(r.Context(), s.db, body.SampleTypeID)
	if err != nil {
		writeErr(w, errOf(404, "not_found", "sample type not found"))
		return
	}
	res := s.evaluateServiceability(r.Context(), originType, body.Origin.Latitude, body.Origin.Longitude,
		originNodeID, st, requestedAt, earliest, latest, deadline)
	s.audit(r.Context(), sess, "check_serviceability", "sample_type", body.SampleTypeID, true,
		map[string]any{"serviceable": res.Serviceable, "reason": res.Reason, "dryRun": true})
	reason := res.Reason
	if res.Serviceable {
		reason = "serviceable"
	}
	out := map[string]any{
		"serviceable":           res.Serviceable,
		"reason":                reason,
		"serviceabilityVersion": s.currentSnapshotVersion(r.Context()),
	}
	if res.LabID != "" {
		out["targetLaboratoryId"] = res.LabID
	}
	if res.Arrival != nil {
		out["estimatedArrivalAt"] = fmtTime(*res.Arrival)
	}
	writeData(w, 200, out)
}

