package main

import (
	"context"
	"bytes"
	"encoding/json"
	"io"
	"net/http"
	"time"
)

func assignmentJSON(a *Assignment) map[string]any {
	out := map[string]any{
		"assignmentId": a.AssignmentID,
		"journeyId":    a.JourneyID,
		"sampleId":     a.SampleID,
		"kind":         a.Kind,
		"sequence":     a.Sequence,
		"status":       a.Status,
	}
	if a.FromLocationID != nil {
		out["fromLocationId"] = *a.FromLocationID
	}
	if a.ToLocationID != nil {
		out["toLocationId"] = *a.ToLocationID
	}
	if a.NodeID != nil {
		out["nodeId"] = *a.NodeID
	}
	if a.LaboratoryID != nil {
		out["laboratoryId"] = *a.LaboratoryID
	}
	if a.OfferedTo != nil {
		out["offeredTo"] = *a.OfferedTo
	}
	if a.AcceptedBy != nil {
		out["acceptedBy"] = *a.AcceptedBy
	}
	if a.Progress != nil {
		out["progress"] = *a.Progress
	}
	return out
}

func (s *server) handleAcceptAssignment(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleCourier, RoleNode, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "accept_assignment", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		a, err := loadAssignment(ctx, s.db, body.AssignmentID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "assignment not found")
		}
		if kindRole(a.Kind) != sess.ActiveRole && sess.ActiveRole != RoleAdmin {
			return 400, nil, errOf(400, "ineligible_worker", "the selected role may not accept this kind of assignment")
		}
		switch a.Status {
		case AsgOffered:
			if a.OfferedTo == nil || *a.OfferedTo != sess.User.UserID {
				return 400, nil, errOf(400, "ineligible_worker", "this assignment was offered to another worker")
			}
		case AsgPending:
			return 409, nil, errOf(409, "offer_not_available", "this assignment is not currently offered")
		case AsgAccepted, AsgInProgress:
			if a.AcceptedBy != nil && *a.AcceptedBy == sess.User.UserID {
				return 201, map[string]any{"assignmentId": a.AssignmentID, "workerId": sess.User.UserID, "status": "accepted"}, nil
			}
			return 409, nil, errOf(409, "assignment_taken", "this assignment was already accepted")
		default:
			return 409, nil, errOf(409, "assignment_inactive", "this assignment is no longer active")
		}
		if a.OfferExpiresAt != nil && a.OfferExpiresAt.Before(nowUTC()) {
			return 409, nil, errOf(409, "offer_not_available", "the offer has expired")
		}
		if !sess.User.Available {
			return 409, nil, errOf(409, "worker_unavailable", "mark yourself available before accepting work")
		}
		var active int
		_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE accepted_by=$1 AND status IN ('accepted','in_progress')`, sess.User.UserID).Scan(&active)
		if active >= sess.User.CapacityUnits {
			return 409, nil, errOf(409, "worker_unavailable", "you are at your assignment capacity")
		}
		now := nowUTC()
		if _, err := s.db.Exec(ctx, `UPDATE assignments SET status='accepted', accepted_by=$2, accepted_at=$3, updated_at=now()
			WHERE assignment_id=$1 AND status='offered'`, a.AssignmentID, sess.User.UserID, now); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		j, _ := loadJourney(ctx, s.db, a.JourneyID)
		if j != nil && j.Status == JourneyPlanned {
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET status='in_progress', updated_at=now() WHERE journey_id=$1`, j.JourneyID)
		}
		s.audit(ctx, sess, "accept_assignment", "assignment", a.AssignmentID, true, map[string]any{"kind": a.Kind, "sampleId": a.SampleID})
		s.emit(ctx, "assignment_accepted", "assignment", a.AssignmentID, map[string]any{
			"assignmentId": a.AssignmentID, "workerId": sess.User.UserID, "kind": a.Kind, "sampleId": a.SampleID,
		}, "", "")
		s.kickOffers(ctx, sess, a.JourneyID)
		return 201, map[string]any{"assignmentId": a.AssignmentID, "workerId": sess.User.UserID, "status": "accepted"}, nil
	})
}

func (s *server) handleDeclineAssignment(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleCourier, RoleNode, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		AssignmentID   string `json:"assignmentId"`
		Reason         string `json:"reason"`
		DeclinedAt     string `json:"declinedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "decline_assignment", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		a, err := loadAssignment(ctx, s.db, body.AssignmentID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "assignment not found")
		}
		if a.Status != AsgOffered || a.OfferedTo == nil || *a.OfferedTo != sess.User.UserID {
			return 409, nil, errOf(409, "offer_not_available", "this assignment is not currently offered to you")
		}
		declinedAt := nowUTC()
		if body.DeclinedAt != "" {
			t, ok := parseTime(body.DeclinedAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "declinedAt must be an RFC3339 timestamp")
			}
			declinedAt = t
		}
		declined := append(a.DeclinedBy, sess.User.UserID)
		dj, _ := json.Marshal(declined)
		if _, err := s.db.Exec(ctx, `UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL,
			declined_by=$2, updated_at=now() WHERE assignment_id=$1`, a.AssignmentID, dj); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		if _, err := s.db.Exec(ctx, `UPDATE users SET recent_declines = recent_declines + 1, last_decline_at=$2 WHERE user_id=$1`,
			sess.User.UserID, declinedAt); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		s.audit(ctx, sess, "decline_assignment", "assignment", a.AssignmentID, true,
			map[string]any{"kind": a.Kind, "sampleId": a.SampleID, "reason": body.Reason})
		s.emit(ctx, "assignment_declined", "assignment", a.AssignmentID, map[string]any{
			"assignmentId": a.AssignmentID, "workerId": sess.User.UserID, "kind": a.Kind, "sampleId": a.SampleID,
		}, "", "")
		// re-offer to the next eligible worker
		a, _ = loadAssignment(ctx, s.db, a.AssignmentID)
		offeredTo, noQualified, _ := s.offerAssignment(ctx, sess, a)
		if noQualified {
			s.flagNoQualifiedWorker(ctx, sess, a.SampleID, a.AssignmentID)
		}
		out := map[string]any{
			"assignmentId": a.AssignmentID,
			"status":       "declined",
			"declinedBy":   sess.User.UserID,
			"declinedAt":   fmtTime(declinedAt),
		}
		if offeredTo != nil {
			out["reofferedTo"] = *offeredTo
		}
		return 201, out, nil
	})
}

var transportProgressOrder = []string{"at_pickup", "picked_up", "in_transit", "arrived", "delivered"}

func (s *server) handleUpdateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleCourier, RoleNode, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "update_assignment_progress", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		a, err := loadAssignment(ctx, s.db, body.AssignmentID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "assignment not found")
		}
		if a.AcceptedBy == nil || *a.AcceptedBy != sess.User.UserID {
			return 403, nil, errOf(403, "forbidden", "only the assigned worker may record progress")
		}
		if a.Status != AsgAccepted && a.Status != AsgInProgress {
			return 409, nil, errOf(409, "assignment_inactive", "this assignment is not active")
		}
		occurredAt := nowUTC()
		if body.OccurredAt != "" {
			t, ok := parseTime(body.OccurredAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "occurredAt must be an RFC3339 timestamp")
			}
			occurredAt = t
		}
		sample, err := loadSample(ctx, s.db, a.SampleID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "sample not found")
		}
		// validate transition
		if a.Kind == KindTransport {
			if !containsString(transportProgressOrder, body.Status) {
				return 409, nil, errOf(409, "invalid_transition", "unknown transport progress status")
			}
			curIdx := -1
			if a.Progress != nil {
				for i, p := range transportProgressOrder {
					if p == *a.Progress {
						curIdx = i
					}
				}
			}
			nextIdx := -1
			for i, p := range transportProgressOrder {
				if p == body.Status {
					nextIdx = i
				}
			}
			if nextIdx <= curIdx {
				return 409, nil, errOf(409, "invalid_transition", "progress may only move forward")
			}
			if (body.Status == "picked_up" || body.Status == "in_transit") &&
				(sample.CurrentHolderID == nil || *sample.CurrentHolderID != sess.User.UserID) {
				return 409, nil, errOf(409, "custody_required", "you must hold custody of the sample before transporting it")
			}
		} else {
			if body.Status != AsgInProgress && body.Status != AsgCompleted {
				return 409, nil, errOf(409, "invalid_transition", "status must be in_progress or completed for this assignment kind")
			}
			if body.Status == AsgCompleted && a.Kind == KindNode {
				// node work completes through the outgoing handoff
				if sample.CurrentHolderID == nil || *sample.CurrentHolderID != sess.User.UserID {
					return 409, nil, errOf(409, "custody_required", "you must hold custody of the sample")
				}
			}
		}
		newStatus := AsgInProgress
		var completedAt *time.Time
		if body.Status == AsgCompleted || body.Status == "delivered" {
			newStatus = AsgCompleted
			completedAt = &occurredAt
		}
		if _, err := s.db.Exec(ctx, `UPDATE assignments SET status=$2, progress=$3, completed_at=COALESCE($4, completed_at), updated_at=now()
			WHERE assignment_id=$1`, a.AssignmentID, newStatus, body.Status, completedAt); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		// sample-level effects
		switch body.Status {
		case "picked_up", "in_transit":
			if sample.Status != SampleInTransit {
				s.setSampleStatus(ctx, sess, sample.SampleID, SampleInTransit, map[string]any{"assignmentId": a.AssignmentID})
			}
		case "delivered":
			if a.ToLocationID != nil {
				_, _ = s.db.Exec(ctx, `UPDATE samples SET latest_lat=(SELECT lat FROM locations WHERE location_id=$2),
					latest_lng=(SELECT lng FROM locations WHERE location_id=$2), location_recorded_at=$3, updated_at=now()
					WHERE sample_id=$1`, sample.SampleID, *a.ToLocationID, occurredAt)
			}
		}
		// deadline check
		req, _ := loadRequest(ctx, s.db, sample.RequestID)
		if req != nil && occurredAt.After(req.DeliveryDeadline) && sample.Status != SampleReceived {
			s.markSampleException(ctx, sess, sample.SampleID, "deadline_missed", "the delivery deadline has passed")
		}
		s.audit(ctx, sess, "update_assignment_progress", "assignment", a.AssignmentID, true,
			map[string]any{"status": body.Status, "sampleId": a.SampleID})
		s.emit(ctx, "assignment_progress", "assignment", a.AssignmentID, map[string]any{
			"assignmentId": a.AssignmentID, "status": body.Status, "sampleId": a.SampleID,
		}, "", "")
		s.kickOffers(ctx, sess, a.JourneyID)
		return 201, map[string]any{"assignmentId": a.AssignmentID, "status": newStatus, "progress": body.Status}, nil
	})
}

func (s *server) markSampleException(ctx context.Context, sess *session, sampleID, excType, reason string) {
	exc := map[string]any{"type": excType, "reason": reason, "observedAt": fmtTime(nowUTC())}
	excJSON, _ := json.Marshal(exc)
	_, _ = s.db.Exec(ctx, `UPDATE samples SET exception=$2, updated_at=now() WHERE sample_id=$1`, sampleID, excJSON)
	s.setSampleStatus(ctx, sess, sampleID, SampleException, map[string]any{"reason": excType})
	s.emit(ctx, "exception_raised", "sample", sampleID, map[string]any{"sampleId": sampleID, "type": excType}, "", "")
}

func (s *server) handleCollectAndSeal(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		SampleID             string   `json:"sampleId"`
		AssignmentID         string   `json:"assignmentId"`
		CollectedAt          string   `json:"collectedAt"`
		ContainerType        string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		IdempotencyKey       string   `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "collect_and_seal_sample", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		a, err := loadAssignment(ctx, s.db, body.AssignmentID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "assignment not found")
		}
		if body.SampleID != "" && body.SampleID != a.SampleID {
			return 400, nil, errOf(400, "invalid_json", "sampleId does not match the assignment's sample")
		}
		if a.Kind != KindCollection {
			return 400, nil, errOf(400, "invalid_json", "assignmentId must reference a collection assignment")
		}
		if a.AcceptedBy == nil || *a.AcceptedBy != sess.User.UserID {
			return 403, nil, errOf(403, "forbidden", "only the assigned collection professional may collect this sample")
		}
		if a.Status != AsgAccepted && a.Status != AsgInProgress {
			return 409, nil, errOf(409, "assignment_inactive", "this collection assignment is not active")
		}
		collectedAt := nowUTC()
		if body.CollectedAt != "" {
			t, ok := parseTime(body.CollectedAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "collectedAt must be an RFC3339 timestamp")
			}
			collectedAt = t
		}
		sample, err := loadSample(ctx, s.db, a.SampleID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "sample not found")
		}
		if sample.Sealed {
			return 409, nil, errOf(409, "invalid_assignment_state", "the sample is already sealed")
		}
		req, err := loadRequest(ctx, s.db, sample.RequestID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "request not found")
		}
		st, err := loadSampleType(ctx, s.db, req.SampleTypeID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "sample type not found")
		}
		if collectedAt.Before(req.EarliestCollection) || collectedAt.After(req.LatestCollection) {
			return 409, nil, errOf(409, "outside_collection_window", "collectedAt is outside the collection window")
		}
		if st.QualifiedRequired && !workerQualified(sess.User, st) {
			return 409, nil, errOf(409, "certification_inactive", "you do not hold an active certification for this sample type")
		}
		if body.ContainerType != "" && st.ContainerType != "" && body.ContainerType != st.ContainerType {
			return 400, nil, errOf(400, "handling_noncompliant", "containerType does not match the required container")
		}
		handlingCompliant := true
		if body.ObservedTemperatureC != nil {
			handlingCompliant = *body.ObservedTemperatureC >= st.TempMinC && *body.ObservedTemperatureC <= st.TempMaxC
		}
		now := nowUTC()
		if _, err := s.db.Exec(ctx, `UPDATE samples SET sealed=TRUE, sealed_at=$2, current_holder_id=$3, updated_at=now()
			WHERE sample_id=$1`, sample.SampleID, collectedAt, sess.User.UserID); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		if _, err := s.db.Exec(ctx, `UPDATE assignments SET status='completed', progress='completed', completed_at=$2, updated_at=now()
			WHERE assignment_id=$1`, a.AssignmentID, now); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		s.setSampleStatus(ctx, sess, sample.SampleID, SampleSealed, map[string]any{"assignmentId": a.AssignmentID})
		details := map[string]any{"assignmentId": a.AssignmentID, "collectedAt": fmtTime(collectedAt), "containerType": body.ContainerType}
		if body.ObservedTemperatureC != nil {
			details["observedTemperatureC"] = *body.ObservedTemperatureC
		}
		s.audit(ctx, sess, "collect_and_seal", "sample", sample.SampleID, true, details)
		s.emit(ctx, "sample_sealed", "sample", sample.SampleID, map[string]any{"sampleId": sample.SampleID, "collectorId": sess.User.UserID}, "", "")
		if !handlingCompliant {
			s.markSampleException(ctx, sess, sample.SampleID, "temperature_excursion", "observed temperature is outside the required range")
		}
		s.kickOffers(ctx, sess, a.JourneyID)
		return 201, map[string]any{
			"sampleId":          sample.SampleID,
			"status":            SampleSealed,
			"currentHolderId":   sess.User.UserID,
			"sealedAt":          fmtTime(collectedAt),
			"handlingCompliant": handlingCompliant,
		}, nil
	})
}

func (s *server) handleRecordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleCourier, RoleNode, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	var body struct {
		AssignmentID string   `json:"assignmentId"`
		Coordinate   *coordIn `json:"coordinate"`
		RecordedAt   string   `json:"recordedAt"`
		Sequence     *int     `json:"sequence"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	if body.Coordinate == nil || !validCoordinate(body.Coordinate.Latitude, body.Coordinate.Longitude) {
		writeErr(w, errOf(400, "invalid_coordinate", "coordinate must be a valid latitude/longitude"))
		return
	}
	if body.Sequence == nil || *body.Sequence < 1 {
		writeErr(w, errOf(400, "invalid_sequence", "sequence must be a positive integer"))
		return
	}
	recordedAt := nowUTC()
	if body.RecordedAt != "" {
		t, ok := parseTime(body.RecordedAt)
		if !ok {
			writeErr(w, errOf(400, "invalid_time", "recordedAt must be an RFC3339 timestamp"))
			return
		}
		recordedAt = t
	}
	ctx := r.Context()
	a, err := loadAssignment(ctx, s.db, body.AssignmentID)
	if err != nil {
		writeErr(w, errOf(404, "not_found", "assignment not found"))
		return
	}
	if a.AcceptedBy == nil || *a.AcceptedBy != sess.User.UserID {
		writeErr(w, errOf(403, "forbidden", "only the assigned worker may record locations for this assignment"))
		return
	}
	if *body.Sequence <= a.LastLocationSeq {
		writeErr(w, errOf(400, "invalid_sequence", "sequence must increase with each location update"))
		return
	}
	if a.LastLocationSeq > 0 {
		var lastAt time.Time
		if err := s.db.QueryRow(ctx, `SELECT last_location_at FROM assignments WHERE assignment_id=$1`, a.AssignmentID).Scan(&lastAt); err == nil {
			if recordedAt.Before(lastAt) {
				writeErr(w, errOf(409, "stale_location", "recordedAt is older than the last recorded location"))
				return
			}
		}
	}
	if _, err := s.db.Exec(ctx, `UPDATE assignments SET last_location_seq=$2, last_location_at=$3, updated_at=now() WHERE assignment_id=$1`,
		a.AssignmentID, *body.Sequence, recordedAt); err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	if _, err := s.db.Exec(ctx, `UPDATE users SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4 WHERE user_id=$1`,
		sess.User.UserID, body.Coordinate.Latitude, body.Coordinate.Longitude, recordedAt); err != nil {
		writeErr(w, errOf(500, "internal_error", err.Error()))
		return
	}
	// If the worker currently holds the sample, the sample moves with them.
	sample, err := loadSample(ctx, s.db, a.SampleID)
	if err == nil && sample.CurrentHolderID != nil && *sample.CurrentHolderID == sess.User.UserID {
		_, _ = s.db.Exec(ctx, `UPDATE samples SET latest_lat=$2, latest_lng=$3, location_recorded_at=$4, updated_at=now() WHERE sample_id=$1`,
			sample.SampleID, body.Coordinate.Latitude, body.Coordinate.Longitude, recordedAt)
		s.emit(ctx, "sample_location", "sample", sample.SampleID, map[string]any{
			"sampleId": sample.SampleID, "latitude": body.Coordinate.Latitude, "longitude": body.Coordinate.Longitude,
		}, "", "")
	}
	s.audit(ctx, sess, "record_worker_location", "assignment", a.AssignmentID, true,
		map[string]any{"sequence": *body.Sequence, "latitude": body.Coordinate.Latitude, "longitude": body.Coordinate.Longitude})
	s.emit(ctx, "worker_location", "user", sess.User.UserID, map[string]any{
		"workerId": sess.User.UserID, "latitude": body.Coordinate.Latitude, "longitude": body.Coordinate.Longitude,
	}, "", "")
	writeData(w, 201, map[string]any{
		"assignmentId": a.AssignmentID,
		"coordinate":   map[string]any{"latitude": body.Coordinate.Latitude, "longitude": body.Coordinate.Longitude},
		"recordedAt":   fmtTime(recordedAt),
		"sequence":     *body.Sequence,
	})
}

func (s *server) handleRecordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleCollector, RoleCourier, RoleNode, RoleLab, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		LocationID           string  `json:"locationId"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		RecordedAt           string  `json:"recordedAt"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "record_handling_checkpoint", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		sample, err := loadSample(ctx, s.db, body.SampleID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "sample not found")
		}
		if sample.Status == SampleReceived || sample.Status == SampleExpired || sample.Status == SampleCancelled {
			return 409, nil, errOf(409, "terminal_sample", "the sample's journey has already ended")
		}
		if sample.CurrentHolderID == nil || *sample.CurrentHolderID != sess.User.UserID {
			return 403, nil, errOf(403, "forbidden", "only the current holder may record a handling checkpoint")
		}
		a, err := loadAssignment(ctx, s.db, body.AssignmentID)
		if err != nil || a.SampleID != sample.SampleID {
			return 404, nil, errOf(404, "not_found", "assignment not found for this sample")
		}
		if a.AcceptedBy == nil || *a.AcceptedBy != sess.User.UserID ||
			(a.Status != AsgAccepted && a.Status != AsgInProgress && a.Status != AsgCompleted) {
			return 409, nil, errOf(409, "assignment_inactive", "the assignment is not active")
		}
		recordedAt := nowUTC()
		if body.RecordedAt != "" {
			t, ok := parseTime(body.RecordedAt)
			if !ok {
				return 400, nil, errOf(400, "invalid_time", "recordedAt must be an RFC3339 timestamp")
			}
			recordedAt = t
		}
		req, _ := loadRequest(ctx, s.db, sample.RequestID)
		st, _ := loadSampleType(ctx, s.db, req.SampleTypeID)
		compliant := true
		if body.ContainerType != "" && st.ContainerType != "" && body.ContainerType != st.ContainerType {
			compliant = false
		}
		if body.ObservedTemperatureC < st.TempMinC || body.ObservedTemperatureC > st.TempMaxC {
			compliant = false
		}
		checkpointID := newUUID()
		var locID *string
		if body.LocationID != "" && isUUID(body.LocationID) {
			locID = &body.LocationID
		}
		if _, err := s.db.Exec(ctx, `INSERT INTO checkpoints (checkpoint_id, sample_id, assignment_id, location_id, actor_id,
			container_type, observed_temperature_c, compliant, recorded_at) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
			checkpointID, sample.SampleID, a.AssignmentID, locID, sess.User.UserID,
			body.ContainerType, body.ObservedTemperatureC, compliant, recordedAt); err != nil {
			return 500, nil, errOf(500, "internal_error", err.Error())
		}
		s.audit(ctx, sess, "handling_checkpoint", "sample", sample.SampleID, true,
			map[string]any{"checkpointId": checkpointID, "compliant": compliant, "observedTemperatureC": body.ObservedTemperatureC})
		if !compliant {
			s.markSampleException(ctx, sess, sample.SampleID, "handling_noncompliant", "observed container or temperature is outside the required range")
		}
		sample, _ = loadSample(ctx, s.db, sample.SampleID)
		return 201, map[string]any{
			"checkpointId": checkpointID,
			"compliant":    compliant,
			"sampleStatus": sample.Status,
		}, nil
	})
}

