package main

import (
	"bytes"
	"context"
	"encoding/json"
	"io"
	"net/http"
	"time"
)

// rebuildRoute reconstructs a routeResult from a journey's stored structure.
func (s *server) rebuildRoute(ctx context.Context, j *Journey, start time.Time) *routeResult {
	route := &routeResult{
		ConnectionIDs: j.ConnectionIDs,
		NodeIDs:       j.NodeIDs,
	}
	if j.LaboratoryID != nil {
		route.LabID = *j.LaboratoryID
	}
	t := start
	for i, cid := range j.ConnectionIDs {
		c, err := loadConnection(ctx, s.db, cid)
		if err != nil {
			continue
		}
		route.TravelMinutes += c.TravelMinutes
		route.TotalCost += c.CostUnits
		t = t.Add(time.Duration(c.TravelMinutes) * time.Minute)
		if i < len(j.ConnectionIDs)-1 {
			if nl, err := loadLocation(ctx, s.db, c.ToLocationID); err == nil {
				route.HandlingMinutes += nl.HandlingMinutes
				t = t.Add(time.Duration(nl.HandlingMinutes) * time.Minute)
			}
		}
	}
	route.Arrival = t
	return route
}

func (s *server) handleSplitJourney(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		JourneyID           string   `json:"journeyId"`
		SampleIDs           []string `json:"sampleIds"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "split_journey", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		j, err := loadJourney(ctx, s.db, body.JourneyID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "journey not found")
		}
		if aerr := checkPlanVersion(j, body.ExpectedPlanVersion); aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
		return s.splitJourneySamples(ctx, sess, j, body.SampleIDs)
	})
}

func (s *server) splitJourneySamples(ctx context.Context, sess *session, j *Journey, sampleIDs []string) (int, any, *apiError) {
	{
		if len(sampleIDs) == 0 {
			return 400, nil, errOf(400, "invalid_sample_set", "sampleIds must not be empty")
		}
		current := journeySampleIDs(ctx, s.db, j.JourneyID)
		for _, sid := range sampleIDs {
			if !containsString(current, sid) {
				return 400, nil, errOf(400, "invalid_sample_set", "sampleIds must belong to the journey")
			}
		}
		if len(sampleIDs) == len(current) {
			return 400, nil, errOf(400, "invalid_sample_set", "splitting must leave at least one sample in the original journey")
		}
		start := nowUTC()
		route := s.rebuildRoute(ctx, j, start)
		var splitJourneyID string
		for _, sid := range sampleIDs {
			sm, err := loadSample(ctx, s.db, sid)
			if err != nil {
				continue
			}
			rq, err := loadRequest(ctx, s.db, sm.RequestID)
			if err != nil {
				continue
			}
			st, err := loadSampleType(ctx, s.db, rq.SampleTypeID)
			if err != nil {
				continue
			}
			if route.Arrival.After(rq.DeliveryDeadline) {
				return 409, nil, errOf(409, "deadline_exceeded", "a split sample can no longer meet its deadline")
			}
			entry := ""
			if j.EntryLocationID != nil {
				entry = *j.EntryLocationID
			}
			preSealed := sm.Sealed
			anchor := ""
			if sm.CurrentHolderID != nil {
				anchor = *sm.CurrentHolderID
			}
			nj, aerr := s.createJourneyPlan(ctx, sess, sm, rq, st, entry, route, start, preSealed, anchor)
			if aerr != nil {
				return aerr.HTTPStatus, nil, aerr
			}
			if !preSealed {
				// keep collection work in the original journey; split journeys start sealed
				_, _ = s.db.Exec(ctx, `DELETE FROM assignments WHERE journey_id=$1 AND kind='collection'`, nj.JourneyID)
			}
			if splitJourneyID == "" {
				splitJourneyID = nj.JourneyID
			} else {
				_, _ = s.db.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, splitJourneyID, sid)
				_, _ = s.db.Exec(ctx, `UPDATE assignments SET journey_id=$2 WHERE journey_id=$1`, nj.JourneyID, splitJourneyID)
				_, _ = s.db.Exec(ctx, `UPDATE reservations SET journey_id=$2 WHERE journey_id=$1`, nj.JourneyID, splitJourneyID)
				_, _ = s.db.Exec(ctx, `DELETE FROM journeys WHERE journey_id=$1`, nj.JourneyID)
			}
			_, _ = s.db.Exec(ctx, `DELETE FROM journey_samples WHERE journey_id=$1 AND sample_id=$2`, j.JourneyID, sid)
			_, _ = s.db.Exec(ctx, `UPDATE samples SET active_journey_id=$2, updated_at=now() WHERE sample_id=$1`, sid, splitJourneyID)
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, j.JourneyID)
		if len(body.SampleIDs) > 1 || len(current)-len(body.SampleIDs) > 1 {
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET route_mode='batched' WHERE journey_id=$1`, splitJourneyID)
		}
		s.audit(ctx, sess, "split_journey", "journey", j.JourneyID, true,
			map[string]any{"splitJourneyId": splitJourneyID, "sampleIds": body.SampleIDs})
		s.emit(ctx, "journey_split", "journey", j.JourneyID, map[string]any{
			"journeyId": j.JourneyID, "splitJourneyId": splitJourneyID,
		}, "", "")
		s.kickOffers(ctx, sess, splitJourneyID)
		j, _ = loadJourney(ctx, s.db, j.JourneyID)
		sj, _ := loadJourney(ctx, s.db, splitJourneyID)
		return 201, map[string]any{
			"journey":      s.journeyPlanJSON(ctx, j),
			"splitJourney": s.journeyPlanJSON(ctx, sj),
		}, nil
	})
}

func (s *server) handleMergeJourneys(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "merge_journeys", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		target, err := loadJourney(ctx, s.db, body.TargetJourneyID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "target journey not found")
		}
		if aerr := checkPlanVersion(target, body.ExpectedPlanVersion); aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
		if len(body.SourceJourneyIDs) == 0 {
			return 400, nil, errOf(400, "invalid_json", "sourceJourneyIds must not be empty")
		}
		sources := []*Journey{}
		for _, id := range body.SourceJourneyIDs {
			sj, err := loadJourney(ctx, s.db, id)
			if err != nil {
				return 404, nil, errOf(404, "not_found", "source journey not found")
			}
			if sj.Status != JourneyPlanned && sj.Status != JourneyInProgress {
				return 409, nil, errOf(409, "inactive_plan", "a source journey is no longer active")
			}
			sources = append(sources, sj)
		}
		// gather all samples and validate compatibility
		allSampleIDs := journeySampleIDs(ctx, s.db, target.JourneyID)
		for _, sj := range sources {
			allSampleIDs = append(allSampleIDs, journeySampleIDs(ctx, s.db, sj.JourneyID)...)
		}
		types := map[string]*SampleType{}
		for _, sid := range allSampleIDs {
			sm, err := loadSample(ctx, s.db, sid)
			if err != nil {
				return 404, nil, errOf(404, "not_found", "sample not found")
			}
			rq, err := loadRequest(ctx, s.db, sm.RequestID)
			if err != nil {
				return 404, nil, errOf(404, "not_found", "request not found")
			}
			st, err := loadSampleType(ctx, s.db, rq.SampleTypeID)
			if err != nil {
				return 404, nil, errOf(404, "not_found", "sample type not found")
			}
			if !st.BatchingAllowed {
				return 409, nil, errOf(409, "pulse_no_batch", "a time-critical sample may not be combined into a batch")
			}
			types[st.SampleTypeID] = st
			// deadline check against the target ETA
			if target.EstimatedDeliveryAt != nil && target.EstimatedDeliveryAt.After(rq.DeliveryDeadline) {
				return 409, nil, errOf(409, "deadline_exceeded", "a merged sample can no longer meet its deadline")
			}
		}
		for _, st := range types {
			for _, other := range types {
				if st.SampleTypeID == other.SampleTypeID {
					continue
				}
				if containsString(st.IncompatibleIDs, other.SampleTypeID) || containsString(other.IncompatibleIDs, st.SampleTypeID) {
					return 409, nil, errOf(409, "incompatible_batch", "the samples are not allowed to travel together")
				}
			}
		}
		// capacity: reserve one extra unit per added sample on the target route
		type resv struct{ rt, rid string }
		added := []resv{}
		cooled := false
		for _, st := range types {
			if st.RequiresCooled {
				cooled = true
			}
		}
		reserveExtra := func(rt, rid string) *apiError {
			for range body.SourceJourneyIDs {
				var n int
				if rt == "location" {
					if cooled {
						_ = s.db.QueryRow(ctx, `SELECT cooled_capacity_units - cooled_reserved_units FROM locations WHERE location_id=$1`, rid).Scan(&n)
					} else {
						_ = s.db.QueryRow(ctx, `SELECT capacity_units - reserved_units FROM locations WHERE location_id=$1`, rid).Scan(&n)
					}
				} else {
					if cooled {
						_ = s.db.QueryRow(ctx, `SELECT cooled_capacity_units - cooled_reserved_units FROM connections WHERE connection_id=$1`, rid).Scan(&n)
					} else {
						_ = s.db.QueryRow(ctx, `SELECT capacity_units - reserved_units FROM connections WHERE connection_id=$1`, rid).Scan(&n)
					}
				}
				if n < 1 {
					if cooled {
						return errOf(409, "cooled_capacity_exhausted", "cooled capacity is not available for the merged batch")
					}
					return errOf(409, "capacity_exhausted", "capacity is not available for the merged batch")
				}
				if rt == "location" {
					if cooled {
						_, _ = s.db.Exec(ctx, `UPDATE locations SET cooled_reserved_units = cooled_reserved_units + 1 WHERE location_id=$1`, rid)
					} else {
						_, _ = s.db.Exec(ctx, `UPDATE locations SET reserved_units = reserved_units + 1 WHERE location_id=$1`, rid)
					}
				} else {
					if cooled {
						_, _ = s.db.Exec(ctx, `UPDATE connections SET cooled_reserved_units = cooled_reserved_units + 1 WHERE connection_id=$1`, rid)
					} else {
						_, _ = s.db.Exec(ctx, `UPDATE connections SET reserved_units = reserved_units + 1 WHERE connection_id=$1`, rid)
					}
				}
				added = append(added, resv{rt, rid})
			}
			return nil
		}
		resources := []resv{}
		if target.EntryLocationID != nil {
			resources = append(resources, resv{"location", *target.EntryLocationID})
		}
		for _, nid := range target.NodeIDs {
			resources = append(resources, resv{"location", nid})
		}
		if target.LaboratoryID != nil {
			resources = append(resources, resv{"location", *target.LaboratoryID})
		}
		for _, cid := range target.ConnectionIDs {
			resources = append(resources, resv{"connection", cid})
		}
		for _, rv := range resources {
			if aerr := reserveExtra(rv.rt, rv.rid); aerr != nil {
				// roll back extras
				for _, a := range added {
					if a.rt == "location" {
						if cooled {
							_, _ = s.db.Exec(ctx, `UPDATE locations SET cooled_reserved_units = GREATEST(0, cooled_reserved_units - 1) WHERE location_id=$1`, a.rid)
						} else {
							_, _ = s.db.Exec(ctx, `UPDATE locations SET reserved_units = GREATEST(0, reserved_units - 1) WHERE location_id=$1`, a.rid)
						}
					} else {
						if cooled {
							_, _ = s.db.Exec(ctx, `UPDATE connections SET cooled_reserved_units = GREATEST(0, cooled_reserved_units - 1) WHERE connection_id=$1`, a.rid)
						} else {
							_, _ = s.db.Exec(ctx, `UPDATE connections SET reserved_units = GREATEST(0, reserved_units - 1) WHERE connection_id=$1`, a.rid)
						}
					}
				}
				return aerr.HTTPStatus, nil, aerr
			}
		}
		// move samples to the target journey
		mergedIDs := []string{}
		for _, sj := range sources {
			for _, sid := range journeySampleIDs(ctx, s.db, sj.JourneyID) {
				_, _ = s.db.Exec(ctx, `INSERT INTO journey_samples (journey_id, sample_id) VALUES ($1,$2) ON CONFLICT DO NOTHING`, target.JourneyID, sid)
				_, _ = s.db.Exec(ctx, `UPDATE samples SET active_journey_id=$2, updated_at=now() WHERE sample_id=$1`, sid, target.JourneyID)
				_, _ = s.db.Exec(ctx, `INSERT INTO reservations (reservation_id, resource_type, resource_id, journey_id, sample_id, cooled, units)
					SELECT $1, resource_type, resource_id, $2, $3, $4, 1 FROM reservations WHERE journey_id=$5 AND sample_id=$3 AND released=FALSE LIMIT 1`,
					newUUID(), target.JourneyID, sid, cooled, sj.JourneyID)
			}
			mergedIDs = append(mergedIDs, sj.JourneyID)
			s.cancelJourneyInternal(ctx, sess, sj, "merged into "+target.JourneyID, JourneyMerged)
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET route_mode='batched', plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, target.JourneyID)
		s.audit(ctx, sess, "merge_journeys", "journey", target.JourneyID, true,
			map[string]any{"mergedJourneyIds": mergedIDs, "sampleIds": allSampleIDs})
		s.emit(ctx, "journey_merged", "journey", target.JourneyID, map[string]any{
			"journeyId": target.JourneyID, "mergedJourneyIds": mergedIDs,
		}, "", "")
		target, _ = loadJourney(ctx, s.db, target.JourneyID)
		return 201, map[string]any{
			"journey":              s.journeyPlanJSON(ctx, target),
			"mergedFromJourneyIds": mergedIDs,
		}, nil
	})
}

func (s *server) handleEditActivePlan(w http.ResponseWriter, r *http.Request) {
	sess, aerr := s.requireAuth(w, r)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	if aerr := requireRole(sess, RoleDispatcher, RoleAdmin); aerr != nil {
		writeErr(w, aerr)
		return
	}
	raw, _ := io.ReadAll(r.Body)
	r.Body = io.NopCloser(bytes.NewReader(raw))
	var body struct {
		JourneyID           string                 `json:"journeyId"`
		ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
		ChangeType          string                 `json:"changeType"`
		Changes             map[string]any         `json:"changes"`
		IdempotencyKey      string                 `json:"idempotencyKey"`
	}
	if aerr := decodeBody(r, &body); aerr != nil {
		writeErr(w, aerr)
		return
	}
	s.idempotent(w, r, sess, "edit_active_plan", body.IdempotencyKey, raw, func() (int, any, *apiError) {
		ctx := r.Context()
		j, err := loadJourney(ctx, s.db, body.JourneyID)
		if err != nil {
			return 404, nil, errOf(404, "not_found", "journey not found")
		}
		if aerr := checkPlanVersion(j, body.ExpectedPlanVersion); aerr != nil {
			return aerr.HTTPStatus, nil, aerr
		}
		if body.Changes == nil {
			body.Changes = map[string]any{}
		}
		switch body.ChangeType {
		case "replace_worker", "reassign_worker":
			assignmentID, _ := body.Changes["assignmentId"].(string)
			workerID, _ := body.Changes["workerId"].(string)
			if assignmentID == "" || !isUUID(workerID) {
				return 400, nil, errOf(400, "invalid_worker", "changes must include assignmentId and workerId")
			}
			a, err := loadAssignment(ctx, s.db, assignmentID)
			if err != nil || a.JourneyID != j.JourneyID {
				return 404, nil, errOf(404, "not_found", "assignment not found in this journey")
			}
			if a.Status == AsgCompleted || a.Status == AsgCancelled {
				return 409, nil, errOf(409, "inactive_plan", "the assignment is already finished")
			}
			worker, err := loadUser(ctx, s.db, workerID)
			if err != nil || !worker.Active {
				return 400, nil, errOf(400, "invalid_worker", "workerId does not reference an active user")
			}
			if !containsString(worker.Roles, kindRole(a.Kind)) {
				return 409, nil, errOf(409, "ineligible_worker", "the worker is not eligible for this assignment")
			}
			st, _ := sampleTypeForSample(ctx, s, a.SampleID)
			if a.Kind == KindCollection && st != nil && !workerQualified(worker, st) {
				return 409, nil, errOf(409, "ineligible_worker", "the worker is not qualified for this sample type")
			}
			if a.Kind == KindNode && (worker.AssignedLocationID == nil || a.NodeID == nil || *worker.AssignedLocationID != *a.NodeID) {
				return 409, nil, errOf(409, "ineligible_worker", "the worker is not assigned to this node")
			}
			if a.Kind == KindLab && (worker.AssignedLocationID == nil || a.LaboratoryID == nil || *worker.AssignedLocationID != *a.LaboratoryID) {
				return 409, nil, errOf(409, "ineligible_worker", "the worker is not assigned to this laboratory")
			}
			now := nowUTC()
			expires := now.Add(offerTimeout)
			_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offered_at=$3, offer_expires_at=$4,
				accepted_by=NULL, accepted_at=NULL, updated_at=now() WHERE assignment_id=$1`, assignmentID, workerID, now, expires)
			s.audit(ctx, sess, "edit_active_plan", "assignment", assignmentID, true,
				map[string]any{"changeType": body.ChangeType, "workerId": workerID})
			s.emit(ctx, "assignment_offered", "assignment", assignmentID, map[string]any{
				"assignmentId": assignmentID, "workerId": workerID, "kind": a.Kind, "sampleId": a.SampleID,
			}, kindRole(a.Kind), workerID)
		case "add_stop":
			locationID, _ := body.Changes["locationId"].(string)
			if locationID == "" {
				return 400, nil, errOf(400, "invalid_stop", "changes must include locationId")
			}
			l, err := loadLocation(ctx, s.db, locationID)
			if err != nil || !l.Active {
				return 400, nil, errOf(400, "invalid_stop", "locationId must reference an active location")
			}
			dwell := l.HandlingMinutes
			if d, ok := body.Changes["dwellMinutes"].(float64); ok {
				dwell = int(d)
			}
			stops := j.Stops
			if len(stops) == 0 {
				return 409, nil, errOf(409, "invalid_stop_order", "the journey has no stops")
			}
			newStop := map[string]any{
				"stopId": newUUID(), "locationId": locationID, "stopType": "handoff",
				"sequence": len(stops) - 1, "estimatedAt": stops[len(stops)-1]["estimatedAt"], "dwellMinutes": dwell,
			}
			stops = append(stops[:len(stops)-1], newStop, stops[len(stops)-1])
			for i, st := range stops {
				st["sequence"] = i
			}
			stopsJSON, _ := json.Marshal(stops)
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET stops=$2, plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, j.JourneyID, stopsJSON)
			s.audit(ctx, sess, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": "add_stop", "locationId": locationID})
		case "remove_stop":
			stopID, _ := body.Changes["stopId"].(string)
			stops := []map[string]any{}
			removed := false
			for _, st := range j.Stops {
				if st["stopId"] == stopID {
					if st["stopType"] != "handoff" {
						return 409, nil, errOf(409, "invalid_stop", "only unfinished handoff stops may be removed")
					}
					removed = true
					continue
				}
				stops = append(stops, st)
			}
			if !removed {
				return 400, nil, errOf(400, "invalid_stop", "stopId not found in this journey")
			}
			for i, st := range stops {
				st["sequence"] = i
			}
			stopsJSON, _ := json.Marshal(stops)
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET stops=$2, plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, j.JourneyID, stopsJSON)
			s.audit(ctx, sess, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": "remove_stop", "stopId": stopID})
		case "reorder_stops":
			ids := strSlice(body.Changes["stopIds"])
			if len(ids) != len(j.Stops) {
				return 400, nil, errOf(400, "invalid_stop_order", "stopIds must reorder every stop of the journey")
			}
			byID := map[string]map[string]any{}
			for _, st := range j.Stops {
				id, _ := st["stopId"].(string)
				byID[id] = st
			}
			stops := []map[string]any{}
			for i, id := range ids {
				st, ok := byID[id]
				if !ok {
					return 400, nil, errOf(400, "invalid_stop_order", "stopIds must reorder every stop of the journey")
				}
				if i == 0 && st["stopType"] != "pickup" {
					return 409, nil, errOf(409, "invalid_stop_order", "the pickup stop must remain first")
				}
				if i == len(ids)-1 && st["stopType"] != "delivery" {
					return 409, nil, errOf(409, "invalid_stop_order", "the delivery stop must remain last")
				}
				st["sequence"] = i
				stops = append(stops, st)
			}
			stopsJSON, _ := json.Marshal(stops)
			_, _ = s.db.Exec(ctx, `UPDATE journeys SET stops=$2, plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1`, j.JourneyID, stopsJSON)
			s.audit(ctx, sess, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": "reorder_stops"})
		case "reroute", "replace_route":
			replacementID, status, aerr := s.replanJourney(ctx, sess, j.JourneyID)
			if aerr != nil {
				return aerr.HTTPStatus, nil, aerr
			}
			if status == "exception" {
				return 409, nil, errOf(409, "no_valid_route", "no valid route is available for the remaining work")
			}
			if status == "expired" {
				return 409, nil, errOf(409, "deadline_exceeded", "no route can meet the delivery deadline")
			}
			if replacementID != "" {
				rj, _ := loadJourney(ctx, s.db, replacementID)
				return 201, s.journeyPlanJSON(ctx, rj), nil
			}
		case "cancel_work":
			s.cancelJourneyInternal(ctx, sess, j, "dispatcher edit", JourneyCancelled)
			for _, sid := range journeySampleIDs(ctx, s.db, j.JourneyID) {
				s.setSampleStatus(ctx, sess, sid, SampleCancelled, map[string]any{"journeyId": j.JourneyID})
			}
			s.audit(ctx, sess, "edit_active_plan", "journey", j.JourneyID, true, map[string]any{"changeType": "cancel_work"})
			j, _ = loadJourney(ctx, s.db, j.JourneyID)
			return 201, s.journeyPlanJSON(ctx, j), nil
		default:
			return 400, nil, errOf(400, "invalid_change_type", "unsupported changeType")
		}
		_, _ = s.db.Exec(ctx, `UPDATE journeys SET plan_version=plan_version+1, updated_at=now() WHERE journey_id=$1 AND status IN ('planned','in_progress')`, j.JourneyID)
		s.emit(ctx, "journey_updated", "journey", j.JourneyID, map[string]any{"journeyId": j.JourneyID}, "", "")
		j, _ = loadJourney(ctx, s.db, j.JourneyID)
		return 201, s.journeyPlanJSON(ctx, j), nil
	})
}

