func (s *server) serveMapAsset(w http.ResponseWriter, r *http.Request) {
	name := filepath.Base(filepath.Clean(r.URL.Path))
	if name == "." || name == "/" || name == "" {
		http.NotFound(w, r)
		return
	}
	full := filepath.Join(s.mapAssets, name)
	if _, err := os.Stat(full); err != nil {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Access-Control-Allow-Origin", "*")
	http.ServeFile(w, r, full)
}

