package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"strings"
	"syscall"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

type server struct {
	db        *pgxpool.Pool
	hub       *eventHub
	static    string
	mapAssets string
}

func main() {
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgres://agent:agent@127.0.0.1:5432/labpickup?sslmode=disable"
	}
	ctx := context.Background()
	db, err := connectDB(ctx, dbURL)
	if err != nil {
		log.Fatalf("database unavailable: %v", err)
	}
	if err := migrate(ctx, db); err != nil {
		log.Fatalf("migration failed: %v", err)
	}
	if os.Getenv("MIGRATE_ONLY") == "1" {
		log.Printf("migrations applied; exiting (MIGRATE_ONLY=1)")
		return
	}
	s := &server{db: db, hub: newEventHub(), static: os.Getenv("STATIC_DIR")}
	if s.static == "" {
		s.static = "/workspace/web/dist"
	}
	s.mapAssets = os.Getenv("MAP_ASSETS_DIR")
	if s.mapAssets == "" {
		s.mapAssets = "/workspace/map-assets"
	}
	if err := s.ensureFirstAdmin(ctx, os.Getenv("ADMIN_USERNAME"), os.Getenv("ADMIN_PASSWORD")); err != nil {
		log.Fatalf("initial admin failed: %v", err)
	}
	sweepCtx, stopSweep := context.WithCancel(context.Background())
	defer stopSweep()
	go s.offerSweeper(sweepCtx)

	mux := http.NewServeMux()
	mux.HandleFunc("POST /api/accept-assignment", s.handleAcceptAssignment)
	mux.HandleFunc("POST /api/authenticate-user", s.handleAuthenticate)
	mux.HandleFunc("POST /api/cancel-journey", s.handleCancelJourney)
	mux.HandleFunc("POST /api/check-serviceability", s.handleCheckServiceability)
	mux.HandleFunc("POST /api/collect-and-seal-sample", s.handleCollectAndSeal)
	mux.HandleFunc("POST /api/configure-capacity", s.handleConfigureCapacity)
	mux.HandleFunc("POST /api/configure-laboratory-acceptance", s.handleConfigureLaboratoryAcceptance)
	mux.HandleFunc("POST /api/confirm-handoff", s.handleConfirmHandoff)
	mux.HandleFunc("POST /api/confirm-laboratory-receipt", s.handleConfirmLaboratoryReceipt)
	mux.HandleFunc("POST /api/create-collection-request", s.handleCreateCollectionRequest)
	mux.HandleFunc("POST /api/create-connection", s.handleCreateConnection)
	mux.HandleFunc("POST /api/create-location", s.handleCreateLocation)
	mux.HandleFunc("POST /api/create-sample-type", s.handleCreateSampleType)
	mux.HandleFunc("POST /api/create-user", s.handleCreateUser)
	mux.HandleFunc("POST /api/decline-assignment", s.handleDeclineAssignment)
	mux.HandleFunc("POST /api/edit-active-plan", s.handleEditActivePlan)
	mux.HandleFunc("GET /api/events", s.handleEvents)
	mux.HandleFunc("POST /api/ingest-presealed-sample", s.handleIngestPresealed)
	mux.HandleFunc("POST /api/initiate-handoff", s.handleInitiateHandoff)
	mux.HandleFunc("POST /api/list-role-work", s.handleListRoleWork)
	mux.HandleFunc("POST /api/merge-journeys", s.handleMergeJourneys)
	mux.HandleFunc("POST /api/read-journey-plan", s.handleReadJourneyPlan)
	mux.HandleFunc("POST /api/read-operations-state", s.handleReadOperationsState)
	mux.HandleFunc("POST /api/read-sample-lifecycle", s.handleReadSampleLifecycle)
	mux.HandleFunc("GET /api/read-sample-state/{sampleId}", s.handleReadSampleState)
	mux.HandleFunc("POST /api/read-serviceability-snapshot", s.handleReadServiceabilitySnapshot)
	mux.HandleFunc("GET /api/read-user/{userId}", s.handleReadUser)
	mux.HandleFunc("POST /api/record-handling-checkpoint", s.handleRecordHandlingCheckpoint)
	mux.HandleFunc("POST /api/record-laboratory-exception", s.handleRecordLaboratoryException)
	mux.HandleFunc("POST /api/record-worker-location", s.handleRecordWorkerLocation)
	mux.HandleFunc("POST /api/report-disruption", s.handleReportDisruption)
	mux.HandleFunc("POST /api/reroute-journey", s.handleRerouteJourney)
	mux.HandleFunc("POST /api/search-audit-trail", s.handleSearchAuditTrail)
	mux.HandleFunc("POST /api/select-active-role", s.handleSelectRole)
	mux.HandleFunc("POST /api/set-connection-status", s.handleSetConnectionStatus)
	mux.HandleFunc("POST /api/set-location-function-status", s.handleSetLocationFunctionStatus)
	mux.HandleFunc("POST /api/set-location-status", s.handleSetLocationStatus)
	mux.HandleFunc("POST /api/set-worker-availability", s.handleSetWorkerAvailability)
	mux.HandleFunc("POST /api/split-journey", s.handleSplitJourney)
	mux.HandleFunc("GET /api/ui/bootstrap", s.handleBootstrap)
	mux.HandleFunc("POST /api/update-assignment-progress", s.handleUpdateAssignmentProgress)
	mux.HandleFunc("POST /api/update-location", s.handleUpdateLocation)
	mux.HandleFunc("POST /api/update-sample-type", s.handleUpdateSampleType)
	mux.HandleFunc("POST /api/update-user-access", s.handleUpdateUserAccess)

	mux.HandleFunc("GET /ready", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if err := s.db.Ping(r.Context()); err != nil {
			w.WriteHeader(http.StatusServiceUnavailable)
			_, _ = w.Write([]byte(`{"status":"starting"}`))
			return
		}
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte(`{"status":"ready"}`))
	})
	mux.HandleFunc("GET /map-assets/", s.serveMapAsset)
	mux.HandleFunc("/", s.serveStatic)

	addr := os.Getenv("ADDR")
	if addr == "" {
		addr = "127.0.0.1:8080"
	}
	httpServer := &http.Server{Addr: addr, Handler: mux}
	go func() {
		sig := make(chan os.Signal, 1)
		signal.Notify(sig, syscall.SIGINT, syscall.SIGTERM)
		<-sig
		stopSweep()
		ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		_ = httpServer.Shutdown(ctx)
	}()
	log.Printf("listening on %s", addr)
	if err := httpServer.ListenAndServe(); err != nil && err != http.ErrServerClosed {
		log.Fatalf("server failed: %v", err)
	}
}

func (s *server) serveMapAsset(w http.ResponseWriter, r *http.Request) {
	name := filepath.Base(filepath.Clean(r.URL.Path))
	if name == "." || name == "/" || name == "" {
		http.NotFound(w, r)
		return
	}
	full := filepath.Join(s.mapAssets, name)
	if _, err := os.Stat(full); err != nil {
		http.NotFound(w, r)
		return
	}
	w.Header().Set("Access-Control-Allow-Origin", "*")
	http.ServeFile(w, r, full)
}

func (s *server) serveStatic(w http.ResponseWriter, r *http.Request) {
	if strings.HasPrefix(r.URL.Path, "/api/") {
		http.NotFound(w, r)
		return
	}
	p := filepath.Clean(r.URL.Path)
	if p == "/" || p == "." {
		p = "/index.html"
	}
	full := filepath.Join(s.static, p)
	if !strings.HasPrefix(full, filepath.Clean(s.static)) {
		http.NotFound(w, r)
		return
	}
	if info, err := os.Stat(full); err != nil || info.IsDir() {
		full = filepath.Join(s.static, "index.html")
		if _, err := os.Stat(full); err != nil {
			http.NotFound(w, r)
			return
		}
	}
	http.ServeFile(w, r, full)
}

