action.file_text:
:root {
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  color: #0f172a;
  background: #f1f5f9;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

button {
  font: inherit;
  cursor: pointer;
  border: 1px solid #cbd5e1;
  background: #ffffff;
  border-radius: 6px;
  padding: 6px 14px;
}

button.primary {
  background: #2563eb;
  border-color: #2563eb;
  color: #ffffff;
}

button.danger {
  background: #dc2626;
  border-color: #dc2626;
  color: #ffffff;
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

input,
select {
  font: inherit;
  padding: 6px 8px;
  border: 1px solid #cbd5e1;
  border-radius: 6px;
  background: #ffffff;
}

label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 4px;
}

.field {
  margin-bottom: 12px;
}

.card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 16px;
  margin-bottom: 16px;
}

.alert {
  border-radius: 6px;
  padding: 10px 14px;
  margin: 10px 0;
  font-size: 14px;
}

.alert.error {
  background: #fef2f2;
  border: 1px solid #fecaca;
  color: #b91c1c;
}

.alert.success {
  background: #f0fdf4;
  border: 1px solid #bbf7d0;
  color: #15803d;
}

.alert.info {
  background: #eff6ff;
  border: 1px solid #bfdbfe;
  color: #1d4ed8;
}

.badge {
  display: inline-block;
  border-radius: 999px;
  padding: 2px 10px;
  font-size: 12px;
  font-weight: 600;
  margin-left: 8px;
}

.badge.stale {
  background: #fef3c7;
  color: #b45309;
}

.badge.fresh {
  background: #dcfce7;
  color: #15803d;
}

.badge.exception {
  background: #fee2e2;
  color: #b91c1c;
}

.badge.status {
  background: #e0e7ff;
  color: #3730a3;
}

table {
  border-collapse: collapse;
  width: 100%;
  font-size: 13px;
}

th,
td {
  text-align: left;
  padding: 6px 10px;
  border-bottom: 1px solid #e2e8f0;
  vertical-align: top;
}

th {
  background: #f8fafc;
  font-weight: 600;
}

.tabs {
  display: flex;
  gap: 4px;
  border-bottom: 2px solid #e2e8f0;
  margin-bottom: 16px;
  flex-wrap: wrap;
}

.tabs button {
  border: none;
  border-radius: 6px 6px 0 0;
  background: transparent;
  padding: 10px 16px;
  font-weight: 600;
  color: #475569;
}

.tabs button.active {
  background: #ffffff;
  color: #1d4ed8;
  box-shadow: inset 0 -2px 0 #1d4ed8;
}

.timeline {
  list-style: none;
  padding: 0;
  margin: 0;
}

.timeline li {
  border-left: 3px solid #cbd5e1;
  padding: 6px 0 6px 12px;
  margin-left: 6px;
  font-size: 13px;
}

.timeline li.failure {
  border-left-color: #dc2626;
}

.muted {
  color: #64748b;
  font-size: 12px;
}

.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 12px;
}

.stat {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
  padding: 14px;
}

.stat .num {
  font-size: 26px;
  font-weight: 700;
}

.row {
  display: flex;
  gap: 12px;
  flex-wrap: wrap;
  align-items: flex-end;
}

.row .field {
  margin-bottom: 0;
}

