import { useCallback, useEffect, useState } from "react";
import { api, getToken, setToken, ApiRequestError } from "./api";
import type { Bootstrap, Role, User } from "./types";
import { ROLE_LABELS } from "./types";
import { WorkView } from "./views/work";
import { SampleView } from "./views/sample";
import { RequesterView } from "./views/requester";
import { MonitorView, AuditView } from "./views/monitor";
import { AdminView, LabView } from "./views/admin";

type Tab =
  | "work"
  | "samples"
  | "request"
  | "laboratory"
  | "monitor"
  | "audit"
  | "admin";

function Login({ onLogin }: { onLogin: () => void }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setBusy(true);
    try {
      const res = await api.post<{ data: { sessionToken: string } }>(
        "/api/authenticate-user",
        { username, password },
      );
      setToken(res.data.sessionToken);
      onLogin();
    } catch (err) {
      if (err instanceof ApiRequestError) setError(err.message);
      else setError("Sign-in failed. Please try again.");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div style={{ maxWidth: 380, margin: "80px auto" }}>
      <div className="card">
        <h1 style={{ fontSize: 20 }}>Lab Sample Pickup &amp; Delivery</h1>
        <p className="muted">Sign in to continue</p>
        <form onSubmit={submit}>
          <div className="field">
            <label htmlFor="login-username">Username</label>
            <input
              id="login-username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              autoComplete="username"
              style={{ width: "100%" }}
            />
          </div>
          <div className="field">
            <label htmlFor="login-password">Password</label>
            <input
              id="login-password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete="current-password"
              style={{ width: "100%" }}
            />
          </div>
          {error && (
            <div className="alert error" role="alert">
              {error}
            </div>
          )}
          <button className="primary" type="submit" disabled={busy} style={{ width: "100%" }}>
            Sign in
          </button>
        </form>
      </div>
    </div>
  );
}

export default function App() {
  const [user, setUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<Role | null>(null);
  const [tab, setTab] = useState<Tab>("work");
  const [loading, setLoading] = useState(true);
  const [authError, setAuthError] = useState<string | null>(null);
  const [sampleFocus, setSampleFocus] = useState<string | null>(null);

  const loadBootstrap = useCallback(async () => {
    try {
      const res = await api.get<{ data: Bootstrap }>("/api/ui/bootstrap");
      const u = res.data.user;
      setUser(u);
      setActiveRole((u.activeRole as Role) ?? u.roles[0] ?? null);
      setAuthError(null);
    } catch (err) {
      if (err instanceof ApiRequestError && err.status === 401) {
        setToken(null);
        setUser(null);
      } else {
        setAuthError("Could not load session. Is the server running?");
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (getToken()) void loadBootstrap();
    else setLoading(false);
  }, [loadBootstrap]);

  const switchRole = async (role: Role) => {
    try {
      await api.post("/api/select-active-role", { role });
      setActiveRole(role);
      setTab("work");
    } catch (err) {
      if (err instanceof ApiRequestError) setAuthError(err.message);
    }
  };

  const signOut = () => {
    setToken(null);
    setUser(null);
    setActiveRole(null);
    setTab("work");
  };

  const openSample = (sampleId: string) => {
    setSampleFocus(sampleId);
    setTab("samples");
  };

  if (loading) return <p style={{ padding: 24 }}>Loading…</p>;
  if (!user) return <Login onLogin={loadBootstrap} />;

  const role = activeRole ?? user.roles[0];
  const tabs: { id: Tab; label: string }[] = [
    { id: "work", label: "My work" },
    { id: "samples", label: "Samples" },
  ];
  if (role === "requester") tabs.push({ id: "request", label: "New request" });
  if (role === "laboratory_intake_operator") tabs.push({ id: "laboratory", label: "Laboratory" });
  if (role === "dispatcher" || role === "administrator") {
    tabs.push({ id: "monitor", label: "Monitor" });
    tabs.push({ id: "audit", label: "Audit" });
  }
  if (role === "administrator") tabs.push({ id: "admin", label: "Administration" });

  return (
    <div style={{ maxWidth: 1100, margin: "0 auto", padding: 16 }}>
      <header
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexWrap: "wrap",
          gap: 12,
          marginBottom: 16,
        }}
      >
        <div>
          <h1 style={{ fontSize: 20, margin: 0 }}>Lab Sample Pickup &amp; Delivery</h1>
          <span className="muted">
            Signed in as {user.displayName ?? user.username}
          </span>
        </div>
        <div className="row">
          <div className="field">
            <label htmlFor="active-role">Active role</label>
            <select
              id="active-role"
              value={role ?? ""}
              onChange={(e) => void switchRole(e.target.value as Role)}
            >
              {user.roles.map((r) => (
                <option key={r} value={r}>
                  {ROLE_LABELS[r] ?? r}
                </option>
              ))}
            </select>
          </div>
          <button onClick={signOut}>Sign out</button>
        </div>
      </header>

      {authError && (
        <div className="alert error" role="alert">
          {authError}
        </div>
      )}

      <nav className="tabs" aria-label="Main views">
        {tabs.map((t) => (
          <button
            key={t.id}
            className={tab === t.id ? "active" : ""}
            onClick={() => setTab(t.id)}
          >
            {t.label}
          </button>
        ))}
      </nav>

      <main>
        {tab === "work" && role && <WorkView role={role} onOpenSample={openSample} />}
        {tab === "samples" && (
          <SampleView focusSampleId={sampleFocus} onConsumeFocus={() => setSampleFocus(null)} />
        )}
        {tab === "request" && <RequesterView onCreated={openSample} />}
        {tab === "laboratory" && <LabView user={user} />}
        {tab === "monitor" && <MonitorView onOpenSample={openSample} />}
        {tab === "audit" && <AuditView />}
        {tab === "admin" && <AdminView />}
      </main>
    </div>
  );
}

