          <div className="field">
            <label htmlFor="login-password">Password</label>
            <input
              id="login-password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete="current-password"
              style={{ width: "100%" }}
            />
          </div>
          {error && (
            <div className="alert error" role="alert">
              {error}
            </div>
          )}
          <button className="primary" type="submit" disabled={busy} style={{ width: "100%" }}>
            Sign in
          </button>
        </form>
      </div>
    </div>
  );
}

export default function App() {
  const [user, setUser] = useState<User | null>(null);
  const [activeRole, setActiveRole] = useState<Role | null>(null);
  const [tab, setTab] = useState<Tab>("work");
  const [loading, setLoading] = useState(true);
  const [authError, setAuthError] = useState<string | null>(null);
  const [sampleFocus, setSampleFocus] = useState<string | null>(null);

  const loadBootstrap = useCallback(async () => {
    try {
      const res = await api.get<{ data: Bootstrap }>("/api/ui/bootstrap");
      const u = res.data.user;
      setUser(u);
      setActiveRole((u.activeRole as Role) ?? u.roles[0] ?? null);
      setAuthError(null);
    } catch (err) {
      if (err instanceof ApiRequestError && err.status === 401) {
        setToken(null);
        setUser(null);
      } else {
        setAuthError("Could not load session. Is the server running?");
      }
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (getToken()) void loadBootstrap();
    else setLoading(false);
  }, [loadBootstrap]);

  const switchRole = async (role: Role) => {
    try {
      await api.post("/api/select-active-role", { role });
      setActiveRole(role);
      setTab("work");
    } catch (err) {
      if (err instanceof ApiRequestError) setAuthError(err.message);
    }
  };

  const signOut = () => {
    setToken(null);
    setUser(null);
    setActiveRole(null);
    setTab("work");
  };

  const openSample = (sampleId: string) => {
    setSampleFocus(sampleId);
    setTab("samples");
  };

  if (loading) return <p style={{ padding: 24 }}>Loading…</p>;
  if (!user) return <Login onLogin={loadBootstrap} />;

  const role = activeRole ?? user.roles[0];
  const tabs: { id: Tab; label: string }[] = [
    { id: "work", label: "My work" },
    { id: "samples", label: "Samples" },
  ];
  if (role === "requester") tabs.push({ id: "request", label: "New request" });
  if (role === "laboratory_intake_operator") tabs.push({ id: "laboratory", label: "Laboratory" });
  if (role === "dispatcher" || role === "administrator") {
    tabs.push({ id: "monitor", label: "Monitor" });
    tabs.push({ id: "audit", label: "Audit" });
  }
  if (role === "administrator") tabs.push({ id: "admin", label: "Administration" });

  return (
    <div style={{ maxWidth: 1100, margin: "0 auto", padding: 16 }}>
      <header
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          flexWrap: "wrap",
          gap: 12,
          marginBottom: 16,
        }}
      >
        <div>
          <h1 style={{ fontSize: 20, margin: 0 }}>Lab Sample Pickup &amp; Delivery</h1>
          <span className="muted">
            Signed in as {user.displayName ?? user.username}
          </span>
        </div>
        <div className="row">
          <div className="field">
            <label htmlFor="active-role">Active role</label>
            <select
              id="active-role"
              value={role ?? ""}
              onChange={(e) => void switchRole(e.target.value as Role)}
            >
              {user.roles.map((r) => (
                <option key={r} value={r}>
                  {ROLE_LABELS[r] ?? r}
                </option>
              ))}
            </select>
          </div>
          <button onClick={signOut}>Sign out</button>
        </div>
      </header>

      {authError && (
        <div className="alert error" role="alert">
          {authError}
        </div>
      )}

      <nav className="tabs" aria-label="Main views">
        {tabs.map((t) => (
          <button
            key={t.id}
            className={tab === t.id ? "active" : ""}
            onClick={() => setTab(t.id)}
          >
            {t.label}
          </button>
        ))}
      </nav>

      <main>
        {tab === "work" && role && <WorkView role={role} onOpenSample={openSample} />}
        {tab === "samples" && (
          <SampleView focusSampleId={sampleFocus} onConsumeFocus={() => setSampleFocus(null)} />
        )}
        {tab === "request" && <RequesterView onCreated={openSample} />}
        {tab === "laboratory" && <LabView user={user} />}
        {tab === "monitor" && <MonitorView onOpenSample={openSample} />}
        {tab === "audit" && <AuditView />}
        {tab === "admin" && <AdminView />}
      </main>
    </div>
  );
}

