import { useCallback, useEffect, useState } from "react";
import { api, ApiRequestError } from "../api";
import type { JourneyPlan, SampleState, TimelineEntry } from "../types";
import { Timeline } from "./work";

interface Lifecycle {
  sampleId: string;
  currentHolderId?: string;
  custodyHolderId?: string;
  timeline?: TimelineEntry[];
  history?: TimelineEntry[];
  exception?: Record<string, unknown> | null;
}

export function SampleView({
  focusSampleId,
  onConsumeFocus,
}: {
  focusSampleId: string | null;
  onConsumeFocus: () => void;
}) {
  const [sampleId, setSampleId] = useState("");
  const [state, setState] = useState<SampleState | null>(null);
  const [lifecycle, setLifecycle] = useState<Lifecycle | null>(null);
  const [plan, setPlan] = useState<JourneyPlan | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const load = useCallback(async (id: string) => {
    setBusy(true);
    setError(null);
    setState(null);
    setLifecycle(null);
    setPlan(null);
    try {
      const res = await api.get<{ data: SampleState }>(`/api/read-sample-state/${id}`);
      const s = res.data;
      setState(s);
      try {
        const lc = await api.post<{ data: Lifecycle }>("/api/read-sample-lifecycle", {
          sampleId: id,
        });
        setLifecycle(lc.data);
      } catch {
        setLifecycle(null);
      }
      if (s.activeJourneyId) {
        try {
          const jp = await api.post<{ data: JourneyPlan }>("/api/read-journey-plan", {
            journeyId: s.activeJourneyId,
          });
          setPlan(jp.data);
        } catch {
          setPlan(null);
        }
      }
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to load sample");
    } finally {
      setBusy(false);
    }
  }, []);

  useEffect(() => {
    if (focusSampleId) {
      setSampleId(focusSampleId);
      void load(focusSampleId);
      onConsumeFocus();
    }
  }, [focusSampleId, load, onConsumeFocus]);

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (sampleId.trim()) void load(sampleId.trim());
  };

  const status = state?.state?.status ?? state?.status;
  const holder = lifecycle?.currentHolderId ?? lifecycle?.custodyHolderId ?? state?.currentHolderId;
  const exception = state?.exception ?? lifecycle?.exception ?? null;
  const timeline = lifecycle?.timeline ?? lifecycle?.history ?? state?.timeline ?? [];
  const legs = plan?.legs ?? [];
  const completedLegs = legs.filter((l) => l.status === "completed").length;

  return (
    <div>
      <form onSubmit={submit} className="row" style={{ marginBottom: 16 }}>
        <div className="field">
          <label htmlFor="sample-id">Sample ID</label>
          <input
            id="sample-id"
            value={sampleId}
            onChange={(e) => setSampleId(e.target.value)}
            placeholder="00000000-0000-0000-0000-000000000000"
            style={{ width: 340 }}
          />
        </div>
        <button type="submit" className="primary" disabled={busy}>
          Load sample
        </button>
      </form>

      {error && (
        <div className="alert error" role="alert">
          {error}
        </div>
      )}

      {state && (
        <div className="card">
          <h2 style={{ marginTop: 0, fontSize: 17 }}>
            Sample {state.sampleId}
            {status && <span className="badge status">{status}</span>}
            {exception && <span className="badge exception">Exception</span>}
            {state.locationStale ? (
              <span className="badge stale">Stale</span>
            ) : (
              <span className="badge fresh">Fresh</span>
            )}
          </h2>
          <table>
            <tbody>
              <tr>
                <th>Status</th>
                <td>{status ?? "—"}</td>
              </tr>
              <tr>
                <th>Serviceability</th>
                <td>{state.serviceability}</td>
              </tr>
              <tr>
                <th>Current custodian</th>
                <td>{holder ?? "—"}</td>
              </tr>
              <tr>
                <th>Last known location</th>
                <td>
                  {state.latestLocation
                    ? `${state.latestLocation.lat}, ${state.latestLocation.lng}`
                    : "—"}
                </td>
              </tr>
              <tr>
                <th>Last update</th>
                <td>
                  {state.locationRecordedAt
                    ? new Date(state.locationRecordedAt).toLocaleString()
                    : "—"}
                </td>
              </tr>
              <tr>
                <th>Delivery deadline</th>
                <td>{new Date(state.deliveryDeadline).toLocaleString()}</td>
              </tr>
              <tr>
                <th>Origin</th>
                <td>
                  {state.originType} ({state.origin.lat}, {state.origin.lng})
                </td>
              </tr>
            </tbody>
          </table>

          {exception && (
            <div className="alert error" role="alert">
              Exception: {JSON.stringify(exception)}
            </div>
          )}

          {plan && (
            <section aria-label="Route progress" style={{ marginTop: 12 }}>
              <h3 style={{ fontSize: 15 }}>Route progress</h3>
              <p>
                Journey {plan.journeyId} · plan v{plan.planVersion} · {plan.routeMode} ·{" "}
                {completedLegs}/{legs.length} legs completed
              </p>
              {plan.orderedStops && plan.orderedStops.length > 0 && (
                <ol>
                  {plan.orderedStops.map((s) => (
                    <li key={s.stopId}>
                      {s.stopType} @ {s.locationId} — est.{" "}
                      {new Date(s.estimatedAt).toLocaleString()}
                      {s.completedAt
                        ? ` · completed ${new Date(s.completedAt).toLocaleString()}`
                        : ""}
                    </li>
                  ))}
                </ol>
              )}
            </section>
          )}

          <section aria-label="Sample timeline" style={{ marginTop: 12 }}>
            <h3 style={{ fontSize: 15 }}>Timeline</h3>
            <Timeline entries={timeline} />
          </section>
        </div>
      )}
    </div>
  );
}

