import { useCallback, useEffect, useState } from "react";
import { api, ApiRequestError } from "../api";
import type { OperationsLocation, OperationsState, Role, User } from "../types";
import { ROLE_LABELS } from "../types";

const ALL_ROLES: Role[] = [
  "requester",
  "certified_collection_professional",
  "relay_courier",
  "node_handler",
  "laboratory_intake_operator",
  "dispatcher",
  "administrator",
];

function CreateUserForm() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [fullName, setFullName] = useState("");
  const [roles, setRoles] = useState<Role[]>(["requester"]);
  const [msg, setMsg] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const toggle = (r: Role) =>
    setRoles((rs) => (rs.includes(r) ? rs.filter((x) => x !== r) : [...rs, r]));

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setMsg(null);
    setError(null);
    try {
      await api.post("/api/create-user", {
        username,
        initialPassword: password,
        fullName,
        roles,
        active: true,
      });
      setMsg(`User ${username} created`);
      setUsername("");
      setPassword("");
      setFullName("");
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to create user");
    }
  };

  return (
    <form onSubmit={(e) => void submit(e)}>
      <div className="row">
        <div className="field">
          <label htmlFor="cu-username">Username</label>
          <input id="cu-username" value={username} onChange={(e) => setUsername(e.target.value)} required />
        </div>
        <div className="field">
          <label htmlFor="cu-password">Initial password</label>
          <input
            id="cu-password"
            type="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
        </div>
        <div className="field">
          <label htmlFor="cu-name">Full name</label>
          <input id="cu-name" value={fullName} onChange={(e) => setFullName(e.target.value)} />
        </div>
      </div>
      <fieldset style={{ border: "1px solid #e2e8f0", borderRadius: 6, margin: "12px 0" }}>
        <legend className="muted">Roles</legend>
        {ALL_ROLES.map((r) => (
          <label key={r} style={{ display: "inline-flex", gap: 4, marginRight: 12, fontWeight: 400 }}>
            <input type="checkbox" checked={roles.includes(r)} onChange={() => toggle(r)} />
            {ROLE_LABELS[r]}
          </label>
        ))}
      </fieldset>
      <button className="primary" type="submit">
        Create user
      </button>
      {msg && (
        <div className="alert success" role="status">
          {msg}
        </div>
      )}
      {error && (
        <div className="alert error" role="alert">
          {error}
        </div>
      )}
    </form>
  );
}

function CreateLocationForm() {
  const [name, setName] = useState("");
  const [lat, setLat] = useState("");
  const [lng, setLng] = useState("");
  const [fns, setFns] = useState<string[]>(["collection"]);
  const [msg, setMsg] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const FUNCTIONS = ["collection", "transfer", "hub", "laboratory"];
  const toggle = (f: string) =>
    setFns((xs) => (xs.includes(f) ? xs.filter((x) => x !== f) : [...xs, f]));

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setMsg(null);
    setError(null);
    try {
      await api.post("/api/create-location", {
        name,
        coordinate: { lat: Number(lat), lng: Number(lng) },
        active: true,
        functions: fns,
      });
      setMsg(`Location ${name} created`);
      setName("");
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to create location");
    }
  };

  return (
    <form onSubmit={(e) => void submit(e)}>
      <div className="row">
        <div className="field">
          <label htmlFor="cl-name">Name</label>
          <input id="cl-name" value={name} onChange={(e) => setName(e.target.value)} required />
        </div>
        <div className="field">
          <label htmlFor="cl-lat">Latitude</label>
          <input id="cl-lat" value={lat} onChange={(e) => setLat(e.target.value)} required inputMode="decimal" />
        </div>
        <div className="field">
          <label htmlFor="cl-lng">Longitude</label>
          <input id="cl-lng" value={lng} onChange={(e) => setLng(e.target.value)} required inputMode="decimal" />
        </div>
      </div>
      <fieldset style={{ border: "1px solid #e2e8f0", borderRadius: 6, margin: "12px 0" }}>
        <legend className="muted">Functions</legend>
        {FUNCTIONS.map((f) => (
          <label key={f} style={{ display: "inline-flex", gap: 4, marginRight: 12, fontWeight: 400 }}>
            <input type="checkbox" checked={fns.includes(f)} onChange={() => toggle(f)} />
            {f}
          </label>
        ))}
      </fieldset>
      <button className="primary" type="submit">
