import { useEffect, useRef } from "react";
import maplibregl from "maplibre-gl";
import "maplibre-gl/dist/maplibre-gl.css";
import { Protocol } from "pmtiles";
import type { Coordinate } from "./types";

export interface MapMarker {
  id: string;
  coordinate: Coordinate;
  kind: "location" | "worker" | "sample" | "laboratory";
  label: string;
}

const MARKER_COLORS: Record<MapMarker["kind"], string> = {
  location: "#2563eb",
  worker: "#059669",
  sample: "#d97706",
  laboratory: "#7c3aed",
};

function markersToGeoJSON(markers: MapMarker[]): GeoJSON.FeatureCollection {
  return {
    type: "FeatureCollection",
    features: markers.map((m) => ({
      type: "Feature",
      geometry: { type: "Point", coordinates: [m.coordinate.lng, m.coordinate.lat] },
      properties: { id: m.id, kind: m.kind, label: m.label, color: MARKER_COLORS[m.kind] },
    })),
  };
}

export function NetworkMap({ markers }: { markers: MapMarker[] }) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<MapMarker[]>(markers);
  markersRef.current = markers;

  useEffect(() => {
    if (!containerRef.current || mapRef.current) return;
    const protocol = new Protocol();
    maplibregl.addProtocol("pmtiles", protocol.tile);
    const map = new maplibregl.Map({
      container: containerRef.current,
      style: {
        version: 8,
        sources: {
          basemap: {
            type: "vector",
            url: "pmtiles:///map-assets/bangalore.pmtiles",
          },
        },
        layers: [
          { id: "background", type: "background", paint: { "background-color": "#eef2f7" } },
          {
            id: "earth",
            type: "fill",
            source: "basemap",
            "source-layer": "earth",
            paint: { "fill-color": "#f8fafc" },
          },
          {
            id: "landuse",
            type: "fill",
            source: "basemap",
            "source-layer": "landuse",
            paint: { "fill-color": "#e2e8f0", "fill-opacity": 0.5 },
          },
          {
            id: "water",
            type: "fill",
            source: "basemap",
            "source-layer": "water",
            paint: { "fill-color": "#bfdbfe" },
          },
          {
            id: "roads",
            type: "line",
            source: "basemap",
            "source-layer": "roads",
            paint: { "line-color": "#94a3b8", "line-width": 1 },
          },
          {
            id: "buildings",
            type: "fill",
            source: "basemap",
            "source-layer": "buildings",
            paint: { "fill-color": "#cbd5e1", "fill-opacity": 0.6 },
          },
          {
            id: "boundaries",
            type: "line",
            source: "basemap",
            "source-layer": "boundaries",
            paint: { "line-color": "#64748b", "line-width": 0.8, "line-dasharray": [2, 2] },
          },
        ],
      },
      center: [77.6, 13.0],
      zoom: 11,
      attributionControl: false,
    });
    map.addControl(new maplibregl.NavigationControl(), "top-right");
    map.on("load", () => {
      map.addSource("markers", {
        type: "geojson",
        data: markersToGeoJSON(markersRef.current),
      });
      map.addLayer({
        id: "markers",
        type: "circle",
        source: "markers",
        paint: {
          "circle-radius": 7,
          "circle-color": ["get", "color"],
          "circle-stroke-color": "#ffffff",
          "circle-stroke-width": 2,
        },
      });
      map.on("click", "markers", (e) => {
        const f = e.features?.[0];
        if (!f) return;
        const c = (f.geometry as GeoJSON.Point).coordinates as [number, number];
        new maplibregl.Popup()
          .setLngLat(c)
          .setText(`${f.properties?.label ?? ""} (${f.properties?.kind ?? ""})`)
          .addTo(map);
      });
      map.on("mouseenter", "markers", () => {
        map.getCanvas().style.cursor = "pointer";
      });
      map.on("mouseleave", "markers", () => {
        map.getCanvas().style.cursor = "";
      });
    });
    mapRef.current = map;
    return () => {
      map.remove();
      mapRef.current = null;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    const update = () => {
      const src = map.getSource("markers") as maplibregl.GeoJSONSource | undefined;
      if (src) src.setData(markersToGeoJSON(markers));
    };
    if (map.isStyleLoaded()) update();
    else map.once("load", update);
  }, [markers]);

  return (
    <div
      ref={containerRef}
      aria-label="Network map"
      role="region"
      style={{ width: "100%", height: 420, borderRadius: 8, overflow: "hidden" }}
    />
  );
}

