import { useCallback, useEffect, useState } from "react";
import { api, newIdempotencyKey, ApiRequestError } from "../api";
import type { Role, RoleWork, TimelineEntry, WorkItem } from "../types";

export function Timeline({ entries }: { entries: TimelineEntry[] }) {
  const ordered = [...entries].sort((a, b) => a.eventId - b.eventId);
  if (ordered.length === 0) return <p className="muted">No history yet.</p>;
  return (
    <ol className="timeline" aria-label="Status timeline">
      {ordered.map((e) => (
        <li key={e.eventId} className={e.success ? "" : "failure"}>
          <strong>{e.action}</strong>{" "}
          <span className="muted">
            {new Date(e.occurredAt).toLocaleString()} · role {e.role || "—"}
            {e.success ? "" : " · failed"}
          </span>
        </li>
      ))}
    </ol>
  );
}

function LocationRecorder({
  assignmentId,
  onDone,
}: {
  assignmentId: string;
  onDone: (msg: string) => void;
}) {
  const [lat, setLat] = useState("");
  const [lng, setLng] = useState("");
  const [seq, setSeq] = useState(1);
  const [error, setError] = useState<string | null>(null);

  const submit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    try {
      await api.post("/api/record-worker-location", {
        assignmentId,
        coordinate: { lat: Number(lat), lng: Number(lng) },
        sequence: seq,
        recordedAt: new Date().toISOString(),
      });
      setSeq(seq + 1);
      onDone(`Location recorded (${lat}, ${lng})`);
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to record location");
    }
  };

  return (
    <form onSubmit={submit} className="row" style={{ marginTop: 8 }}>
      <div className="field">
        <label htmlFor={`lat-${assignmentId}`}>Latitude</label>
        <input
          id={`lat-${assignmentId}`}
          value={lat}
          onChange={(e) => setLat(e.target.value)}
          required
          inputMode="decimal"
        />
      </div>
      <div className="field">
        <label htmlFor={`lng-${assignmentId}`}>Longitude</label>
        <input
          id={`lng-${assignmentId}`}
          value={lng}
          onChange={(e) => setLng(e.target.value)}
          required
          inputMode="decimal"
        />
      </div>
      <button type="submit" className="primary">
        Record location
      </button>
      {error && (
        <div className="alert error" role="alert" style={{ width: "100%" }}>
          {error}
        </div>
      )}
    </form>
  );
}

function WorkItemCard({
  item,
  onOpenSample,
  onAction,
}: {
  item: WorkItem;
  onOpenSample: (id: string) => void;
  onAction: () => void;
}) {
  const [showHistory, setShowHistory] = useState(false);
  const [showLocation, setShowLocation] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const act = async (op: string, body: Record<string, unknown>, ok: string) => {
    setBusy(true);
    setError(null);
    setMessage(null);
    try {
      await api.post(op, body);
      setMessage(ok);
      onAction();
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Action failed");
    } finally {
      setBusy(false);
    }
  };

  const isAssignment = item.kind !== "sample" && item.kind !== "journey" && item.assignmentId;
  const offered = item.status === "offered" || item.status === "pending";
  const accepted = item.status === "accepted" || item.status === "in_progress";

  return (
    <div className="card">
      <div>
        <strong>{item.kind}</strong>
        <span className="badge status">{item.status}</span>
        {item.locationStale && <span className="badge stale">Stale location</span>}
      </div>
      <div className="muted" style={{ margin: "4px 0" }}>
        {item.assignmentId && <span>Assignment {item.assignmentId} · </span>}
        {item.sampleId && <span>Sample {item.sampleId} · </span>}
        {item.journeyId && <span>Journey {item.journeyId}</span>}
        {item.deliveryDeadline && (
          <span> · deadline {new Date(item.deliveryDeadline).toLocaleString()}</span>
        )}
      </div>
      <div className="row">
        {item.sampleId && (
          <button onClick={() => onOpenSample(item.sampleId!)}>View sample</button>
        )}
        {isAssignment && offered && (
          <>
            <button
              className="primary"
              disabled={busy}
              onClick={() =>
                void act(
                  "/api/accept-assignment",
                  { assignmentId: item.assignmentId, idempotencyKey: newIdempotencyKey() },
                  "Assignment accepted",
                )
              }
            >
              Accept assignment
            </button>
            <button
              className="danger"
              disabled={busy}
              onClick={() =>
                void act(
                  "/api/decline-assignment",
                  { assignmentId: item.assignmentId, idempotencyKey: newIdempotencyKey() },
                  "Assignment declined",
                )
              }
            >
              Decline assignment
            </button>
          </>
        )}
        {isAssignment && accepted && (
          <button onClick={() => setShowLocation((v) => !v)}>
            {showLocation ? "Hide location form" : "Record location"}
          </button>
        )}
        <button onClick={() => setShowHistory((v) => !v)}>
          {showHistory ? "Hide history" : "Show history"}
        </button>
      </div>
      {message && (
        <div className="alert success" role="status">
          {message}
        </div>
      )}
      {error && (
        <div className="alert error" role="alert">
          {error}
        </div>
      )}
      {showLocation && item.assignmentId && (
        <LocationRecorder assignmentId={item.assignmentId} onDone={setMessage} />
      )}
      {showHistory && <Timeline entries={item.history ?? []} />}
    </div>
  );
}

export function WorkView({
  role,
  onOpenSample,
}: {
  role: Role;
  onOpenSample: (id: string) => void;
}) {
  const [work, setWork] = useState<RoleWork | null>(null);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const res = await api.post<{ data: RoleWork }>("/api/list-role-work", { role });
      setWork(res.data);
      setError(null);
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to load work");
    }
  }, [role]);

  useEffect(() => {
    setWork(null);
    void load();
  }, [load]);

  if (error)
    return (
      <div className="alert error" role="alert">
        {error}
      </div>
    );
  if (!work) return <p>Loading work…</p>;

  const current = [...(work.pending ?? []), ...(work.inProgress ?? [])];
  const completed = work.completed ?? [];

  return (
    <div>
      <section aria-labelledby="current-work-heading">
        <h2 id="current-work-heading">Current work</h2>
        {current.length === 0 && <p className="muted">No current work for this role.</p>}
        {current.map((item, i) => (
          <WorkItemCard
            key={item.assignmentId ?? item.sampleId ?? item.journeyId ?? i}
            item={item}
            onOpenSample={onOpenSample}
            onAction={load}
          />
        ))}
      </section>
      <section aria-labelledby="completed-work-heading">
        <h2 id="completed-work-heading">Completed work</h2>
        {completed.length === 0 && <p className="muted">No completed work yet.</p>}
        {completed.map((item, i) => (
          <WorkItemCard
            key={item.assignmentId ?? item.sampleId ?? item.journeyId ?? i}
            item={item}
            onOpenSample={onOpenSample}
            onAction={load}
          />
        ))}
      </section>
    </div>
  );
}

