import { useState } from "react";
import { api, newIdempotencyKey, ApiRequestError } from "../api";
import { SAMPLE_TYPES } from "../types";

function toIso(local: string): string {
  return new Date(local).toISOString();
}

interface FormState {
  lat: string;
  lng: string;
  originType: string;
  sampleTypeId: string;
  deliveryDeadline: string;
  earliestCollection: string;
  latestCollection: string;
  containerType: string;
  tempMin: string;
  tempMax: string;
}

const defaultForm = (): FormState => {
  const now = Date.now();
  const toLocal = (t: number) => {
    const d = new Date(t);
    d.setMinutes(d.getMinutes() - d.getTimezoneOffset());
    return d.toISOString().slice(0, 16);
  };
  return {
    lat: "12.9716",
    lng: "77.5946",
    originType: "home",
    sampleTypeId: SAMPLE_TYPES[0].id,
    deliveryDeadline: toLocal(now + 24 * 3600 * 1000),
    earliestCollection: toLocal(now + 3600 * 1000),
    latestCollection: toLocal(now + 4 * 3600 * 1000),
    containerType: "standard",
    tempMin: "2",
    tempMax: "8",
  };
};

export function RequesterView({ onCreated }: { onCreated: (sampleId: string) => void }) {
  const [form, setForm] = useState<FormState>(defaultForm());
  const [checkResult, setCheckResult] = useState<string | null>(null);
  const [checkOk, setCheckOk] = useState<boolean | null>(null);
  const [createMsg, setCreateMsg] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const set = (k: keyof FormState) => (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) =>
    setForm((f) => ({ ...f, [k]: e.target.value }));

  const baseBody = () => ({
    origin: { lat: Number(form.lat), lng: Number(form.lng) },
    originType: form.originType,
    sampleTypeId: form.sampleTypeId,
    deliveryDeadline: toIso(form.deliveryDeadline),
    earliestCollectionAt: toIso(form.earliestCollection),
    latestCollectionAt: toIso(form.latestCollection),
  });

  const check = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setError(null);
    setCheckResult(null);
    setCreateMsg(null);
    try {
      const res = await api.post<{ data: { serviceable: boolean; reason?: string } }>(
        "/api/check-serviceability",
        baseBody(),
      );
      setCheckOk(res.data.serviceable);
      setCheckResult(
        res.data.serviceable
          ? "Serviceable — a laboratory can receive this sample before its deadline."
          : `Not serviceable${res.data.reason ? `: ${res.data.reason}` : ""}`,
      );
    } catch (err) {
      setCheckOk(false);
      setCheckResult(err instanceof ApiRequestError ? err.message : "Serviceability check failed");
    } finally {
      setBusy(false);
    }
  };

  const create = async (e: React.FormEvent) => {
    e.preventDefault();
    setBusy(true);
    setError(null);
    setCreateMsg(null);
    setCheckResult(null);
    try {
      const res = await api.post<{ data: { requestId: string; sampleId: string } }>(
        "/api/create-collection-request",
        {
          ...baseBody(),
          requestedAt: new Date().toISOString(),
          containerType: form.containerType,
          temperatureMinC: Number(form.tempMin),
          temperatureMaxC: Number(form.tempMax),
          idempotencyKey: newIdempotencyKey(),
        },
      );
      setCreateMsg(
        `Request created. Request ${res.data.requestId} · Sample ${res.data.sampleId}`,
      );
      onCreated(res.data.sampleId);
    } catch (err) {
      setError(err instanceof ApiRequestError ? err.message : "Failed to create request");
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="card" style={{ maxWidth: 560 }}>
      <h2 style={{ marginTop: 0, fontSize: 17 }}>New collection request</h2>
      <form>
        <div className="row">
          <div className="field">
            <label htmlFor="req-lat">Origin latitude</label>
            <input id="req-lat" value={form.lat} onChange={set("lat")} required inputMode="decimal" />
          </div>
          <div className="field">
            <label htmlFor="req-lng">Origin longitude</label>
            <input id="req-lng" value={form.lng} onChange={set("lng")} required inputMode="decimal" />
          </div>
          <div className="field">
            <label htmlFor="req-origin-type">Origin type</label>
            <select id="req-origin-type" value={form.originType} onChange={set("originType")}>
              <option value="home">Home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Network node</option>
            </select>
          </div>
        </div>
        <div className="row" style={{ marginTop: 12 }}>
          <div className="field">
            <label htmlFor="req-sample-type">Sample type</label>
            <select id="req-sample-type" value={form.sampleTypeId} onChange={set("sampleTypeId")}>
              {SAMPLE_TYPES.map((t) => (
                <option key={t.id} value={t.id}>
                  {t.name}
                </option>
              ))}
            </select>
          </div>
          <div className="field">
            <label htmlFor="req-container">Container type</label>
            <input id="req-container" value={form.containerType} onChange={set("containerType")} />
          </div>
          <div className="field">
            <label htmlFor="req-tmin">Temp min (°C)</label>
            <input id="req-tmin" value={form.tempMin} onChange={set("tempMin")} inputMode="decimal" />
          </div>
          <div className="field">
            <label htmlFor="req-tmax">Temp max (°C)</label>
            <input id="req-tmax" value={form.tempMax} onChange={set("tempMax")} inputMode="decimal" />
          </div>
        </div>
