}

// eligibleWorkers returns candidate workers for an assignment, best first.
func (s *server) eligibleWorkers(ctx context.Context, a *Assignment, st *SampleType) (eligible []string, anyEligible bool) {
	role := kindRole(a.Kind)
	rows, err := s.db.Query(ctx, `SELECT `+userCols+` FROM users WHERE active=TRUE AND roles ? $1`, role)
	if err != nil {
		return nil, false
	}
	defer rows.Close()
	users := []*User{}
	for rows.Next() {
		u, err := scanUser(rows)
		if err == nil {
			users = append(users, u)
		}
	}
	structural := []*User{}
	for _, u := range users {
		if containsString(a.DeclinedBy, u.UserID) {
			continue
		}
		switch a.Kind {
		case KindCollection:
			if !workerQualified(u, st) {
				continue
			}
		case KindNode:
			if u.AssignedLocationID == nil || a.NodeID == nil || *u.AssignedLocationID != *a.NodeID {
				continue
			}
		case KindLab:
			if u.AssignedLocationID == nil || a.LaboratoryID == nil || *u.AssignedLocationID != *a.LaboratoryID {
				continue
			}
		}
		structural = append(structural, u)
	}
	if len(structural) == 0 {
		return nil, false
	}
	// filter by availability and capacity
	cands := []cand{}
	for _, u := range structural {
		var active int
		_ = s.db.QueryRow(ctx, `SELECT count(*) FROM assignments WHERE accepted_by=$1 AND status IN ('accepted','in_progress')`, u.UserID).Scan(&active)
		if !u.Available || active >= u.CapacityUnits {
			continue
		}
		penalty := u.LastDeclineAt != nil && time.Since(*u.LastDeclineAt) < 30*time.Minute
		cands = append(cands, cand{u: u, active: active, penalty: penalty})
	}
	sortCands(cands)
	out := []string{}
	for _, c := range cands {
		out = append(out, c.u.UserID)
	}
	return out, true
}

type cand struct {
	u       *User
	active  int
	penalty bool
}

func sortCands(cands []cand) {
	for i := 0; i < len(cands); i++ {
		for j := i + 1; j < len(cands); j++ {
			a, b := cands[i], cands[j]
			less := false
			if a.penalty != b.penalty {
				less = !a.penalty
			} else if a.active != b.active {
				less = a.active < b.active
			} else {
				at, bt := a.u.LastAssignedAt, b.u.LastAssignedAt
				switch {
				case at == nil && bt != nil:
					less = true
				case at != nil && bt == nil:
					less = false
				case at != nil && bt != nil:
					less = at.Before(*bt)
				default:
					less = a.u.UserID < b.u.UserID
				}
			}
			if less {
				cands[i], cands[j] = cands[j], cands[i]
			}
		}
	}
}

const offerTimeout = 2 * time.Minute

// offerAssignment offers an assignment to the best eligible worker. Returns
// (offeredTo, noQualifiedWorker, error).
func (s *server) offerAssignment(ctx context.Context, sess *session, a *Assignment) (*string, bool, error) {
	st, err := sampleTypeForSample(ctx, s, a.SampleID)
	if err != nil {
		return nil, false, err
	}
	eligible, anyEligible := s.eligibleWorkers(ctx, a, st)
	if len(eligible) == 0 {
		if !anyEligible {
			return nil, true, nil
		}
		// eligible workers exist but are busy/unavailable; stay pending for the sweeper
		_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, updated_at=now() WHERE assignment_id=$1`, a.AssignmentID)
		return nil, false, nil
	}
	workerID := eligible[0]
	now := nowUTC()
	expires := now.Add(offerTimeout)
	_, err = s.db.Exec(ctx, `UPDATE assignments SET status='offered', offered_to=$2, offered_at=$3, offer_expires_at=$4, updated_at=now()
		WHERE assignment_id=$1`, a.AssignmentID, workerID, now, expires)
	if err != nil {
		return nil, false, err
	}
	_, _ = s.db.Exec(ctx, `UPDATE users SET last_assigned_at=$2 WHERE user_id=$1`, workerID, now)
	s.audit(ctx, sess, "offer_assignment", "assignment", a.AssignmentID, true,
		map[string]any{"workerId": workerID, "kind": a.Kind, "sampleId": a.SampleID})
	s.emit(ctx, "assignment_offered", "assignment", a.AssignmentID, map[string]any{
		"assignmentId": a.AssignmentID, "workerId": workerID, "kind": a.Kind, "sampleId": a.SampleID,
	}, kindRole(a.Kind), workerID)
	return &workerID, false, nil
}

func sampleTypeForSample(ctx context.Context, s *server, sampleID string) (*SampleType, error) {
	var typeID string
	err := s.db.QueryRow(ctx, `SELECT r.sample_type_id FROM samples sm JOIN requests r ON r.request_id = sm.request_id WHERE sm.sample_id=$1`, sampleID).Scan(&typeID)
	if err != nil {
		return nil, err
	}
	return loadSampleType(ctx, s.db, typeID)
}

// flagNoQualifiedWorker marks a sample with the distinct no-qualified-worker exception.
func (s *server) flagNoQualifiedWorker(ctx context.Context, sess *session, sampleID, assignmentID string) {
	exc := map[string]any{
		"type":         "no_qualified_worker",
		"reason":       "no qualified worker is available for this assignment",
		"assignmentId": assignmentID,
		"observedAt":   fmtTime(nowUTC()),
	}
	excJSON, _ := json.Marshal(exc)
	_, _ = s.db.Exec(ctx, `UPDATE samples SET exception=$2, updated_at=now() WHERE sample_id=$1`, sampleID, excJSON)
	s.setSampleStatus(ctx, sess, sampleID, SampleException, map[string]any{"reason": "no_qualified_worker", "assignmentId": assignmentID})
	s.emit(ctx, "exception_raised", "sample", sampleID, map[string]any{"sampleId": sampleID, "type": "no_qualified_worker"}, "", "")
}

// kickOffers offers all currently-offerable assignments for a journey.
func (s *server) kickOffers(ctx context.Context, sess *session, journeyID string) {
	asgs := journeyAssignments(ctx, s.db, journeyID)
	for _, a := range asgs {
		if a.Status != AsgPending {
			continue
		}
		offerable := false
		switch a.Kind {
		case KindCollection:
			offerable = true
		case KindNode, KindLab:
			offerable = true
		case KindTransport:
			if a.Sequence == 1 {
				// first transport leg: offer once the sample is sealed
				var sealed bool
				_ = s.db.QueryRow(ctx, `SELECT sealed FROM samples WHERE sample_id=$1`, a.SampleID).Scan(&sealed)
				offerable = sealed
			} else {
				// later legs: offer once the preceding node assignment is engaged
				var prevStatus string
				err := s.db.QueryRow(ctx, `SELECT status FROM assignments WHERE journey_id=$1 AND sequence=$2`,
					journeyID, a.Sequence-1).Scan(&prevStatus)
				offerable = err == nil && (prevStatus == AsgAccepted || prevStatus == AsgInProgress || prevStatus == AsgCompleted)
			}
		}
		if !offerable {
			continue
		}
		offeredTo, noQualified, err := s.offerAssignment(ctx, sess, a)
		if err != nil {
			continue
		}
		if noQualified {
			s.flagNoQualifiedWorker(ctx, sess, a.SampleID, a.AssignmentID)
		} else if offeredTo != nil {
			if a.Kind == KindCollection {
				s.setSampleStatus(ctx, sess, a.SampleID, SampleAwaitingCollection, map[string]any{"assignmentId": a.AssignmentID})
			}
		}
	}
}

// offerSweeper periodically expires unanswered offers and retries pending ones.
func (s *server) offerSweeper(ctx context.Context) {
	ticker := time.NewTicker(10 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
		// expire offers
		rows, err := s.db.Query(ctx, `SELECT assignment_id FROM assignments WHERE status='offered' AND offer_expires_at < now()`)
		if err == nil {
			ids := []string{}
			for rows.Next() {
				var id string
				_ = rows.Scan(&id)
				ids = append(ids, id)
			}
			rows.Close()
			for _, id := range ids {
				a, err := loadAssignment(ctx, s.db, id)
				if err != nil || a.OfferedTo == nil {
					continue
				}
				declined := append(a.DeclinedBy, *a.OfferedTo)
				dj, _ := json.Marshal(declined)
				_, _ = s.db.Exec(ctx, `UPDATE assignments SET status='pending', offered_to=NULL, offer_expires_at=NULL, declined_by=$2, updated_at=now()
					WHERE assignment_id=$1`, id, dj)
				_, _ = s.db.Exec(ctx, `UPDATE users SET recent_declines = recent_declines + 1, last_decline_at=now() WHERE user_id=$1`, *a.OfferedTo)
				s.audit(ctx, nil, "offer_expired", "assignment", id, true, map[string]any{"workerId": *a.OfferedTo})
			}
		}
		// retry pending assignments on active journeys
		jrows, err := s.db.Query(ctx, `SELECT DISTINCT journey_id FROM assignments a JOIN journeys j ON j.journey_id=a.journey_id
			WHERE a.status='pending' AND j.status IN ('planned','in_progress')`)
		if err == nil {
			jids := []string{}
			for jrows.Next() {
				var id string
				_ = jrows.Scan(&id)
				jids = append(jids, id)
			}
			jrows.Close()
			for _, jid := range jids {
				s.kickOffers(ctx, nil, jid)
			}
		}
	}
}

